 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',1,'Introduction à l''unicité d''Allah (at-Tawḥīd)','Mercredi 2 juillet 2025 – 7 Muḥarram 1447 H',1) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Quel est le but de la création des djinns et des hommes selon le Coran ?','["Peupler la terre","Adorer Allah","Accomplir les cinq piliers","Connaître les savants"]'::jsonb,1,'Allah dit dans la sourate adh-Dhāriyāt, verset 56 : « Je n''ai créé les djinns et les hommes que pour qu''ils M''adorent. »',1),
   (t,c,'facile','Que signifie le mot « Tawḥīd » dans la langue arabe ?','["Associer plusieurs êtres à Allah","Rendre une chose unique, ou le fait qu''une chose soit unique par rapport à d''autres","Accomplir les actes d''adoration obligatoires","Croire aux prophètes et aux livres révélés"]'::jsonb,1,'L''unicité dans la langue arabe signifie : rendre une chose unique, ou le fait qu''une chose soit unique par rapport à d''autres.',2),
   (t,c,'facile','Quel est le contraire du Tawḥīd ?','["Al-Kufr (la mécréance)","Al-Chirk (le polythéisme)","An-Nifāq (l''hypocrisie)","Al-Bid''a (l''innovation)"]'::jsonb,1,'Le polythéisme (al-shirk), qui est l''opposé de l''unicité, consiste à associer à Allah d''autres êtres dans ce qui Lui est exclusivement réservé.',3),
   (t,c,'facile','Combien de catégories comprend le Tawḥīd selon les textes du Coran et de la Sunna ?','["Deux","Trois","Quatre","Cinq"]'::jsonb,1,'Les textes du Coran et de la Sunna montrent que l''unicité d''Allah se divise en trois formes : Tawḥīd ar-Rubūbiyya, Tawḥīd al-Ulūhiyya, et Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt.',4),
   (t,c,'facile','Que désigne le Tawḥīd ar-Rubūbiyya ?','["Vouer exclusivement à Allah tous les actes d''adoration","Croire aux noms et attributs d''Allah","Unifier Allah dans Ses actes tels que la création, la vie et la mort, le pouvoir et l''organisation de l''univers","Reconnaître les cinq piliers de l''Islam"]'::jsonb,2,'Tawḥīd ar-Rubūbiyya : c''est le fait d''unifier Allah dans Ses actes, tels que la création, la vie et la mort, le pouvoir, l''organisation et la gestion de l''univers.',5),
   (t,c,'facile','Que désigne le Tawḥīd al-Ulūhiyya ?','["Unifier Allah dans Sa seigneurie uniquement","Vouer exclusivement à Allah tous les actes d''adoration, apparents ou cachés, par les paroles ou les actes","Croire aux noms et attributs d''Allah sans les déformer","Connaître le nombre des noms d''Allah"]'::jsonb,1,'Tawḥīd al-Ulūhiyya : c''est vouer exclusivement à Allah tous les actes d''adoration : apparents ou cachés, par les paroles ou les actes. Aucune forme d''adoration ne doit être dirigée vers un autre qu''Allah.',6),
   (t,c,'facile','Combien de noms Allah possède-t-Il selon le hadith d''Abū Hurayra mentionné dans ce cours ?','["100 noms","99 noms (cent moins un)","1000 noms","Un seul nom connu"]'::jsonb,1,'Dans le hadith rapporté par Abū Hurayra, le Prophète a dit : « Certes, Allah a 99 noms — cent moins un —, celui qui les recense entrera au Paradis. »',7),
   (t,c,'facile','Quelle est la première obligation religieuse selon le Prophète envoyant Muʿādh au Yémen ?','["La prière","Le jeûne","Réaliser l''unicité d''Allah","La zakāt"]'::jsonb,2,'Le Prophète a dit à Muʿādh : « Tu vas aller à un peuple des Gens du Livre. Informe-les que le premier devoir qui leur incombe est de réaliser l''unicité d''Allah. » Ce qui montre que la connaissance de l''unicité d''Allah est la première obligation religieuse, avant même la prière.',8),
   (t,c,'facile','Que dit Ibn al-Qayyim à propos de la valeur d''une science ?','["La valeur d''une science dépend du nombre de ses étudiants","La valeur d''une science dépend de l''objet qu''elle étudie","La valeur d''une science dépend de l''ancienneté de ses sources","La valeur d''une science dépend de la difficulté de ses règles"]'::jsonb,1,'Ibn al-Qayyim a dit : « La valeur d''une science dépend de l''objet qu''elle étudie. Or il n''y a pas de sujet plus noble que la connaissance d''Allah, de Ses noms, de Ses attributs, et de Ses actions. »',9),
   (t,c,'facile','Qu''est-ce que le Chirk (al-shirk) signifie littéralement ?','["Nier","Associer","Déformer","Ignorer"]'::jsonb,1,'Chirk signifie littéralement : associer. Le polythéisme (al-shirk) consiste à associer à Allah d''autres êtres dans ce qui Lui est exclusivement réservé.',10),
   (t,c,'moyenne','Quelle est la définition religieuse du Tawḥīd selon le Coran et la Sunna ?','["Prononcer la shahāda une seule fois dans sa vie","Unifier Allah dans Ses spécificités et dans les droits qui Lui reviennent exclusivement","Accomplir les cinq piliers de l''Islam sans faute","Rejeter toutes les autres religions"]'::jsonb,1,'Dans les textes, le Tawḥīd consiste à unifier Allah dans Ses spécificités et dans les droits qui Lui reviennent exclusivement.',11),
   (t,c,'moyenne','Comment le Tawḥīd al-Ulūhiyya se situe-t-il par rapport aux deux autres catégories ?','["Il est indépendant des deux autres catégories","Il est moins important que les deux autres","Il comprend et englobe les deux autres formes, puisqu''on n''adore qu''Allah en raison de Sa seigneurie et de Ses attributs parfaits","Il est identique au Tawḥīd ar-Rubūbiyya"]'::jsonb,2,'Le Tawḥīd al-Ulūhiyya comprend et englobe les deux autres formes, puisqu''on n''adore qu''Allah en raison de Sa seigneurie et de Ses attributs parfaits.',12),
   (t,c,'moyenne','Quelle sourate affirme l''unicité absolue d''Allah dans Ses noms, attributs et essence, et que le Prophète récitait fréquemment ?','["Sourate al-Fātiḥa","Sourate al-Baqara","Sourate al-Ikhlāṣ","Sourate al-Mujādila"]'::jsonb,2,'Sourate al-Ikhlāṣ affirme l''unicité absolue d''Allah dans Ses noms, attributs et essence. Le Prophète récitait ces deux sourates (al-Ikhlāṣ et al-Kāfirūn) dans les sunnan, les prières de voyage, et avant de dormir.',13),
   (t,c,'moyenne','Comment ʿĀʾishah a-t-elle réagi lors de la révélation de la sourate al-Mujādilah ?','["Elle a demandé des précisions sur le sens du verset","Elle a dit : « Gloire à Celui dont l''ouïe entend tout ! »","Elle a pleuré en entendant le verset","Elle n''a pas compris le sens du verset"]'::jsonb,1,'ʿĀʾishah a dit : « Gloire à Celui dont l''ouïe entend tout ! » Elle dit cela en réaction à la descente du verset, car elle-même n''avait pas bien entendu ce qu''avait dit la femme. Mais Allah, Lui, a tout entendu.',14),
   (t,c,'moyenne','Quelle est la position des pieux prédécesseurs (Salaf aṣ-Ṣāliḥ) concernant les Noms et Attributs d''Allah ?','["Ils les interprétaient selon la raison et la philosophie","Ils les acceptaient tels quels, y croyaient et agissaient en conséquence, sans les déformer, les nier, ni en discuter le comment","Ils en niaient certains pour éviter l''anthropomorphisme","Ils réservaient leur connaissance aux savants uniquement"]'::jsonb,1,'Les compagnons acceptaient les Noms et les Attributs d''Allah tels quels, y croyaient et agissaient en conséquence, sans chercher à en déformer le sens, à les nier, ni à en discuter le ''comment'' (bi-lā kayf).',15),
   (t,c,'difficile','Quelle secte définit l''unicité d''Allah comme « l''affirmation d''une présence absolue, dépourvue d''attributs, de caractéristiques, et au-delà de toute description » ?','["Les Muʿtazilites","Les Jahmites","Les philosophes","Les partisans de l''ittihād"]'::jsonb,2,'Les philosophes définissent l''unicité d''Allah comme étant : « L''affirmation d''une présence absolue, dépourvue d''attributs, de caractéristiques, et au-delà de toute description. » Cela mène à la négation des noms et attributs d''Allah.',16),
   (t,c,'difficile','Quelle est la doctrine des partisans de l''ittihād (panhéistes) concernant Allah ?','["Ils nient la prédestination divine","Ils nient les attributs d''Allah tout en affirmant Son existence","Ils affirment qu''Allah est présent réellement et concrètement dans toutes les choses, faisant de toute chose Allah","Ils affirment que l''homme n''est l''auteur d''aucune de ses actions"]'::jsonb,2,'Les partisans de l''ittihād affirment que : « Allah est présent réellement et concrètement dans toutes les choses. » Selon cette croyance, toute chose est Allah, et il n''y aurait donc qu''un seul être existant. Cette doctrine est une forme claire de mécréance (kufr).',17),
   (t,c,'difficile','Selon le shaykh Ṣāliḥ al-Fawzān, pourquoi la reconnaissance du Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt par les polythéistes ne les rendait-elle pas monothéistes ?','["Car ils ne connaissaient pas tous les noms d''Allah","Car cette reconnaissance ne dépasse pas le cadre d''une reconnaissance de l''unicité dans la seigneurie, et ils commettaient le shirk dans l''adoration","Car ils rejetaient l''ensemble des attributs d''Allah","Car ils n''accomplissaient pas la prière"]'::jsonb,1,'Le shaykh al-Fawzān a répondu : « Le fait de reconnaître l''unicité dans les noms et attributs ne suffit pas, car cela ne dépasse pas le cadre d''une reconnaissance de l''unicité dans la seigneurie. » Les polythéistes commettaient le shirk dans l''adoration (tawḥīd al-ulūhiyyah).',18),
   (t,c,'difficile','Comment Ibn al-Qayyim et certains savants résument-ils le Tawḥīd en deux grandes catégories ?','["Tawḥīd de la seigneurie et Tawḥīd de l''adoration uniquement","Tawḥīd al-ʿIlmī al-Iʿtiqādī (connaissance et croyance : seigneurie + noms et attributs) et Tawḥīd al-ʿAmalī aṭ-Ṭalabī (actes et adoration)","Tawḥīd apparent et Tawḥīd caché","Tawḥīd obligatoire et Tawḥīd recommandé"]'::jsonb,1,'Certains savants résument le Tawḥīd en deux grandes catégories : 1. Tawḥīd al-ʿIlmī al-Iʿtiqādī : ce qui relève de la connaissance et de la croyance (seigneurie + noms et attributs). 2. Tawḥīd al-ʿAmalī aṭ-Ṭalabī : ce qui relève des actes et de l''adoration. Cette classification est présente chez des imams comme Ibn al-Qayyim.',19),
   (t,c,'difficile','Que disent les Jabrites (al-Jabriyya) concernant les actions de l''être humain ?','["L''homme crée ses propres actions librement sans intervention divine","L''homme est partiellement libre dans ses actions","L''homme n''est l''auteur d''aucune de ses actions, il est contraint comme une feuille portée par le vent","L''homme est responsable de ses actes mais Allah les juge selon Sa volonté"]'::jsonb,2,'Les Jabrites disent : « L''homme n''est l''auteur d''aucune de ses actions. Il est contraint, comme une feuille portée par le vent. » Ils nient le libre arbitre et la responsabilité de l''homme, ce qui annule la notion même de taklīf (responsabilité religieuse).',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',2,'L''unicité d''Allah dans ses noms et Attributs et réfutation des sectes déviantes','Dimanche 6 juillet 2025 – 11 Muḥarram 1447 H',2) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','De quelle racine arabe est issu le mot « Tawḥīd » et quel en est le sens selon l''imām Ibn Fāris ?','["De la racine (ع-ب-د) dont le sens est l''adoration","De la racine (و-ح-د) dont le sens est l''unicité et l''isolement","De la racine (ح-م-د) dont le sens est la louange","De la racine (ص-د-ق) dont le sens est la véracité"]'::jsonb,1,'Le tawḥīd est un nom d''action issu du verbe waḥḥada – yuwahḥidu, qui provient de la racine (و-ح-د). Le sens de cette racine, comme l''a rappelé l''imām al-Lughawī Ibn Fāris, est l''unicité et l''isolement (al-infirrād).',1),
   (t,c,'facile','Pourquoi dit-on qu''Allah est unique, selon le cours ?','["Parce que les hommes Lui vouent exclusivement l''adoration","Parce qu''Il est unique par essence, car Il n''a nul égal ni semblable, et c''est pour cela que le serviteur L''unifie en Lui consacrant toutes les formes d''adoration","Parce que les savants ont décidé de L''unifier","Parce que le Coran l''a affirmé sans autre raison"]'::jsonb,1,'Il convient de préciser qu''on ne dit pas qu''Allah est unique du fait que le serviteur Lui voue exclusivement l''adoration. En réalité, Il est unique par essence, car Il n''a nul égal ni semblable. Et c''est parce qu''Il est ainsi que le serviteur L''unifie en Lui consacrant exclusivement toutes les formes d''adoration.',2),
   (t,c,'facile','À partir de quel savant la division du Tawḥīd en trois catégories s''est-elle répandue ?','["À partir d''al-Bukhārī","À partir d''Ibn Taymiyyah, Ibn al-Qayyim, puis Shaykh Muḥammad ibn ʿAbd al-Wahhāb","À partir d''al-Ghazālī","À partir d''al-Ashʿarī"]'::jsonb,1,'À partir d''Ibn Taymiyyah, Ibn al-Qayyim, puis Shaykh Muḥammad ibn ʿAbd al-Wahhāb et ses élèves, la division en trois catégories s''est répandue. Il n''y a aucune contradiction entre les deux méthodes, même si les termes diffèrent : la différence est de forme, non de fond.',3),
   (t,c,'facile','Quel est le synonyme du Tawḥīd al-ʿibādah (l''unicité dans l''adoration) mentionné dans le cours ?','["Al-ʿAdl (la justice)","Al-Ikhlāṣ (la sincérité, la pureté de l''intention) envers Allah","Al-Ḥikma (la sagesse)","Al-Ṣabr (la patience)"]'::jsonb,1,'L''unicité dans l''adoration (Tawḥīd al-ʿibādah) : c''est le fait que le serviteur voue toutes ses formes d''adoration exclusivement à Allah et ne voue aucune adoration à autre que Lui. Cela a pour synonyme al-ikhlāṣ (la sincérité, pureté de l''intention) envers Allah.',4),
   (t,c,'facile','Que signifie le Tawḥīd al-maʿrifah wa-l-ithbāt (l''unicité dans la connaissance et l''affirmation) ?','["Accomplir les actes d''adoration avec sincérité","Croire en Allah, affirmer ce qu''Il nous a ordonné d''affirmer, nier ce qu''Il nous a ordonné de nier, conformément aux textes","Mémoriser les noms d''Allah et les réciter","Étudier la philosophie islamique pour comprendre Allah"]'::jsonb,1,'L''unicité dans la connaissance et l''affirmation (Tawḥīd al-maʿrifah wa-l-ithbāt) consiste à croire en Allah, à affirmer ce qu''Il nous a ordonné d''affirmer, et à nier ce qu''Il nous a ordonné de nier. C''est le fait d''avoir foi en tout ce qu''Allah a révélé concernant Lui-même, et d''y croire fermement, conformément aux textes.',5),
   (t,c,'facile','Qu''est-ce que le taʿṭīl ?','["Comparer Allah à Ses créatures","Nier les noms ou attributs d''Allah","Chercher à connaître le ''comment'' des attributs","Altérer le sens des attributs"]'::jsonb,1,'Ne pas faire de taʿṭīl : ne pas nier les noms ou attributs d''Allah. C''est l''une des quatre restrictions à respecter dans le Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt.',6),
   (t,c,'facile','Qu''est-ce que le tamthīl ?','["Nier les attributs d''Allah","Altérer le sens des attributs d''Allah","Comparer les attributs d''Allah à ceux des créatures (anthropomorphisme)","Chercher à savoir comment sont les attributs d''Allah"]'::jsonb,2,'Ne pas faire de tamthīl : ne pas les comparer à ceux des créatures (anthropomorphisme). C''est la troisième des quatre restrictions à respecter dans le Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt.',7),
   (t,c,'facile','Sur quoi repose le Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt comme piliers fondamentaux selon le cours ?','["Sur la croyance, la prière et le jeûne","Sur al-ʿIʿtiqād (la croyance ferme), al-Īmān (la foi) et al-Ithbāt (l''affirmation) combiné à an-Nafy (la négation)","Sur la mémorisation du Coran et de la Sunna","Sur la consultation des savants et le consensus"]'::jsonb,1,'L''unicité d''Allah dans Ses noms et attributs repose sur trois fondements indissociables : 1. al-ʿIʿtiqād : la croyance ferme. 2. al-Īmān : la foi. 3. al-Ithbāt : l''affirmation de tout ce qu''Allah s''est Lui-même attribué ou que Son Prophète a confirmé pour Lui, et an-Nafy : la négation de tout défaut ou imperfection.',8),
   (t,c,'facile','Combien d''attributs les Ashāʿirah ont-ils affirmés, selon ce cours ?','["Tous les attributs mentionnés dans le Coran et la Sunna","Seulement sept attributs, tous les autres étant rejetés, altérés ou interprétés de manière figurée","Uniquement les noms d''Allah sans attribut correspondant","Aucun attribut"]'::jsonb,1,'Les Ashāʿirah ont affirmé seulement sept attributs. Tous les autres attributs ont été rejetés, altérés ou interprétés de manière figurée.',9),
   (t,c,'facile','Quelles sont les deux grandes catégories du shirk dans les noms et attributs d''Allah ?','["La mécréance et l''hypocrisie","At-Taʿṭīl (la négation) et At-Tashbīh (l''anthropomorphisme)","Le grand shirk et le petit shirk","La négation partielle et la négation totale uniquement"]'::jsonb,1,'Le shirk dans les noms et attributs d''Allah se divise en deux grandes catégories : 1. At-Taʿṭīl : la négation — c''est le fait de nier ce qu''Allah a affirmé pour Lui-même. 2. At-Tashbīh : l''anthropomorphisme — c''est le fait d''assimiler Allah à Ses créatures.',10),
   (t,c,'moyenne','Quel est l''antonyme du Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt selon le cours ?','["Invoquer les saints et les morts uniquement","Le rejet des noms et attributs d''Allah, leur altération (taḥrīf), leur négation (taʿṭīl), ou le fait de croire qu''Allah a des attributs comparables à ceux de Ses créatures","Croire à l''existence de plusieurs dieux","Ne pas accomplir les actes d''adoration"]'::jsonb,1,'L''antonyme de l''unicité dans les noms et attributs est : soit le rejet des noms et attributs d''Allah, soit leur altération (taḥrīf), soit leur négation (taʿṭīl), soit de croire qu''Allah a des attributs comparables à ceux de Ses créatures.',11),
   (t,c,'moyenne','Selon la définition du shaykh ʿAbd ar-Raḥmān as-Saʿdī, en quoi consiste le Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt ?','["Réciter les noms d''Allah dans les prières uniquement","Croire qu''Allah est seul et unique dans la perfection absolue sous tous ses aspects, en affirmant ce qu''Il S''est affirmé et en Le déclarant exempt de ce qu''Il a nié pour Lui-même","Comparer les attributs d''Allah à ceux des créatures pour mieux les comprendre","Accepter uniquement les attributs mentionnés dans le Coran et non dans la Sunna"]'::jsonb,1,'Selon as-Saʿdī, c''est croire qu''Allah est seul et unique dans la perfection absolue sous tous ses aspects, en affirmant ce qu''Il S''est affirmé à Lui-même ou ce que Son Prophète a affirmé pour Lui parmi Ses noms et attributs, et en Le déclarant exempt de ce qu''Il a nié pour Lui-même ou que Son Prophète a nié à Son sujet.',12),
   (t,c,'moyenne','Quelle est la position des Muʿtazilah sur les noms et attributs d''Allah ?','["Ils ont nié tous les noms et tous les attributs d''Allah","Ils ont affirmé sept attributs et rejeté les autres","Ils ont renié les attributs tout en acceptant les noms, considérant ces noms comme de simples désignations abstraites sans attribut correspondant","Ils ont comparé Allah à Ses créatures"]'::jsonb,2,'Les Muʿtazilah ont renié les attributs, tout en acceptant les noms. Selon eux, les noms d''Allah ne désignent pas de qualités réelles, mais sont de simples désignations abstraites, sans attribut correspondant.',13),
   (t,c,'moyenne','Quels sont les trois principes fondamentaux dans l''affirmation des noms et attributs d''Allah rappelés par l''Imām ash-Shinqīṭī ?','["La mémorisation, la récitation et la mise en pratique","La foi en tout ce qu''Allah a affirmé de Lui-même, exempter Allah de toute ressemblance avec les créatures, et désespérer totalement d''accéder à la réalité du ''comment'' des attributs","L''affirmation, la négation et l''interprétation figurée","La lecture du Coran, la lecture de la Sunna et la consultation des savants"]'::jsonb,1,'L''Imām ash-Shinqīṭī rappelle trois fondements essentiels : 1. La foi en tout ce qu''Allah a affirmé de Lui-même dans le Coran ou la Sunnah authentique. 2. Exempter Allah de toute ressemblance avec les créatures dans Ses noms, Ses attributs ou Ses actes. 3. Le désespoir total d''accéder à la réalité du ''comment'' (al-kayfiyyah) des attributs d''Allah.',14),
   (t,c,'moyenne','Quelle est la voie des pieux prédécesseurs (Salaf) concernant les noms et attributs d''Allah, telle que formulée dans ce cours ?','["L''affirmation totale avec comparaison aux créatures pour faciliter la compréhension","La négation de tout ce qui pourrait ressembler aux créatures","L''affirmation (al-ithbāt) sans ressemblance (tashbīh), et la négation (an-nafī) sans annulation (taʿṭīl)","L''interprétation figurée (taʾwīl) de tous les attributs littéraux"]'::jsonb,2,'Les pieux prédécesseurs ont toujours affirmé une voie entre l''affirmation et la négation : l''affirmation (al-ithbāt) sans ressemblance (tashbīh), et la négation (an-nafī) sans annulation (taʿṭīl).',15),
   (t,c,'difficile','Pourquoi est-il impossible, selon l''argument du cours, qu''une entité existe sans attributs ? Et comment cet argument réfute-t-il les Jahmiyyah ?','["Car les savants l''ont décidé par consensus, et les Jahmiyyah n''ont pas suivi les savants","Car toute chose présente possède nécessairement une entité réelle, et toute entité implique des attributs ; affirmer qu''Allah est présent mais sans attributs revient en réalité à nier Son existence véritable","Car la philosophie grecque prouve l''impossibilité d''une entité sans attributs","Car le Coran l''interdit explicitement dans un verset précis sur les Jahmiyyah"]'::jsonb,1,'Toute chose présente (mawjūdah) possède nécessairement une entité réelle (dhāt). Et toute entité implique des attributs. Ces groupes sont donc confrontés à deux issues : soit ils reconnaissent qu''Allah est présent et doivent reconnaître qu''Il a des attributs réels, soit ils nient Son existence réelle, ce qui est une mécréance manifeste. Dire : ''Allah est présent mais sans attributs'' revient en réalité à nier Son existence véritable.',16),
   (t,c,'difficile','Quel est le lien entre les Kullābiyyah et les Ashāʿirah selon ce cours ?','["Les Ashāʿirah sont les fondateurs des Kullābiyyah","Les Kullābiyyah ont accepté certains attributs mais ont nié les attributs liés aux actions d''Allah, et ce courant est le précurseur direct de l''Ashʿarisme","Les deux groupes sont identiques avec des noms différents","Les Kullābiyyah ont réfuté les Ashāʿirah sur tous les points"]'::jsonb,1,'Les Kullābiyyah ont accepté certains attributs mais ont nié les attributs liés aux actions d''Allah. Ce courant est le précurseur direct de l''Ashʿarisme.',17),
   (t,c,'difficile','Selon le cours, pourquoi est-il interdit d''affirmer un ''comment'' (takyīf) pour les attributs d''Allah ?','["Car les anciens savants ne l''ont pas fait","Car la compréhension du kayf d''un attribut est liée à la vision de l''Être qui en est porteur, et nous ne voyons pas Allah dans cette vie, rendant impossible la perception de la réalité de Ses attributs","Car le takyīf est une forme de mécréance explicitement mentionnée dans le Coran","Car cela mènerait obligatoirement à l''anthropomorphisme"]'::jsonb,1,'La compréhension du kayf (le comment ou la réalité) d''un attribut est liée à la vision de l''Être qui en est porteur. Or, nous ne voyons pas Allah dans cette vie, et donc il est impossible de cerner ou de percevoir la réalité de Ses attributs. Affirmer un ''comment'' pour les attributs d''Allah est un mensonge sur Allah, interdit, et Allah est bien au-dessus de ce que l''on imagine ou décrit.',18),
   (t,c,'difficile','Que dit la parole du Salaf Nuʿaym ibn Ḥammād sur ceux qui assimilent Allah à Ses créatures et ceux qui nient Ses attributs ?','["Qu''ils sont dans l''erreur mais pas dans la mécréance","Que celui qui assimile Allah à Ses créatures a mécru, et que celui qui nie ce qu''Allah a affirmé de Lui-même a aussi mécru, et que ce qu''Allah S''est attribué ne comporte aucune ressemblance","Que seuls ceux qui nient tous les attributs ont mécru","Qu''ils doivent être rééduqués par les savants avant d''être jugés"]'::jsonb,1,'Nuʿaym ibn Ḥammād a dit : « Celui qui assimile Allah à Ses créatures a mécru. Et celui qui nie ce qu''Allah a affirmé de Lui-même, ou que Son Prophète a affirmé, a aussi mécru. Et ce qu''Allah S''est attribué à Lui-même ou ce que Son Prophète Lui a attribué ne comporte aucune ressemblance. »',19),
   (t,c,'difficile','Comment l''argument « affirmer certains attributs tout en en niant d''autres » est-il réfuté dans le cours par un verset coranique ?','["Par le verset de la sourate al-Ikhlāṣ sur l''unicité d''Allah","Par le verset de la sourate al-Baqarah : « Croyez-vous donc en une partie des Écritures pour renier l''autre ? » montrant que cela revient à croire en une partie du Livre et à rejeter une autre","Par le verset de la sourate al-Isrāʾ sur l''interdiction d''affirmer ce dont on n''est pas certain","Par le verset de la sourate ash-Shūrā : « Rien ne Lui est comparable »"]'::jsonb,1,'Affirmer certains attributs tout en niant d''autres revient à croire en une partie du Livre et à rejeter une autre. Allah a mis en garde contre cette attitude dans le Coran : « Croyez-vous donc en une partie des Écritures pour renier l''autre ? » [Sourate al-Baqarah, v.85].',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',3,'Approfondissement de la définition du Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt','Mercredi 9 juillet 2025 – 14 Muḥarram 1447 H',3) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Sur quels deux fondements repose le Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt ?','["La mémorisation des noms d''Allah et leur récitation dans les prières","L''affirmation (al-ithbāt) de ce qu''Allah S''est attribué, et la négation (an-nafī) de ce qu''Il a nié pour Lui-même","La croyance aux anges et aux livres révélés","L''étude de la philosophie islamique et le consensus des savants"]'::jsonb,1,'Le Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt repose sur deux fondements : 1. L''Affirmation (al-ithbāt) : affirmer ce qu''Allah S''est attribué dans le Coran ou ce que Son Messager a affirmé de Lui dans la Sunnah. 2. La Négation (an-nafī) : nier ce qu''Allah a nié de Lui-même ou ce que Son Messager a nié à Son sujet.',1),
   (t,c,'facile','Dans quel ouvrage Ibn Taymiyyah a-t-il résumé la voie du Tawḥīd dans les noms et attributs, combinant affirmation et négation ?','["Al-ʿAqīda al-Wāsiṭiyya uniquement","Al-ʿAqīda al-Ḥamawiyya al-Kubrā","Al-Qawl al-Mufīd ʿalā Kitāb at-Tawḥīd","Aʿlām as-Sunna al-Manshūra"]'::jsonb,1,'Shaykh al-Islām Ibn Taymiyyah a résumé cette voie dans son livre al-ʿAqīda al-Ḥamawiyya al-Kubrā, en soulignant que le fondement du Tawḥīd dans les noms et attributs est la combinaison entre affirmation (ithbāt) et négation (nafī).',2),
   (t,c,'facile','Qu''est-ce que l''affirmation générale (al-ithbāt al-mujmal) ?','["Affirmer de manière précise et explicite chaque nom et attribut d''Allah mentionnés dans le Coran","Affirmer la perfection absolue d''Allah de manière globale, sans mentionner des attributs spécifiques","Affirmer uniquement les attributs confirmés par le consensus des savants","Affirmer les attributs d''Allah en les comparant à ceux des créatures pour faciliter la compréhension"]'::jsonb,1,'L''affirmation générale (al-ithbāt al-mujmal) consiste à affirmer la perfection absolue d''Allah de manière globale, sans mentionner des attributs spécifiques. Exemple : « Louange à Allah, Seigneur de la Création », ce qui implique Sa perfection dans tous Ses attributs.',3),
   (t,c,'facile','Qu''est-ce que la négation détaillée (an-nafī al-mufaṣṣal) ?','["Nier de manière globale tout ce qui contredit la perfection absolue d''Allah","Exempter Allah en niant explicitement ce qu''Il a Lui-même nié dans le Coran ou ce que Son Prophète a nié dans la Sunna, comme les attributs d''imperfection ou de défaut","Nier l''existence de toute ressemblance entre Allah et Ses créatures en termes généraux","Nier les interprétations des sectes déviantes concernant les attributs d''Allah"]'::jsonb,1,'La négation détaillée (an-nafī al-mufaṣṣal) consiste à exempter (tanzīh) Allah en niant explicitement ce qu''Il a Lui-même nié dans le Coran, ou ce que Son Prophète a nié à Son sujet dans la Sunnah, comme les attributs d''imperfection (naqṣ) ou de défaut (ʿayb). Exemple : « Il n''a pas engendré, ni été Lui-même engendré. »',4),
   (t,c,'facile','Quelle est la définition linguistique du taʿṭīl ?','["Comparer Allah à Ses créatures","Altérer le sens d''un attribut d''Allah","L''abandon, ou le fait de laisser quelque chose sans usage","Chercher à connaître le comment des attributs d''Allah"]'::jsonb,2,'Le taʿṭīl, d''un point de vue linguistique, signifie l''abandon, ou le fait de laisser quelque chose sans usage. Exemple dans le Coran : le terme muʿaṭṭala désigne un puits abandonné, c''est-à-dire laissé sans être utilisé ni entretenu (Sourate al-Ḥajj, verset 45).',5),
   (t,c,'facile','Qui est considéré comme le premier à avoir introduit la croyance du taʿṭīl (la négation des attributs d''Allah) ?','["Jahm ibn Ṣafwān","Al-Jaʿd ibn Dirham","Bishr ibn Ghiyāth al-Marīsī","Hishām ibn al-Ḥakam"]'::jsonb,1,'Al-Jaʿd ibn Dirham est considéré comme le premier à avoir exposé la croyance du taʿṭīl. Il a été influencé par les Juifs, les polythéistes et la secte des Ṣābiʾah dans la ville de Haran.',6),
   (t,c,'facile','En quelle année al-Jaʿd ibn Dirham a-t-il été exécuté, et par qui ?','["En 126 H par le prince Salm ibn Aḥwaz al-Tamīmī","En 115 H par Khalīd ibn ʿAbd Allāh al-Qasrī","En 128 H par le calife de l''époque","En 100 H par les savants de Médine"]'::jsonb,1,'Al-Jaʿd ibn Dirham a été exécuté en l''an 115 H par Khalīd ibn ʿAbd Allāh al-Qasrī, le jour du Aïd, qui dit : « Ô gens ! Sacrifiez (vos bêtes) pour Allah, et moi je sacrifie al-Jaʿd ibn Dirham, car il a prétendu qu''Allah n''a pas pris Ibrāhīm pour ami très aimé, ni parlé à Mūsā. »',7),
   (t,c,'facile','Quelle est la définition linguistique du taḥrīf ?','["Laisser quelque chose sans usage","Comparer Allah à Ses créatures","Déformer ou changer une chose de sa place, issu de la racine (ح-ر-ف)","Chercher à connaître la réalité des attributs d''Allah"]'::jsonb,2,'Taḥrīf vient de la racine (ح-ر-ف), qui signifie : déformer, changer une chose de sa place.',8),
   (t,c,'facile','Combien de types de falsification (taḥrīf) existe-t-il selon ce cours ?','["Un seul type : la falsification dans le sens","Trois types : dans les mots, dans le sens et dans la grammaire","Deux types : la falsification dans les mots (taḥrīf lafẓī) et la falsification dans le sens (taḥrīf maʿnawī)","Quatre types selon les quatre écoles juridiques"]'::jsonb,2,'Les deux catégories de falsification sont : 1. Falsification dans les mots (taḥrīf lafẓī) : altérer la prononciation ou la structure grammaticale d''un mot pour changer le sujet ou le sens voulu. 2. Falsification dans le sens (taḥrīf maʿnawī) : interpréter un sens clair dans un sens tordu, contraire à ce qu''indiquent les textes.',9),
   (t,c,'facile','Quelle est la définition du at-takyīf dans le domaine des attributs d''Allah ?','["Nier totalement un attribut qu''Allah S''est affirmé","Comparer les attributs d''Allah à ceux des créatures de manière totale","Décrire le comment d''un ou plusieurs attributs d''Allah, ou demander le comment (al-kayfiyyah)","Altérer le sens d''un attribut sans modifier les mots"]'::jsonb,2,'At-takyīf : c''est le fait de décrire le comment d''un ou plusieurs attributs d''Allah ou de demander le comment (al-kayfiyyah), soit en décrivant l''attribut (ex. : dire que la main d''Allah est comme ceci ou comme cela), soit en interrogeant sur le comment (ex. : demander « Comment est la main d''Allah ? »).',10),
   (t,c,'moyenne','Quelle est la différence entre l''at-tashbīh et l''at-tamthīl selon ce cours ?','["Le tashbīh concerne uniquement les noms d''Allah, et le tamthīl concerne uniquement les attributs","Le tashbīh est une ressemblance partielle en attribuant à Allah des attributs semblables à ceux des créatures, tandis que le tamthīl est une ressemblance totale en donnant un équivalent exact à un attribut d''Allah","Le tashbīh est permis dans certains cas, tandis que le tamthīl est toujours interdit","Le tashbīh concerne les sectes anciennes et le tamthīl les sectes modernes"]'::jsonb,1,'At-tashbīh : attribuer à Allah des attributs semblables à ceux des créatures (ressemblance partielle). At-tamthīl : c''est ce que le Coran a explicitement réfuté. Cela consiste à donner un équivalent exact, un modèle ou une image à un attribut d''Allah (ressemblance totale).',11),
   (t,c,'moyenne','Qu''implique la négation (an-nafī) dans les textes du Coran et de la Sunna, au-delà d''une simple absence ?','["Elle implique uniquement l''absence de l''attribut nié, sans autre signification","Elle implique l''affirmation implicite de l''attribut contraire dans sa forme parfaite","Elle implique que cet attribut appartient aux créatures et non à Allah","Elle implique que les savants doivent interpréter le sens selon leur raison"]'::jsonb,1,'Lorsqu''on parle de négation dans les textes du Coran et de la Sunnah, il ne s''agit pas d''une simple absence, mais plutôt d''une affirmation implicite de l''attribut contraire, dans sa forme parfaite. Exemple : la négation du sommeil et de la somnolence signifie l''affirmation de la perfection d''Allah dans la préservation et la vigilance absolue, sans aucune faiblesse ni lassitude.',12),
   (t,c,'moyenne','Quelle est la chaîne de transmission des idées du taʿṭīl depuis son origine jusqu''à Jahm ibn Ṣafwān ?','["Labīd ibn al-Aʿṣam → Bayān ibn Samʿān → al-Jaʿd ibn Dirham → Jahm ibn Ṣafwān","Labīd ibn al-Aʿṣam → Ṭālūt ibn Ukhtā → Bayān ibn Samʿān → al-Jaʿd ibn Dirham → Jahm ibn Ṣafwān","Hishām ibn al-Ḥakam → al-Jaʿd ibn Dirham → Jahm ibn Ṣafwān","Les philosophes grecs → al-Jaʿd ibn Dirham → Jahm ibn Ṣafwān → Bishr al-Marīsī"]'::jsonb,1,'Jaʿd ibn Dirham a pris ses idées de Bayān ibn Samʿān, qui lui-même les a pris de Ṭālūt ibn Ukhtā, et ce Ṭālūt les aurait pris de Labīd ibn al-Aʿṣam (le juif accusé d''avoir empoisonné le Prophète). Puis Jaʿd ibn Dirham a transmis ces idées à Jahm ibn Ṣafwān.',13),
   (t,c,'moyenne','Quelle règle importante est énoncée concernant le lien entre taḥrīf lafẓī et taḥrīf maʿnawī ?','["La falsification dans le sens entraîne toujours une falsification dans les mots","Les deux types de falsification sont indépendants l''un de l''autre","Toute falsification dans les mots (taḥrīf lafẓī) entraîne une falsification dans le sens (taḥrīf maʿnawī), car le but est de nier ce qu''Allah S''est affirmé","La falsification dans les mots est permise si elle n''altère pas le sens"]'::jsonb,2,'Règle importante : Toute falsification dans les mots (taḥrīf lafẓī) entraîne une falsification dans le sens (taḥrīf maʿnawī), car le but est de nier ce qu''Allah S''est affirmé.',14),
   (t,c,'moyenne','Pourquoi est-il incorrect de qualifier Allah de « pas sourd » sans autre précision, selon le cours ?','["Car cette expression contredit les textes du Coran","Car dans la négation absolue il n''y a pas d''éloge direct sauf lorsqu''elle implique l''affirmation de son contraire ; dire qu''Allah n''est pas sourd n''est un éloge que si cela implique qu''Il entend parfaitement","Car les savants ont interdit d''utiliser des négations pour décrire Allah","Car cela mènerait à l''anthropomorphisme"]'::jsonb,1,'Dans la négation absolue, il n''y a pas d''éloge direct (madḥ), sauf lorsqu''elle implique l''affirmation de son contraire, ce qui devient alors un éloge implicite. Ainsi, dire qu''Allah « n''est pas sourd » n''est en soi pas un éloge, sauf si cela implique qu''Il entend parfaitement (as-Samīʿ). C''est pourquoi l''éloge provient principalement de l''affirmation des attributs.',15),
   (t,c,'difficile','Quelle est la différence entre la négation (an-nafī) et la falsification (at-taḥrīf), et quelle règle logique découle de leur rapport ?','["Ils sont synonymes : toute négation est une falsification et toute falsification est une négation","An-nafī nie totalement un attribut, tandis qu''at-taḥrīf altère le sens apparent en apparence tout en conservant le mot ; toute falsification est une forme de négation, mais toute négation n''est pas nécessairement une falsification","An-nafī concerne les attributs d''action et at-taḥrīf concerne les attributs d''essence","La négation est permise dans certains cas, contrairement à la falsification qui est toujours interdite"]'::jsonb,1,'An-nafī : c''est le fait de nier totalement un attribut qu''Allah S''est affirmé. At-taḥrīf : c''est d''altérer le sens apparent d''un nom ou d''un attribut, soit en modifiant le mot, soit en interprétant son sens dans une direction qui contredit la langue arabe claire. Règle importante : Toute falsification est une forme de négation, mais toute négation n''est pas nécessairement une falsification.',16),
   (t,c,'difficile','Comment les négationnistes (muʿaṭṭilah) sont-ils, selon le cours, d''abord tombés dans l''anthropomorphisme avant de basculer dans le négationnisme ?','["Ils ont commencé par étudier les textes du Coran, puis les ont mal interprétés","En affirmant les attributs, puis en les comparant à ceux des créatures par erreur","Ils ont comparé Allah à la création, puis ont nié les attributs pour éviter cette ressemblance imaginée ; ainsi tout négationniste est en réalité d''abord tombé dans l''anthropomorphisme puis l''a nié","Ils ont suivi les philosophes grecs qui combinaient les deux erreurs simultanément"]'::jsonb,2,'En réalité, les négationnistes sont tombés dans la négation parce qu''ils ont d''abord sombré dans l''anthropomorphisme. Ils se sont dit : « Si nous affirmons tel ou tel attribut, cela revient à faire de l''anthropomorphisme », alors ils ont décidé de le rejeter et de verser dans le négationnisme. Ainsi, tout négationniste est en réalité d''abord tombé dans l''anthropomorphisme, puis l''a nié.',17),
   (t,c,'difficile','Quel exemple de falsification dans les mots (taḥrīf lafẓī) est donné concernant le verset sur la parole d''Allah à Mūsā ?','["Ils ont remplacé le mot « Allāh » par le mot « Mūsā » dans le verset","Ils ont modifié la voyelle sur « Allāh » de dammah (ḍamma) en fatḥah pour faire croire que Mūsā est celui qui a parlé à Allah, ce qui est une altération grammaticale flagrante","Ils ont supprimé le verset de certaines copies du Coran","Ils ont interprété « parler » comme signifiant « inspirer » sans modifier les mots"]'::jsonb,1,'Certains négationnistes ont voulu éviter l''attribution de la parole à Allah. Ils ont modifié la voyelle sur « Allāh » : dammah (ḍamma) → fatḥah, pour faire croire que Mūsā est celui qui a parlé à Allah, ce qui est une altération grammaticale flagrante. (Sourate an-Nisāʾ, v.164 : « Allah a bel et bien parlé à Moïse. »)',18),
   (t,c,'difficile','Quelle est la différence entre at-tashbīh et at-takyīf, et quelle règle logique découle de leur rapport ?','["Ils sont identiques : tout tashbīh est un takyīf et tout takyīf est un tashbīh","At-tashbīh compare directement un attribut d''Allah à la créature, tandis qu''at-takyīf décrit ou interroge sur le comment d''un attribut sans forcément le comparer à quelque chose de connu ; toute adaptation (takyīf) est une assimilation (tashbīh), mais toute assimilation n''est pas forcément une adaptation","At-tashbīh concerne les attributs d''essence et at-takyīf concerne les attributs d''action","Le takyīf est une forme légère de tashbīh, permise dans certaines circonstances pédagogiques"]'::jsonb,1,'At-tashbīh consiste à attribuer à Allah un attribut en le comparant directement à la créature. At-takyīf consiste à décrire ou interroger sur le comment d''un attribut sans forcément le comparer à quelque chose de connu. Règle : Toute adaptation (takyīf) est une assimilation (tashbīh), mais toute assimilation n''est pas forcément une adaptation.',19),
   (t,c,'difficile','Quel exemple de falsification dans le sens (taḥrīf maʿnawī) est donné à propos du terme istawā (s''est élevé) dans la sourate Ṭā-Hā, et pourquoi est-il invalide ?','["Certains ont remplacé istawā par istaqarra (s''est installé), mais ce mot ne figure pas dans le Coran","Certains ont interprété istawā par istawlā (s''est emparé), mais ce mot n''a jamais signifié cela dans le langage clair des Arabes et n''est pas fondé dans les textes","Certains ont nié totalement le verset en prétendant qu''il était abrogé","Certains ont remplacé istawā par istaqarr (s''est fixé) pour nier la transcendance d''Allah"]'::jsonb,1,'Les gens de la falsification ont remplacé le terme clair istawā (s''est élevé) par istawlā (s''est emparé), pour éviter d''affirmer l''istiwāʾ d''Allah au-dessus de Son Trône, bien que ce mot n''ait jamais signifié cela dans le langage clair des Arabes. (Sourate Ṭā-Hā, v.5 : « Le Tout Miséricordieux, qui s''est élevé sur le Trône en toute majesté. »)',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',4,'Introduction du livre Al-Qawaid Al-Muthlaa et ouvrages de références','13/07/2025',4) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Quel est le titre complet du livre étudié dans cette série de cours, et quel en est l''auteur ?','["Al-Ḥamawiyya al-Kubrā, d''Ibn Taymiyya","Al-Qawāʿid al-Muthlā fī Ṣifāt Allāh wa-Asmāʾihi al-Ḥusnā, d''Ibn ʿUthaymīn","Aṣ-Ṣawāʿiq al-Mursalā, d''Ibn al-Qayyim","Darʾ Taʿāruḍ al-ʿAql wa-n-Naql, d''Ibn Taymiyya"]'::jsonb,1,'Le livre étudié s''intitule Al-Qawāʿid al-Muthlā fī Ṣifāt Allāh wa-Asmāʾihi al-Ḥusnā (Les règles exemplaires concernant les Attributs d''Allah et Ses Noms), de Shaykh Muḥammad Ṣāliḥ Ibn ʿUthaymīn.',1),
   (t,c,'facile','En combien de grandes parties le livre Al-Qawāʿid al-Muthlā est-il divisé ?','["Trois grandes parties","Quatre grandes parties","Cinq grandes parties auxquelles s''ajoute une conclusion réfutative","Sept grandes parties correspondant aux sept règles sur les Noms"]'::jsonb,2,'Ce livre est divisé en cinq grandes parties, auxquelles s''ajoute une conclusion réfutative : une introduction, les règles relatives aux Noms (7 règles), les règles relatives aux Attributs (7 règles), les règles concernant les textes scripturaires (4 règles), et les réfutations aux interprètes.',2),
   (t,c,'facile','Combien de règles fondamentales le livre Al-Qawāʿid al-Muthlā consacre-t-il respectivement aux Noms et aux Attributs d''Allah ?','["5 règles pour les Noms et 5 règles pour les Attributs","7 règles pour les Noms et 4 règles pour les Attributs","7 règles pour les Noms et 7 règles pour les Attributs","4 règles pour les Noms et 7 règles pour les Attributs"]'::jsonb,2,'Le livre contient 7 règles fondamentales relatives aux Noms d''Allah et 7 règles relatives aux Attributs d''Allah.',3),
   (t,c,'facile','Quels sont les quatre piliers de la foi en Allah mentionnés dans l''introduction du livre ?','["Croire en Allah, aux anges, aux livres et aux prophètes","Croire en l''existence d''Allah, en Sa seigneurie, en Sa divinité exclusive et en Ses Noms et Attributs","Croire en l''unicité, en la prophétie, en le Jugement Dernier et en la prédestination","Croire en la prière, le jeûne, le pèlerinage et l''aumône"]'::jsonb,1,'Les piliers de la foi en Allah sont : 1. Croire en l''existence d''Allah et en Sa présence, 2. Croire en Sa seigneurie (rubūbiyya), 3. Croire en Sa divinité exclusive (ulūhiyya), 4. Croire en Ses Noms et Attributs (al-Asmāʾ wa-ṣ-Ṣifāt).',4),
   (t,c,'facile','Quelle est la première règle concernant les Noms d''Allah énoncée dans le livre Al-Qawāʿid al-Muthlā ?','["Les Noms d''Allah sont limités à quatre-vingt-dix-neuf","Les Noms d''Allah sont d''institution divine (tawqīfiyya)","Tous les Noms d''Allah sont beaux (ḥusnā)","Les Noms d''Allah s''affirment uniquement par le Coran"]'::jsonb,2,'La première règle dans les Noms d''Allah est : tous les Noms d''Allah sont bons/beaux (ḥusnā).',5),
   (t,c,'facile','Selon quelle règle les Noms d''Allah ne peuvent-ils être établis que par le Coran et la Sunna, sans que la raison humaine ait sa place dans ce domaine ?','["Les Noms d''Allah sont limitatifs","Les Noms d''Allah sont d''institution divine (tawqīfiyya)","Les Noms d''Allah sont à la fois des dénominatifs et des attributs","Les Noms d''Allah indiquent Son entité de trois manières"]'::jsonb,1,'La règle 5 sur les Noms stipule que les Noms d''Allah sont d''institution divine (tawqīfiyya) : la raison humaine n''a pas sa place dans ce domaine. La base dans l''affirmation des noms et des attributs d''Allah est le Coran et la Sunna.',6),
   (t,c,'facile','Qu''est-ce que l''ilḥād (abjuration ou profanation) dans les Noms d''Allah ?','["Mémoriser les Noms d''Allah sans les comprendre","Se détourner de ce qu''implique leur bon usage et leurs droits","Invoquer Allah par des Noms non mentionnés dans le Coran","Comparer les Noms d''Allah à ceux des créatures"]'::jsonb,1,'La 7e règle sur les Noms précise que l''ilḥād (abjuration ou profanation) dans les Noms d''Allah, c''est se détourner de ce qu''implique leur bon usage et leurs droits.',7),
   (t,c,'facile','Quelles sont les deux catégories des Attributs affirmés (thubūtiyya) d''Allah ?','["Attributs généraux et attributs spécifiques","Attributs anciens et attributs nouveaux","Attributs liés à l''entité (ṣifāt dhātiyya) et attributs liés aux actions (ṣifāt fiʿliyya)","Attributs connus et attributs inconnus"]'::jsonb,2,'Les Attributs affirmés se divisent en deux catégories : les Attributs liés à l''entité (ṣifāt dhātiyya) et les Attributs liés aux actions (ṣifāt fiʿliyya).',8),
   (t,c,'facile','Quels sont les deux types d''invocation inclus dans le verset « Invoquez-Le donc par ces noms » selon l''explication du shaykh Ibn ʿUthaymīn ?','["L''invocation publique et l''invocation secrète","L''invocation d''adoration (duʿāʾ al-ʿibāda) et l''invocation de demande (duʿāʾ al-masʾala)","L''invocation collective et l''invocation individuelle","L''invocation obligatoire et l''invocation recommandée"]'::jsonb,1,'Dans le verset de la sourate al-Aʿrāf (v. 180), le terme « invoquez-Le » inclut : l''invocation d''adoration (duʿāʾ al-ʿibāda) et l''invocation de demande (duʿāʾ al-masʾala).',9),
   (t,c,'facile','Quel ouvrage d''Ibn Taymiyya est décrit comme destiné au niveau avancé, portant sur la réfutation des rationalistes et étant très technique ?','["Al-Ḥamawiyya al-Kubrā","At-Tadmuriyya","Darʾ Taʿāruḍ al-ʿAql wa-n-Naql","Naqḍ at-Taʾsīs"]'::jsonb,2,'Darʾ Taʿāruḍ al-ʿAql wa-n-Naql d''Ibn Taymiyya est classé au niveau avancé : c''est une réfutation majeure des rationalistes, très technique, qui nécessite un bon niveau.',10),
   (t,c,'moyenne','Pourquoi le domaine des Attributs d''Allah est-il dit plus vaste que celui des Noms ?','["Car les Attributs ont été mentionnés plus souvent dans le Coran que les Noms","Car tout Nom implique un attribut, mais tout attribut n''est pas forcément un Nom","Car les Attributs peuvent être établis par la raison contrairement aux Noms","Car les Attributs sont en nombre illimité alors que les Noms sont fixés à quatre-vingt-dix-neuf"]'::jsonb,1,'La règle 2 sur les Attributs précise : le domaine des Attributs est plus vaste que celui des Noms, car tout Nom implique un attribut, mais tout attribut n''est pas forcément un Nom.',11),
   (t,c,'moyenne','Quels sont les trois points essentiels par lesquels l''imām Ibn ʿUthaymīn souligne l''importance du Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt dans son introduction ?','["Cette science est obligatoire, ancienne et unique en son genre","Cette science fait partie intégrante de la foi en Allah, elle est l''une des trois catégories de l''unicité, et l''adoration ne peut être parfaite sans la connaissance des Noms et Attributs","Cette science réfute les sectes, complète la foi et protège des innovations","Cette science est la plus noble, la plus ancienne et la plus difficile des sciences islamiques"]'::jsonb,1,'Ibn ʿUthaymīn a voulu souligner trois points essentiels : 1. Cette science fait partie intégrante de la foi en Allah. 2. Elle constitue l''une des trois catégories de l''unicité d''Allah ; sans elle, le tawḥīd reste incomplet. 3. L''adoration et l''invocation ne peuvent être parfaites sans la connaissance des noms et attributs d''Allah.',12),
   (t,c,'moyenne','Quelle est la réponse célèbre de Mālik ibn Anas sur l''istiwāʾ d''Allah au-dessus du Trône, et que conclut-il à propos des questions sur ce sujet ?','["L''istiwāʾ est inconnu, le comment est inconnu, y croire est recommandé, et poser des questions est permis pour les savants","L''istiwāʾ est connu, le comment en est inconnu, y croire est obligatoire, et poser des questions à son sujet est une innovation","L''istiwāʾ signifie la domination, le comment est connu des savants, y croire est optionnel, et poser des questions est encouragé","L''istiwāʾ est à interpréter figurément, le comment est sans importance, y croire est suffisant, et poser des questions est déconseillé"]'::jsonb,1,'Mālik ibn Anas a répondu : « Al-Istiwāʾ (l''établissement) est connu, le ''comment'' (al-kayf) en est inconnu, y croire est obligatoire, et poser des questions à son sujet est une innovation. » Puis il dit au questionneur : « Je ne te vois que comme un innovateur. » Et il ordonna qu''on le fasse sortir.',13),
   (t,c,'moyenne','Lorsqu''un Nom d''Allah indique un attribut transitif (ṣifa mutaʿaddiya), combien d''éléments comprend-il, et lesquels ?','["Deux éléments : l''affirmation du Nom et l''affirmation du qualificatif","Quatre éléments : le Nom, le qualificatif, le statut, et l''action correspondante","Trois éléments : l''affirmation du Nom, l''affirmation du qualificatif contenu dans ce nom, et l''affirmation du statut de ce qualificatif et de ce qu''il implique","Un seul élément : l''affirmation que ce Nom appartient à Allah"]'::jsonb,2,'Lorsqu''un Nom d''Allah indique un attribut transitif (ṣifa mutaʿaddiya), il comprend trois éléments : l''affirmation du Nom d''Allah, l''affirmation du qualificatif d''Allah contenu dans ce nom, et l''affirmation du statut de ce qualificatif et de ce qu''il implique.',14),
   (t,c,'moyenne','En quoi consiste concrètement l''invocation d''adoration (duʿāʾ al-ʿibāda) par les Noms d''Allah ?','["Répéter les Noms d''Allah à voix haute dans les prières surérogatoires","Faire précéder chaque demande par un Nom d''Allah en rapport avec l''objet de la demande","Adorer Allah en fonction du sens du Nom : par exemple, sachant qu''Allah entend tout, faire attention à ses paroles, et ainsi de suite pour chaque Nom","Mémoriser les quatre-vingt-dix-neuf Noms d''Allah pour entrer au Paradis"]'::jsonb,2,'L''invocation d''adoration consiste à ce que tu adores Allah avec ce qu''implique chacun de Ses Noms : tu te repens à Lui car Il est Celui qui accepte le repentir, tu L''évoque avec ta langue car Il est l''Audient, tu L''adore avec tes membres car Il est le Voyant, tu Le crains dans ton for intérieur car Il est le Subtil, le Très Informé, et ainsi de suite.',15),
   (t,c,'difficile','Pourquoi les Attributs affirmés (thubūtiyya) sont-ils plus nombreux que les Attributs infirmés (salbiyya), selon la règle 4 sur les Attributs ?','["Car le Coran mentionne davantage d''affirmations que de négations dans ses versets","Car les savants ont établi plus d''attributs affirmés que d''attributs niés par consensus","Car la perfection se montre par l''affirmation et non par l''infirmation : plus les Attributs affirmés sont nombreux et variés, plus la perfection d''Allah est manifeste","Car les Attributs infirmés appartiennent aux créatures et non à Allah"]'::jsonb,2,'Les Attributs affirmés sont tous des attributs de perfection (kamāl). Plus ils sont nombreux et variés, plus la perfection d''Allah est manifeste. C''est pourquoi les Attributs affirmés sont plus nombreux que les attributs infirmés : la perfection se montre par l''affirmation et non l''infirmation.',16),
   (t,c,'difficile','Selon la 3e règle sur les textes, le sens apparent (ẓāhir) des textes sur les Attributs est-il entièrement connu ou entièrement inconnu ? Quelle est la position correcte ?','["Il est entièrement connu : les savants peuvent en déduire le comment des attributs","Il est entièrement inconnu : il faut déléguer le sens à Allah sans chercher à le comprendre","Il est connu sous un angle (le sens général ou lexical) et inconnu sous un autre (la réalité exacte, kayfiyya, de l''attribut)","Il est connu uniquement pour les attributs mentionnés dans le Coran, et inconnu pour ceux de la Sunna"]'::jsonb,2,'Le sens apparent (ẓāhir) des textes sur les Attributs est connu sous un angle et inconnu sous un autre : le sens général ou lexical est connu, mais la réalité exacte (kayfiyya) de l''attribut est inconnue. C''est le sens de la réponse de Mālik ibn Anas.',17),
   (t,c,'difficile','Quel est le lien entre la validité du Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt et les deux autres formes de tawḥīd, selon l''introduction du livre ?','["Le Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt est indépendant des deux autres formes et peut être étudié séparément","La foi en l''unicité d''Allah dans Ses noms et attributs ne peut être authentique et valide que si elle est accompagnée du Tawḥīd ar-Rubūbiyya et du Tawḥīd al-Ulūhiyya","Le Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt est la base des deux autres formes qui en découlent logiquement","Les trois formes de tawḥīd sont indépendantes et peuvent chacune être pratiquée sans les autres"]'::jsonb,1,'La foi en l''unicité d''Allah dans Ses noms et attributs (Tawḥīd al-Asmāʾ wa-ṣ-Ṣifāt) ne peut être authentique et valide que si elle est accompagnée des deux autres formes de tawḥīd : Tawḥīd ar-Rubūbiyya et Tawḥīd al-Ulūhiyya.',18),
   (t,c,'difficile','De quelle manière les Noms d''Allah fonctionnent-ils à la fois comme dénominatifs communs et comme attributs différents ?','["Communs car ils désignent tous la même qualité d''Allah, différents car certains sont coraniques et d''autres prophétiques","Communs car ils désignent tous l''entité d''Allah (dhāt), différents car chacun d''eux implique un sens spécifique","Communs car ils appartiennent tous à la même langue arabe, différents car leur prononciation varie","Communs car ils peuvent tous s''invoquer ensemble, différents car leur effet spirituel diffère"]'::jsonb,1,'Les Noms d''Allah sont des dénominatifs communs car ils désignent tous l''entité d''Allah (dhāt), et des attributs différents car chacun d''eux implique un sens spécifique.',19),
   (t,c,'difficile','Quelle raison personnelle Ibn ʿUthaymīn mentionne-t-il pour avoir rédigé le livre Al-Qawāʿid al-Muthlā, et quel objectif exprime-t-il ?','["En raison d''une demande de ses élèves et dans l''espoir de produire un ouvrage académique reconnu","En raison de l''importance du sujet et des propos tenus tantôt correctement tantôt faussement par ignorance ou fanatisme, en espérant que son travail soit sincère, agréé auprès d''Allah et bénéfique pour Ses serviteurs","En raison d''un manque de livres sur les Noms d''Allah et dans le but de réfuter les Muʿtazila","En raison d''une instruction de ses maîtres et dans l''espoir de compléter les ouvrages d''Ibn Taymiyya"]'::jsonb,1,'Ibn ʿUthaymīn précise : en raison de la place et de l''importance de l''unicité d''Allah dans Ses noms et attributs, et en raison des propos tenus par les gens dans ce domaine tantôt de manière correcte, tantôt de manière fausse, soit par ignorance, soit par fanatisme, il a souhaité rédiger sur ce sujet, en espérant que son travail soit sincère, agréé auprès d''Allah, et bénéfique pour Ses serviteurs.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',5,'Première règle : Tous les Noms d''Allah sont extrêmement beaux et bons','18/07/2025',5) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Dans combien de versets du Coran Allah affirme-t-il explicitement que Lui appartiennent les noms extrêmement beaux (al-asmāʾ al-ḥusnā) ?','["Deux versets","Trois versets","Quatre versets","Sept versets"]'::jsonb,2,'Dans quatre versets du Coran, Allah affirme clairement qu''à Lui appartiennent les noms extrêmement beaux et bons (al-asmāʾ al-ḥusnā) : sourate al-Aʿrāf (7:180), sourate al-Isrāʾ (17:110), sourate Ṭā-Hā (20:8) et sourate al-Ḥashr (59:24).',1),
   (t,c,'facile','Que signifie le mot « al-ḥusnā » grammaticalement dans l''expression al-asmāʾ al-ḥusnā ?','["Un pluriel masculin signifiant « beaux »","La forme féminine du superlatif « aḥsan », signifiant « extrêmement beau et bon »","Un adjectif relatif signifiant « bons par rapport à d''autres »","Un nom d''action signifiant « embellissement »"]'::jsonb,1,'Le mot « al-ḥusnā » est la forme féminine du superlatif « aḥsan », qui signifie « extrêmement beau et bon ». Il s''agit d''un superlatif absolu et non relatif.',2),
   (t,c,'facile','Parmi les quatre catégories de significations des noms selon Ibn ʿUthaymīn, laquelle est la seule qui convient à être attribuée à Allah ?','["Ce qui désigne le mal ou l''imperfection en soi","Ce qui désigne un sens positif seulement dans un contexte particulier","Ce qui désigne quelque chose de bon mais sans perfection assurée","Ce qui désigne quelque chose de bon de manière parfaite et absolue"]'::jsonb,3,'Seule la quatrième catégorie correspond aux noms d''Allah : ce qui désigne quelque chose de bon de manière parfaite et absolue. Par exemple, as-Samīʿ (L''Audient parfait) et al-Baṣīr (Le Clairvoyant parfait). Les autres catégories ne peuvent en aucun cas être attribuées à Allah.',3),
   (t,c,'facile','Quelle est la différence fondamentale entre les noms d''Allah et les noms des créatures ?','["Les noms d''Allah sont en arabe uniquement, contrairement aux noms des créatures","Les noms d''Allah sont limités en nombre, contrairement aux noms des créatures","Les noms d''Allah sont fondés sur des attributs réels et parfaits, tandis que les noms des créatures sont des noms propres figés sans lien nécessaire avec le sens","Les noms d''Allah ne peuvent être prononcés qu''en prière, contrairement aux noms des créatures"]'::jsonb,2,'Les noms d''Allah ne sont pas de simples appellations sans signification. Ils sont fondés sur des attributs réels et parfaits qu''Allah possède véritablement. En revanche, les noms des créatures sont des noms propres, figés, sans lien nécessaire avec la réalité de leur être : une personne peut s''appeler « Ḥakīm » sans pour autant avoir la sagesse.',4),
   (t,c,'facile','Combien de fois le nom « al-Ḥayy » (Le Vivant) revient-il dans le Coran, et avec quel autre nom est-il toujours associé ?','["Une seule fois, associé à al-Raḥmān","Deux fois, associé à al-ʿAlīm","Trois fois, associé à al-Qayyūm","Quatre fois, associé à al-Qahhar"]'::jsonb,2,'Le nom al-Ḥayy (Le Vivant) revient à trois reprises dans le Coran, toujours associé à al-Qayyūm (Celui qui subsiste par Lui-même et qui fait subsister toute chose) : sourate al-Baqara (2:255), sourate Āl ʿImrān (3:2), et sourate Ṭā-Hā (20:111).',5),
   (t,c,'facile','Quelle est la particularité de la vie d''Allah (al-ḥayāt) par rapport à la vie des créatures ?','["Elle est plus longue que la vie des créatures mais a tout de même un début","Elle n''est pas précédée de néant et n''est pas suivie de disparition, et n''est touchée par aucune faiblesse ni défaut","Elle est identique à la vie des créatures dans son essence mais supérieure dans sa durée","Elle existe uniquement dans l''au-delà et non dans ce bas monde"]'::jsonb,1,'La vie d''Allah est parfaite : elle n''est pas précédée de néant, n''est pas suivie de disparition, et n''est touchée par aucune faiblesse, ni défaut, ni manquement. C''est une vie éternelle et absolue, contrairement à celle des créatures qui est imparfaite et limitée.',6),
   (t,c,'facile','Quel exemple illustre le cas d''un nom qui ne peut s''utiliser pour Allah que dans un contexte restreint (et non comme nom autonome) ?','["Al-Mutakallim (Celui qui parle)","Al-Mākir (Celui qui ruse/complote)","Al-Qahhār (Le Dominateur)","Al-Jabbār (Le Tout-Puissant)"]'::jsonb,1,'Al-Mākir désigne un sens positif seulement dans un contexte particulier : on peut informer qu''Allah complote contre ceux qui complotent, comme dans le verset de la sourate Āl ʿImrān, mais ce n''est pas une chose qu''on Lui attribue directement de façon totale et absolue comme nom.',7),
   (t,c,'facile','Quelle est la différence entre le superlatif absolu et le superlatif relatif dans la description des noms d''Allah ?','["Le superlatif absolu implique une comparaison avec les créatures, le relatif n''en implique pas","Le superlatif absolu indique la perfection sans comparaison ni égal, tandis que le superlatif relatif implique une comparaison avec un autre élément","Le superlatif absolu s''applique aux attributs d''action, le relatif aux attributs d''essence","Les deux types sont équivalents et s''appliquent tous deux aux noms d''Allah"]'::jsonb,1,'Le superlatif relatif implique une comparaison (exemple : Muḥammad est plus intelligent que Zayd). Le superlatif absolu indique la perfection sans comparaison, sans égal ni associé (exemple : les noms d''Allah sont extrêmement beaux, sans que cela soit relatif à d''autres). Dire que les noms d''Allah atteignent la perfection suprême ne veut pas dire qu''ils ont une limite ou une fin.',8),
   (t,c,'facile','Que précise Ibn al-Qayyim sur la raison pour laquelle tous les noms d''Allah sont extrêmement beaux ?','["Parce qu''ils sont mentionnés dans le Coran et la Sunna uniquement","Parce qu''ils expriment tous la louange, l''éloge et la glorification","Parce qu''ils sont en nombre limité et bien connus des savants","Parce qu''ils sont prononcés en arabe classique"]'::jsonb,1,'Ibn al-Qayyim a dit : « Tous les noms d''Allah sont extrêmement beaux, car ils expriment tous la louange, l''éloge et la glorification. » Il est impossible de louer une entité parfaite avec des noms péjoratifs ou imparfaits.',9),
   (t,c,'facile','Pourquoi le nom al-Mutakallim (Celui qui parle) ne peut-il pas être attribué à Allah en tant que nom autonome ?','["Parce qu''Allah ne parle pas selon les textes du Coran","Parce que la parole peut être bonne, mais aussi mauvaise ; ce nom est ambigu et ne convient pas à Allah","Parce que ce nom est réservé aux prophètes dans le Coran","Parce que ce nom implique une ressemblance avec les créatures"]'::jsonb,1,'Al-Mutakallim (celui qui parle) désigne quelque chose de bon, mais sans perfection assurée : la parole peut être bonne, mais aussi mauvaise. Ce type de nom est ambigu et ne convient pas à Allah en tant que nom autonome.',10),
   (t,c,'moyenne','Quelle est la règle concernant les noms d''Allah qui ne se mentionnent qu''en duo (al-ism al-mzdawaj), et quel exemple en est donné ?','["Ces noms peuvent se mentionner seuls car chacun contient un sens complet ; exemple : al-Awwal et al-Ākhir","Ces noms ne s''utilisent qu''en paire pour exprimer la perfection globale, car les mentionner séparément créerait une ambiguïté ; exemple : al-Nāfiʿ et al-Ḍārr","Ces noms sont toujours associés à al-Ḥayy et al-Qayyūm pour renforcer leur sens","Ces noms sont limités à deux paires dans tout le Coran"]'::jsonb,1,'Certains noms ne s''utilisent qu''en paire pour exprimer la perfection globale. Exemple : al-Nāfiʿ (Celui qui accorde le profit) et al-Ḍārr (Celui qui inflige le mal). On ne dit pas simplement al-Nāfiʿ seul, car on ne peut attribuer ce nom sans son pendant al-Ḍārr, pour ne pas créer d''ambiguïté. Ensemble, ils expriment que seul Allah détient le pouvoir de nuire et de bénéficier.',11),
   (t,c,'moyenne','Comment la combinaison des noms al-ʿAzīz et al-Ḥakīm produit-elle une perfection supérieure à celle de chacun pris séparément ?','["Car leur réunion double simplement la perfection de chaque nom sans ajouter de nouveau sens","Car la puissance d''Allah est toujours accompagnée de sagesse, ce qui exclut toute injustice, et Sa sagesse est soutenue par une puissance parfaite qui ne subit aucune pression","Car ces deux noms ensemble désignent la même réalité que le nom al-Qahhar","Car leur association est mentionnée dans la sourate al-Fātiḥa"]'::jsonb,1,'Al-ʿAzīz implique la puissance parfaite, al-Ḥakīm implique la sagesse parfaite. Pris ensemble, ils indiquent que la puissance d''Allah est toujours accompagnée de sagesse — Il n''est jamais injuste dans l''usage de Sa puissance — et que Son jugement est appuyé par Sa puissance, car Il ne craint personne et ne subit aucune pression. C''est un niveau de perfection supérieur que les créatures puissantes ne possèdent pas.',12),
   (t,c,'moyenne','Quelle est la spécificité qui distingue le nom al-Khāliq du nom al-Bāriʾ selon le cours ?','["Al-Khāliq désigne la création à partir du néant uniquement, tandis qu''al-Bāriʾ désigne la création à partir d''une matière existante","Al-Khāliq est Celui qui a créé toute chose avec mesure et précision, tandis qu''al-Bāriʾ est Celui qui donne forme aux créatures à partir du néant","Al-Khāliq concerne les créatures visibles et al-Bāriʾ concerne les créatures invisibles","Al-Khāliq et al-Bāriʾ sont des synonymes parfaits qui peuvent s''interchanger librement"]'::jsonb,1,'Ces noms ne sont pas interchangeables : al-Khāliq est Celui qui a créé toute chose avec mesure et précision, tandis qu''al-Bāriʾ est Celui qui donne forme aux créatures à partir du néant. Ils renvoient à des aspects différents et complémentaires de la perfection divine.',13),
   (t,c,'moyenne','Quelle est la science de la miséricorde d''Allah décrite dans le hadith du Prophète concernant ar-Raḥmān, et quel verset coranique en confirme la vastitude ?','["Allah est plus miséricordieux envers Ses serviteurs qu''un père envers son fils ; confirmé par la sourate al-Fātiḥa","Allah est plus miséricordieux envers Ses serviteurs que cette mère envers son enfant ; confirmé par : « Ma miséricorde s''étend à toutes choses » (al-Aʿrāf, 7:156)","Allah réserve Sa miséricorde aux croyants uniquement ; confirmé par la sourate al-Bayyina","Allah distribue Sa miséricorde selon la piété de chacun ; confirmé par la sourate az-Zumar"]'::jsonb,1,'Le Prophète a dit : « Allah est plus miséricordieux envers Ses serviteurs que cette mère envers son enfant. » Ce hadith a été prononcé en voyant une mère retrouver son enfant égaré et le serrer contre elle. Allah confirme dans le Coran : « Ma miséricorde s''étend à toutes choses. » (Sourate al-Aʿrāf, 7:156).',14),
   (t,c,'moyenne','Quelle est la signification linguistique du nom « Allah » selon le tafsīr d''Ibn ʿAbbās ?','["Celui qui est présent partout et en tout temps","Celui qui possède la divinité et l''adoration sur toute la création","Celui dont le nom est inconnaissable et indicible","Celui qui a créé toute chose à partir du néant"]'::jsonb,1,'Selon le tafsīr d''Ibn ʿAbbās : « Allah est Celui qui possède la divinité et l''adoration sur toute la création. » Cela signifie qu''Allah est Celui qui mérite l''adoration exclusive et que l''adoration sincère, l''amour, l''espérance et la crainte Lui sont dus uniquement.',15),
   (t,c,'difficile','Pourquoi la structure linguistique du verset « wa-li-Llāhi al-asmāʾ al-ḥusnā » exprime-t-elle une exclusivité et une restriction, et comment s''appelle ce procédé rhétorique ?','["Car le pluriel « al-asmāʾ » indique une multitude ; ce procédé s''appelle at-takthīr","Car la particule lām précédée de wa indique l''appartenance exclusive et le fait de mettre ce qui est possédé en tête exprime la restriction (ḥaṣr) ; ce procédé s''appelle taqdīm mā ḥaqquhu at-taʾkhīr","Car le nom d''Allah est placé après ses attributs, ce qui en rhétorique s''appelle at-taʾkhīr al-maqṣūd","Car la conjonction wa au début du verset lie ce verset au précédent pour renforcer l''exclusivité ; ce procédé s''appelle al-waṣl"]'::jsonb,1,'La particule lām indique ici l''appartenance exclusive. En rhétorique arabe (balāgha), mettre en tête ce qui devrait normalement venir après s''appelle taqdīm mā ḥaqquhu at-taʾkhīr, et cela exprime la restriction (ḥaṣr). De même que dire « à toi ce stylo » signifie qu''il est uniquement à toi, le verset signifie que ces noms appartiennent exclusivement à Allah.',16),
   (t,c,'difficile','La science d''Allah (al-ʿIlm) contenue dans le nom al-ʿAlīm couvre quatre dimensions. Laquelle parmi les propositions suivantes les énumère correctement ?','["Ce qui est passé, ce qui est présent, ce qui est futur, et ce qui est caché aux anges","Ce qui est (mā yakūn), ce qui était (mā kāna), ce qui sera (mā sayakūn), et ce qui ne s''est pas produit et comment cela aurait été s''il s''était produit (mā lam yakun law kāna kayfa yakūn)","Ce qui est dans les cieux, ce qui est sur la terre, ce qui est dans les mers, et ce qui est dans les cœurs","La science de la prédestination, la science des livres révélés, la science des créatures et la science du Jour Dernier"]'::jsonb,1,'La science d''Allah couvre : ce qui est (mā yakūn), ce qui était (mā kāna), ce qui sera (mā sayakūn), et ce qui ne s''est pas produit et comment cela aurait été s''il s''était produit (mā lam yakun law kāna kayfa yakūn). Cette science n''est précédée d''aucune ignorance et n''est sujette à aucun oubli.',17),
   (t,c,'difficile','Pourquoi est-il incorrect d''affirmer que les noms d''Allah atteignent une « extrême limite » dans le sens d''une limite ou d''une fin de leur nombre ou de leur signification ?','["Car le Coran a explicitement dit que leurs nombres sont infinis, ce qui contredit l''idée de limite","Car « atteindre l''extrême limite » signifie qu''ils sont d''une perfection absolue sans fin dans leur sens, non qu''ils ont une limite quantitative ; rien ne Lui est comparable et nul ne Lui est semblable ni comparable","Car les savants ont établi un nombre fixe de noms et cette limite est un consensus","Car l''idée d''une limite implique nécessairement une imperfection, que les savants ont réfutée par consensus"]'::jsonb,1,'Dire que les noms d''Allah atteignent la perfection suprême et leur extrême limite signifie qu''ils sont absolument parfaits dans leurs sens, sans aucun défaut. Cela ne veut pas dire qu''ils ont une limite ou une fin, ni dans leur nombre ni dans leur signification. Rien de Lui ne ressemble, nul ne Lui est semblable ni comparable.',18),
   (t,c,'difficile','Pourquoi le mal existe-t-il dans la création d''Allah sans qu''il entre pour autant dans Ses noms ou Ses attributs, et quel exemple coranique l''illustre ?','["Car Allah délègue la création du mal aux anges déchus ; illustré par la sourate al-Baqara sur Iblīs","Car le mal est une notion relative qui dépend du point de vue humain et non d''une réalité objective dans la création","Car le mal existe dans la création mais pas dans les noms, les attributs ni les actions d''Allah ; illustré par le verset al-Fātiḥa où Allah ne S''attribue pas directement la colère et l''égarement mais les mentionne de manière implicite","Car Allah a interdit l''attribution du mal aux noms divins par un verset explicite de la sourate al-Aʿrāf"]'::jsonb,2,'Le mal existe dans la création, mais pas dans les noms, les attributs ni les actions d''Allah. Un exemple coranique : dans la sourate al-Fātiḥa (1:7), Allah n''attribue pas directement la colère et l''égarement à Lui-même, mais les mentionne de manière implicite : « le chemin de ceux que Tu as comblés de faveurs, non pas de ceux qui ont encouru Ta colère, ni des égarés. »',19),
   (t,c,'difficile','Quel est le Nom Suprême d''Allah (al-ism al-aʿẓam) selon la majorité des savants, et sur quelle base l''établissent-ils ?','["Le nom ar-Raḥmān, car il n''est attribué qu''à Allah seul dans le Coran","Le nom al-Ḥayy al-Qayyūm, car ils sont toujours associés dans les passages les plus importants du Coran","Le nom « Allah », car tous les autres noms lui sont rattachés, il englobe les significations des autres noms, et il est le seul retrouvé dans tous les hadiths mentionnant le Nom Suprême","Le nom al-Aḥad, car la sourate al-Ikhlāṣ l''établit comme unique et indivisible"]'::jsonb,2,'La majorité des savants dit que le Nom Suprême est « Allah », pour plusieurs raisons : tous les autres noms lui sont rattachés, il englobe les significations des autres noms, il est le nom propre d''Allah, et il est le seul retrouvé dans tous les hadiths mentionnant le Nom Suprême. Il est aussi le plus mentionné dans le Coran, plus de 2000 fois.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',6,'Deuxième règle : Les Noms d''Allah sont à la fois des dénominatifs et des qualificatifs',null,6) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','La deuxième règle affirme que les Noms d''Allah sont à la fois des dénominatifs et des qualificatifs. En tant que dénominatifs, que désignent-ils ?','["Ils désignent tous la même et unique entité, qui est Allah","Ils désignent chacun un attribut distinct et parfait qu''Allah possède","Ils désignent les actes d''Allah dans la création et dans le gouvernement de l''univers","Ils désignent les prières et invocations qui Lui sont adressées par Ses serviteurs"]'::jsonb,0,'Les Noms d''Allah sont des dénominatifs par considération d''indication de l''entité : ils désignent tous la même entité, à savoir Allah. Du point de vue de l''entité désignée, ils sont donc comme des synonymes.',1),
   (t,c,'facile','La deuxième règle affirme que les Noms d''Allah sont à la fois des dénominatifs et des qualificatifs. En tant que qualificatifs, que désignent-ils ?','["Ils renvoient tous au même Être unique sans aucune distinction de sens entre eux","Ils indiquent chacun un sens et un attribut propre d''Allah","Ils désignent les actes d''adoration que les serviteurs doivent accomplir envers Allah","Ils désignent les créatures qu''Allah a formées selon Sa sagesse absolue"]'::jsonb,1,'Les Noms d''Allah sont des qualificatifs par considération d''indication des sens : chaque Nom indique un attribut particulier d''Allah. Le sens du Vivant est différent de l''Omniscient, qui lui-même est différent du Capable, et ainsi de suite.',2),
   (t,c,'facile','Du point de vue de l''entité désignée, les Noms d''Allah sont-ils synonymes ou distincts ? Du point de vue des significations, sont-ils synonymes ou distincts ?','["Synonymes sous les deux angles à la fois","Distincts du point de vue de l''entité ; synonymes du point de vue des significations","Distincts sous les deux angles à la fois","Synonymes du point de vue de l''entité ; distincts du point de vue des significations"]'::jsonb,3,'En fonction de la première considération (l''entité désignée), les Noms sont synonymes car tous indiquent le même dénominatif qui est Allah. En fonction de la deuxième considération (les sens), ils sont différents car chacun a un sens propre : le sens du Vivant est différent de l''Omniscient, qui lui-même est différent du Capable.',3),
   (t,c,'facile','Quel exemple illustre qu''un nom humain peut ne pas refléter la réalité de son porteur ?','["Appeler quelqu''un al-Amīn alors qu''il est malhonnête dans ses transactions","Appeler quelqu''un Karīm (généreux) alors qu''il ne l''est pas, ou al-Ghanī (riche) alors qu''il ne l''est pas","Appeler quelqu''un al-Ḥakīm (sage) alors qu''il n''a reçu aucune formation religieuse","Appeler quelqu''un al-Qawī (fort) alors qu''il est physiquement très faible"]'::jsonb,1,'Lorsqu''on appelle une personne al-Ghanī (le riche), cela ne signifie pas forcément qu''il est riche. De même, si on appelle quelqu''un Karīm, cela ne garantit pas qu''il est réellement généreux. Ce ne sont que des noms propres, sans que leurs significations soient toujours applicables.',4),
   (t,c,'facile','Quelle est la différence entre les noms humains et les Noms d''Allah quant à leur lien avec les attributs ?','["Les noms humains sont toujours liés à un attribut réel, contrairement aux Noms divins qui sont purement formels","Les deux catégories de noms ne sont jamais nécessairement liées à l''attribut réel de leur porteur","Les noms humains ne sont pas forcément liés à un attribut réel, tandis que les Noms d''Allah désignent toujours des attributs qu''Il possède en perfection absolue","Les deux catégories sont nécessairement liées à un attribut réel et parfait de leur porteur respectif"]'::jsonb,2,'Les noms des hommes ne sont pas nécessairement liés à un attribut et ne peuvent être que de simples noms propres, sans lien avec les caractéristiques de la personne. En revanche, lorsqu''Allah Se nomme al-Karīm ou al-Ghanī, ces Noms désignent véritablement des attributs qu''Il possède en perfection absolue.',5),
   (t,c,'facile','Quelle est la position des Jahmiyyah concernant les Noms et attributs d''Allah ?','["Ils nient tous les Noms et tous les attributs d''Allah","Ils acceptent les Noms d''Allah mais nient les attributs que ces Noms contiennent","Ils affirment les attributs mais nient que les Noms leur correspondent directement","Ils acceptent sept attributs fondamentaux et rejettent tous les autres comme relevant de l''anthropomorphisme"]'::jsonb,0,'Les Jahmiyyah nient tous les Noms et les attributs d''Allah. Cette position contredit le Coran et le bon sens.',6),
   (t,c,'facile','Quelle est la position des Muʿtazila concernant les Noms et attributs d''Allah ?','["Ils nient les Noms d''Allah tout en acceptant les attributs qui y correspondent","Ils nient à la fois tous les Noms et tous les attributs, comme le font les Jahmiyyah","Ils acceptent les Noms d''Allah mais nient les attributs que ces Noms contiennent","Ils acceptent intégralement les Noms et les attributs sans aucune restriction ni interprétation"]'::jsonb,2,'Les Muʿtazila acceptent les Noms d''Allah mais nient les attributs qu''ils contiennent. Cela est incohérent : comment un Nom pourrait-il ne pas contenir ce qu''il désigne ?',7),
   (t,c,'facile','Quel argument les négationnistes des attributs avancent-ils pour justifier leur rejet ?','["Que les attributs divins sont totalement inconnaissables et ne peuvent donc être affirmés par les humains","Que l''affirmation de plusieurs attributs implique une multiplicité d''entités anciennes, contredisant le Tawḥīd","Que les attributs ne sont mentionnés que dans des hadiths de chaîne transmissive affaiblie","Que les attributs sont une propriété exclusive aux créatures et ne peuvent s''appliquer à Allah"]'::jsonb,1,'Les négationnistes justifient leur position en prétendant que l''affirmation des attributs implique une multiplicité d''entités anciennes. En réalité, cette raison est erronée ou plutôt caduque, et son invalidité est démontrée par les textes scripturaires et la raison.',8),
   (t,c,'facile','Que signifie le fait que les Noms d''Allah sont tawqīfiyya ?','["Qu''ils sont fixés par le consensus des savants à travers les siècles","Qu''ils ne peuvent être prononcés qu''en arabe classique dans les invocations","Qu''ils ne peuvent provenir que du Coran et de la Sunna authentique ; il est illicite de nommer Allah sans preuve révélée","Qu''ils doivent être traduits avec précision dans toutes les langues pour être valides"]'::jsonb,2,'Les Noms d''Allah sont tawqīfiyya : seuls les textes révélés peuvent établir un Nom d''Allah. Ils ne peuvent être inventés ni ajoutés par la raison, et doivent nécessairement provenir du Coran et de la Sunna authentique, car nul ne connaît ce qui revient à Allah si ce n''est Lui-même.',9),
   (t,c,'facile','Pourquoi ad-dahr (le temps) n''est-il pas l''un des Noms d''Allah ?','["Parce que les savants l''ont exclu par consensus explicite de la liste des Noms divins","Parce qu''il s''agit d''un mot emprunté à d''autres langues et non purement arabe","Parce qu''il n''apparaît que dans des hadiths dont l''authenticité est fortement contestée","Parce que c''est un nom figé et non dérivé, sans sens de perfection, désignant simplement un laps de temps sans impliquer aucun attribut réel"]'::jsonb,3,'Ad-dahr est un nom figé (ism jāmid) et non dérivé. Il ne contient pas un sens de perfection, désigne simplement un laps de temps ou une période, et n''implique aucun attribut réel tel que la puissance, la connaissance ou la sagesse. Contrairement aux noms divins parfaits, ce nom ne peut être attribué à Allah comme nom tawqīfī.',10),
   (t,c,'moyenne','La preuve linguistique de la deuxième règle s''appuie sur le consensus des linguistes. En quoi consiste ce consensus ?','["On ne dit d''une personne qu''elle est ʿAlīm que si elle a la science, Samīʿ que si elle entend, Baṣīr que si elle voit — dire audient sans ouïe est donc incohérent","Les linguistes admettent que les noms arabes peuvent désigner des qualités sans que leur porteur les possède nécessairement dans les faits","Le consensus stipule que seuls les noms dérivés d''un attribut actif peuvent être attribués à Allah dans les textes révélés","Les linguistes ont établi la liste exhaustive des Noms pouvant légitimement désigner Allah dans le Coran et la Sunna"]'::jsonb,0,'Selon le consensus des linguistes, on ne dit d''une personne qu''elle est ʿAlīm que si elle possède la science, Samīʿ que si elle entend, Baṣīr que si elle voit, Qawī que si elle a la force. Il est incohérent de dire d''un être qu''il est audient sans ouïe ou voyant sans vision, car cela contredit le sens même du mot.',11),
   (t,c,'moyenne','Dans la deuxième règle, les versets de la sourate al-Aḥqāf (v.8) et de la sourate al-Kahf (v.58) sont mis en parallèle. Comment s''interprètent-ils mutuellement ?','["Le premier établit l''unicité d''Allah et le second confirme que Sa miséricorde est réservée aux seuls croyants","Ils affirment strictement la même chose sans apport interprétatif l''un pour l''autre","Le premier nomme Allah ar-Raḥīm ; le second précise qu''Il est dhū ar-raḥma, montrant que le Nom exprime un attribut réel et n''est pas une appellation figée","Le premier concerne toute la création dans ce monde et le second les croyants dans l''au-delà uniquement"]'::jsonb,2,'Ces deux versets s''interprètent l''un par l''autre : quand Allah se nomme ar-Raḥīm, la sourate al-Kahf précise qu''Il est dhū ar-raḥma (le Dieu de miséricorde), montrant qu''Il est qualifié par l''attribut de raḥma. Ainsi, le Nom n''est pas figé, mais il exprime l''attribut correspondant.',12),
   (t,c,'moyenne','La distinction dhāt (entité) / ṣifah (qualificatif), illustrée par l''exemple de la montre, permet d''établir une règle fondamentale sur les attributs d''Allah. Laquelle ?','["Les attributs d''Allah sont des entités indépendantes qui subsistent seules sans avoir besoin d''une essence","Affirmer plusieurs attributs à Allah implique nécessairement plusieurs essences distinctes et anciennes","Les attributs ne peuvent exister seuls ; affirmer plusieurs attributs à Allah n''implique donc aucune pluralité d''essences","Les attributs d''Allah et des créatures existent de manière identique, rattachés chacun à leur entité respective"]'::jsonb,2,'Le qualificatif/attribut est ce qui n''existe que rattaché à une entité et ne peut exister seul. Il est impossible de trouver dans la réalité une présence se baladant seule ou une couleur flottant sans support. Les attributs d''Allah n''impliquent donc aucune pluralité d''entités : c''est une seule essence possédant plusieurs attributs parfaits.',13),
   (t,c,'moyenne','La deuxième règle distingue ar-Raḥmān et ar-Raḥīm. Quelle différence de portée existe entre ces deux Noms ?','["Ar-Raḥmān désigne la miséricorde pour les croyants dans l''au-delà ; ar-Raḥīm désigne celle pour toute la création dans ce monde","Ar-Raḥmān désigne Celui dont la miséricorde englobe toute chose dans ce monde ; ar-Raḥīm renvoie à une miséricorde particulière accordée à qui Il veut parmi Ses serviteurs","Ar-Raḥmān et ar-Raḥīm sont de parfaits synonymes désignant rigoureusement la même réalité sans distinction possible","Ar-Raḥmān désigne la miséricorde dans l''au-delà uniquement ; ar-Raḥīm désigne la miséricorde spéciale dans ce monde"]'::jsonb,1,'Ar-Raḥmān désigne Celui dont la Miséricorde englobe toute chose : croyants et non-croyants, dans ce monde. Tandis qu''ar-Raḥīm renvoie à une miséricorde particulière qu''Allah accorde à qui Il veut parmi Ses serviteurs, comme quand Il dit : « Il est Très Miséricordieux envers les croyants » (Sourate Al-Ahzâb, v.43).',14),
   (t,c,'moyenne','La preuve rationnelle (ʿaqlī) de la deuxième règle établit que toute chose existante possède au minimum trois qualificatifs fondamentaux. Lesquels ?','["La puissance, la connaissance et la volonté, qui sont les trois attributs premiers de toute existence","La création à partir du néant, la subsistance dans le temps, et la disparition à un terme fixé","L''attribut de présence, le type de présence (nécessaire ou possible), et la nature de l''existence (entité ou attribut rattaché à autre chose)","Le nom propre qui identifie, le qualificatif qui décrit, et l''acte qui se manifeste dans la réalité"]'::jsonb,2,'Toute chose existante a au minimum trois qualificatifs : 1. L''attribut de présence (tout ce qui existe est présent). 2. Le type de présence : soit wājib al-wujūd (existence nécessaire, seul Allah), soit mumkin al-wujūd (existence possible, tout le reste). 3. La nature de l''existence : entité subsistant par elle-même, ou attribut subsistant dans une autre entité.',15),
   (t,c,'difficile','Les négationnistes soutiennent qu''affirmer plusieurs attributs divins impliquerait une multiplicité d''entités anciennes. Comment la preuve rationnelle de la deuxième règle invalide-t-elle cet argument ?','["En montrant que le Coran interdit d''interpréter l''affirmation des attributs comme impliquant une quelconque multiplicité d''entités indépendantes","En invoquant le consensus des savants qui ont unanimement affirmé les attributs sans que cela porte atteinte à l''unicité d''Allah","En établissant que les attributs ne sont pas des entités indépendantes mais des qualificatifs subsistant dans le qualifié, de même qu''un homme peut être savant, courageux et patient sans être plusieurs personnes","En démontrant que la philosophie islamique rend logiquement incompatible toute notion d''entité ancienne avec un monothéisme pur et authentique"]'::jsonb,2,'Les attributs ne sont pas des entités pour que leur affirmation nécessite la pluralité des entités : ils sont des qualificatifs du qualifié et présents chez lui. Il est logiquement admis qu''une seule entité peut être décrite par plusieurs attributs — un homme peut être savant, généreux, courageux, patient sans être plusieurs personnes. Les attributs d''Allah n''impliquent donc aucune pluralité d''entités.',16),
   (t,c,'difficile','La sourate al-Burūj (85:12-16) et la sourate al-Aʿlā sont citées dans la deuxième règle. En quoi réfutent-elles la thèse des négationnistes des attributs ?','["Ces versets affirment la transcendance absolue d''Allah qui dépasse toute description, invalidant toute attribution d''attributs ressemblant à ceux des créatures","Ces versets mentionnent un seul qualifié (Allah) auquel sont attribués de nombreux Noms et qualificatifs dans un même passage, prouvant que la multiplicité des attributs ne contredit pas l''unicité de l''essence","Ces versets interdisent explicitement de nier les attributs d''Allah en qualifiant cette négation d''acte de mécréance grave et manifeste","Ces versets établissent que seuls sept attributs fondamentaux peuvent être affirmés, invalidant l''idée d''une multiplicité illimitée d''attributs divins"]'::jsonb,1,'Allah s''est décrit Lui-même avec de nombreux qualificatifs malgré qu''Il soit l''Unique : dans la sourate al-Burūj, Il est le Pardonneur, le Tout-Affectueux, le Maître du Trône, le Tout-Glorieux. Dans ces nobles versets, il y a de nombreux qualificatifs d''un seul et unique qualifié, or cela n''implique pas la duplicité d''entités anciennes.',17),
   (t,c,'difficile','La deuxième règle précise que l''ambiguïté des négationnistes repose sur une confusion entre deux réalités. Lesquelles ?','["Ils confondent les attributs d''essence avec les attributs d''action en les traitant de manière strictement identique sans distinction aucune","Ils confondent les preuves textuelles et les preuves rationnelles en accordant une priorité excessive à la philosophie sur le Coran","Ils confondent la négation légitime des imperfections avec la négation illégitime des attributs positifs, tombant dans le taʿṭīl pur","Ils confondent l''existence d''un attribut rattaché à une essence avec une existence indépendante, sans distinguer entre l''essence et l''attribut"]'::jsonb,3,'Cette ambiguïté est fausse, car elle ne distingue pas l''essence de l''attribut, et confond l''existence de l''attribut dans une essence avec l''existence indépendante. Les attributs sont bien réels, mais ils n''existent pas indépendamment d''Allah. Ce sont des qualificatifs du Qualifié (ṣifāt li-l-mawṣūf) et ils subsistent en Lui.',18),
   (t,c,'difficile','La règle tawqīfiyya des Noms d''Allah interdit de nommer Allah sans preuve révélée. Sur quel verset cette interdiction s''appuie-t-elle et quelle en est la raison fondamentale ?','["Sur la sourate al-Ikhlāṣ, car elle définit l''unicité d''Allah de manière exhaustive et constitue une liste limitative des attributs essentiels","Sur la sourate al-Fātiḥa, car elle contient l''ensemble des attributs indispensables à la connaissance d''Allah et forme un cadre complet","Sur la sourate al-Isrāʾ (17:36) : nul ne connaît ce qui revient à Allah si ce n''est Lui-même, et nommer Allah sans preuve revient à affirmer ce dont on n''est pas certain","Sur la sourate al-Aʿrāf (7:180), car elle interdit expressément toutes les formes de profanation dans les Noms d''Allah"]'::jsonb,2,'Les Noms d''Allah ne peuvent être inventés ni ajoutés par la raison, car nul ne connaît ce qui revient à Allah si ce n''est Lui-même. La preuve : « N''affirme rien dont tu ne sois certain. De l''ouïe, de la vue et du cœur, de tout cela, chacun devra répondre. » (Sourate al-Isrāʾ, 17:36). Il est donc interdit de donner à Allah un nom sans preuve claire du Coran ou de la Sunna.',19),
   (t,c,'difficile','Si l''on acceptait la thèse muʿtazilite — Allah serait « audient sans ouïe, voyant sans vue, fort sans force » — quelle contradiction logique produirait-elle selon la deuxième règle ?','["Cela rendrait la règle tawqīfiyya inapplicable, puisque des Noms sans sens propre ne pourraient plus servir de référence","Cela impliquerait que tous les Noms d''Allah sont de parfaits synonymes sans aucune distinction de sens entre eux","Cela contredirait la règle tawqīfiyya en introduisant des Noms non mentionnés dans le Coran ni la Sunna","Cela reviendrait à traiter les Noms d''Allah comme les noms humains — appeler Karīm celui qui n''est pas généreux —, ce que réfute le consensus des linguistes : on n''appelle audient que celui qui entend"]'::jsonb,3,'Dire qu''Allah est audient sans ouïe ou voyant sans vue contredit le sens même du mot selon le consensus des linguistes : on n''appelle audient que celui qui entend, voyant que celui qui voit. Cela reviendrait à traiter les Noms d''Allah comme les noms des humains — appeler Karīm quelqu''un qui n''est pas généreux. C''est pourquoi on comprend l''égarement des négationnistes des sens des Noms d''Allah.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',7,'Les preuves que les Noms d''Allah sont à la fois dénominatifs et qualificatifs','23/07/2025',7) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Selon la deuxième règle, que montrent les Noms d''Allah par considération d''indication de l''entité ?','["Ils sont synonymes car tous indiquent le même dénominatif qui est Allah","Ils sont opposés car chacun désigne une créature différente","Ils sont des verbes sans sens qualificatif","Ils ne renvoient à aucune réalité"]'::jsonb,0,'Dans la deuxième règle, il est dit qu''ils sont des dénominatifs par considération d''indication de l''entité et qu''en fonction de cette considération ils sont synonymes car tous indiquent le même dénominatif qui est Allah.',1),
   (t,c,'facile','Selon la deuxième règle, que montrent les Noms d''Allah par considération d''indication des sens ?','["Ils sont différents car chacun a un sens","Ils sont identiques car tous ont exactement la même signification","Ils sont vides de sens mais utiles pour la récitation","Ils désignent seulement des actes humains"]'::jsonb,0,'Dans la deuxième règle, il est dit qu''ils sont des qualificatifs par considération d''indication des sens et qu''en fonction de cette considération ils sont différents car chacun a un sens.',2),
   (t,c,'facile','Dans Sourate Ach-Choura, v. 19, « Et Il est le Fort, le Tout-Puissant », quel Nom est présenté comme un nom qui est en même temps une qualité ?','["Al-Qawiyy","Ad-Dahr","Al-Insān","Al-Qalam"]'::jsonb,0,'Dans la partie sur les preuves du Coran et de la Sunna, le passage de Sourate Ach-Choura, v. 19 dit qu''Allah s''est nommé par al-Qawiyy, un nom qui est en même temps une qualité.',3),
   (t,c,'facile','Dans Sourate al-Kahf, v. 58, « Ton Seigneur est le Pardonneur, le détenteur de la miséricorde », que montre l''expression « le détenteur de la miséricorde » ?','["Que le Très Miséricordieux est qualifié de la miséricorde","Que la miséricorde n''est qu''un nom sans signification","Que la miséricorde appartient aux créatures seulement","Que le pardon annule tous les autres attributs"]'::jsonb,0,'Dans l''explication de Sourate al-Kahf, v. 58, il est dit que ce verset montre que le Très Miséricordieux est qualifié de la miséricorde.',4),
   (t,c,'facile','Dans Sourate Al-Aʿrāf, v. 180, « C''est Allah qui possède les noms les plus sublimes. Invoquez-Le donc par ces noms », que signifie al-asmāʾ al-ḥusnā ?','["Les noms les plus beaux et parfaits","Les noms les plus rares parmi les hommes","Les noms qui n''ont pas de sens qualificatif","Les noms réservés au temps et aux créatures"]'::jsonb,0,'Dans le sous-chapitre sur les noms extrêmement beaux et bons, le terme al-asmāʾ al-ḥusnā est expliqué comme signifiant « les noms les plus beaux et parfaits ».',5),
   (t,c,'facile','Quel groupe est présenté comme affirmant les noms d''Allah tout en n''acceptant pas Ses attributs ?','["Les Muʿtazila","Les linguistes","Les pieux prédécesseurs","Les traditionnistes du hadith"]'::jsonb,0,'Dans la section « Argumentation des négationnistes et réfutations », il est dit que les Muʿtazila affirment les noms d''Allah mais n''acceptent pas Ses attributs.',6),
   (t,c,'facile','Dans la première réfutation des négationnistes, quelle voie est attribuée aux pieux prédécesseurs ?','["Affirmer les noms et attributs d''Allah","Affirmer les noms mais renier les attributs","Renier tous les noms et attributs","Employer le mot corps sans réserve"]'::jsonb,0,'Dans la première réfutation, il est écrit : « Affirmer les noms et attributs d''Allah, voie des pieux prédécesseurs ».',7),
   (t,c,'facile','Que montrent les invocations prophétiques « Je cherche protection auprès de la puissance d''Allah » et « Je cherche protection auprès de la miséricorde d''Allah » ?','["Que Ses noms et attributs possèdent un sens réel et intemporel","Que les invocations se limitent aux créatures","Que les attributs n''ont aucune signification","Que seuls les verbes peuvent décrire Allah"]'::jsonb,0,'Dans les exemples tirés des invocations prophétiques, il est dit que l''usage des maṣādir montre que Ses noms et attributs possèdent un sens réel et intemporel.',8),
   (t,c,'facile','Quel principe est rappelé dans la partie sur le consensus des linguistes ?','["On ne peut pas qualifier quelqu''un de savant s''il n''a pas de savoir","Tout nom qualifie une entité même sans réalité","Les noms n''ont aucun lien avec les attributs","Un audient peut être qualifié sans ouïe"]'::jsonb,0,'Dans la section sur le consensus, il est rappelé qu''on ne peut pas qualifier quelqu''un de savant s''il n''a pas de savoir, ni quelqu''un d''audient s''il n''a pas d''ouïe.',9),
   (t,c,'facile','Selon le sous-chapitre sur le statut linguistique du mot ad-Dahr, quel est ce mot ?','["Un nom figé non dérivé","Un nom dérivé renvoyant à la miséricorde","Un attribut de perfection","Un des noms les plus sublimes"]'::jsonb,0,'Dans le sous-chapitre sur le statut linguistique du mot ad-Dahr, il est dit que le mot ad-Dahr est un nom figé et non un nom dérivé.',10),
   (t,c,'moyenne','Dans Sourate Adh-Dhâriyât, v. 58, « C''est Allah, en vérité, qui est le Dispensateur de toute grâce et le Détenteur de la force et de la toute-puissance », pourquoi l''expression « le Détenteur de la force » sert-elle de preuve ?','["Parce qu''elle montre que le Nom al-Qawiyy renferme réellement la qualité de force","Parce qu''elle prouve que la force est une créature séparée","Parce qu''elle montre que les noms divins sont dépourvus de sens","Parce qu''elle limite la force au monde visible"]'::jsonb,0,'Dans la partie sur les maṣādir, il est dit que l''emploi de « le Détenteur de la force » montre que le Nom al-Qawiyy renferme réellement la qualité de force.',11),
   (t,c,'moyenne','Dans Sourate Al-Kahf, v. 1, « Louange à Allah qui a révélé à Son serviteur le Coran, Livre qui par Sa grâce ne s''écarte jamais de la vérité », pourquoi ce passage est-il mentionné ?','["Pour montrer que le Coran est exempt de futilité ou d''erreur","Pour montrer que les noms divins changent selon les lecteurs","Pour prouver que les attributs sont de simples métaphores","Pour établir que les lois n''ont pas de sagesse"]'::jsonb,0,'Dans le sous-chapitre sur la justification des législations et des actions par des noms appropriés, ce passage est cité pour montrer que le Coran est exempt de futilité ou d''erreur.',12),
   (t,c,'moyenne','Dans l''anecdote rapportée par Ibn al-Qayyim, pourquoi le bédouin rejette-t-il la lecture « Allah est Pardonneur, Miséricordieux » à la place de « Allah est Fort et Sage » dans le verset sur le voleur ?','["Parce que l''inversion des Noms change le sens du jugement et de la législation","Parce que les deux formulations ont exactement le même sens","Parce que le bédouin refusait toute récitation","Parce que le passage parlait de miséricorde et non de châtiment"]'::jsonb,0,'Dans l''anecdote rapportée par Ibn al-Qayyim, il est dit que l''inversion des Noms change le sens du jugement et de la législation.',13),
   (t,c,'moyenne','Dans la section « Les catégories de mots et les noms d''Allah », comment les Noms d''Allah sont-ils considérés lorsqu''ils sont dénominatifs ?','["Comme des synonymes car tous renvoient à la même entité divine","Comme des mots associés dont le sens change selon le contexte","Comme des mots globaux sans membre précis","Comme des noms humains renvoyant à des entités multiples"]'::jsonb,0,'Dans la section sur les catégories de mots, il est dit que les noms d''Allah, lorsqu''ils sont dénominatifs, sont considérés comme des synonymes car tous renvoient à la même entité divine.',14),
   (t,c,'moyenne','Selon le sous-chapitre sur le statut linguistique du mot ad-Dahr, pourquoi ad-Dahr ne peut-il pas être un Nom d''Allah ?','["Parce qu''il est figé, non dérivé, et ne renvoie pas à un attribut de perfection","Parce qu''il est le plus beau de tous les noms","Parce qu''il est un verbe d''action intemporel","Parce qu''il est cité comme attribut essentiel de miséricorde"]'::jsonb,0,'Dans le sous-chapitre sur le statut linguistique du mot ad-Dahr, il est précisé qu''il est figé, non dérivé, et qu''il ne répond à aucune des conditions des Noms d''Allah.',15),
   (t,c,'difficile','Dans Sourate Ach-Choura, v. 11, « Rien ne Lui est comparable, et Il entend tout et voit tout », quelle réfutation est apportée à ceux qui nient les attributs par peur de l''assimilation ?','["Affirmer les attributs n''implique pas de ressemblance avec les créatures","Toute affirmation d''attribut implique nécessairement un corps","Il faut nier l''ouïe et la vue pour éviter l''anthropomorphisme","La négation des attributs est la seule manière d''affirmer l''unicité"]'::jsonb,0,'Dans la réfutation par le Coran et la Sunnah, ce passage de Sourate Ach-Choura, v. 11 montre qu''Allah est l''Audient et le Voyant alors que rien ne Lui est comparable.',16),
   (t,c,'difficile','Dans la réfutation de l''argument sur les corps, quel exemple est donné pour montrer que tout ce qui est qualifié n''est pas forcément corporel ?','["La nuit peut être qualifiée de froide, bien qu''elle ne soit pas un corps","Le soleil peut être qualifié de lumineux parce qu''il est un corps","L''homme peut être qualifié de vivant parce qu''il a un corps","L''ange peut être qualifié de fort parce qu''il ressemble à l''homme"]'::jsonb,0,'Dans la septième réfutation, l''exemple donné est que la nuit peut être qualifiée de froide, bien qu''elle ne soit pas un corps.',17),
   (t,c,'difficile','Pourquoi la prétention selon laquelle tous les corps sont identiques est-elle rejetée ?','["Parce que le corps humain diffère de celui des djinns, des anges ou des animaux","Parce que tous les corps possèdent exactement les mêmes qualités","Parce que les corps sont une illusion linguistique","Parce que seul le corps humain existe réellement"]'::jsonb,0,'Dans la huitième réfutation, il est dit que cette prétention est fausse, car le corps humain diffère de celui des djinns, des anges ou des animaux.',18),
   (t,c,'difficile','Dans le hadith rapporté par Al-Boukhari, n°7491, et Muslim, n°2246, « Le fils d''Adam m''offense : il insulte le temps, alors que Je suis le temps. Dans Ma Main est le commandement, et c''est Moi qui fais tourner la nuit et le jour », pourquoi ad-Dahr n''est-il pas un Nom d''Allah ?','["Parce qu''Allah est le Créateur du temps et de ce qu''il contient, et l''intervertisseur ne peut pas être confondu avec ce qui est interverti","Parce que le hadith affirme explicitement qu''ad-Dahr est un des noms les plus sublimes","Parce que le temps est un attribut de perfection au même titre que la science","Parce que le temps désigne directement l''essence divine sans aucune précision"]'::jsonb,0,'Dans le sous-chapitre sur le sens réel du hadith « Je suis le temps », il est expliqué qu''Allah est le Créateur du temps et de ce qu''il contient, et qu''il est impossible que l''intervertisseur soit interverti.',19),
   (t,c,'difficile','Dans Sourate al-Jāthiyah, v. 24, « Il n''y a rien après la mort. Une génération disparaît, remplacée par une autre. Le temps passe et nous emporte », quelle conclusion est tirée de l''attribution de l''action au temps ?','["Croire que le temps agit de lui-même constitue un shirk majeur","Le temps est une divinité secondaire","Le temps est un attribut indépendant d''Allah","Cette parole est une simple description autorisée du temps"]'::jsonb,0,'Dans la réfutation de ceux qui attribuent l''action au temps, il est dit que croire que le temps agit de lui-même constitue un shirk majeur, car cela attribue à la création une action qui revient exclusivement au Créateur.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',8,'Troisième et Quatrième règle sur les Noms d''Allah : attributs transitifs/intransitifs et modes de désignation','27/07/2025',8) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Selon la troisième règle, combien d''éléments comprend un Nom d''Allah dont l''attribut est transitif (ṣifah mutaʿaddiya) ?','["Un seul : l''affirmation du Nom suffit à tout englober","Deux : le Nom et l''attribut qu''il contient","Trois : le Nom, l''attribut, et l''effet de l''attribut sur la création","Quatre : le Nom, l''attribut, l''effet sur la création et la jurisprudence"]'::jsonb,2,'La troisième règle stipule que si un Nom d''Allah indique un attribut transitif, il comprend trois éléments : l''affirmation de ce Nom, l''affirmation du qualificatif d''Allah contenu dans ce Nom, et l''affirmation du statut de ce qualificatif et de ce qu''il implique.',1),
   (t,c,'facile','Selon la troisième règle, combien d''éléments comprend un Nom d''Allah dont l''attribut est intransitif (ṣifah lāzim) ?','["Deux : l''affirmation du Nom et l''affirmation de l''attribut contenu dans ce Nom","Trois : l''affirmation du Nom, de l''attribut et de son effet sur la création","Un seul : l''affirmation du Nom d''Allah suffit à tout englober logiquement","Quatre : le Nom, l''attribut, l''effet et la jurisprudence correspondante"]'::jsonb,0,'Si le Nom indique un attribut intransitif, il comprend deux éléments seulement : l''affirmation de ce Nom d''Allah et l''affirmation du qualificatif d''Allah contenu dans ce Nom.',2),
   (t,c,'facile','Quel Nom d''Allah est donné comme exemple d''attribut transitif dans la troisième règle ?','["Al-Ḥayy (Le Vivant), dont la vie est un attribut essentiel propre à l''Être divin","Al-ʿAẓīm (L''Immense), dont la grandeur n''a aucun lien avec la création","As-Samīʿ (L''Audient), dont l''ouïe a un effet sur la création","Al-Qayyūm (Le Subsistant), dont l''attribut ne produit pas d''effet observable"]'::jsonb,2,'L''exemple donné pour un attribut transitif est as-Samīʿ (L''Audient) : il contient l''affirmation de l''Audient comme Nom d''Allah, l''affirmation de l''ouïe comme qualificatif, et l''affirmation de ce qu''il implique — qu''Allah entend le secret et la confidence.',3),
   (t,c,'facile','Quel Nom d''Allah est donné comme exemple d''attribut intransitif dans la troisième règle ?','["As-Samīʿ (L''Audient), dont l''ouïe est liée à ce qui se passe chez les créatures","Al-Ghafūr (Le Pardonneur), dont le pardon a un effet réel sur les individus repentants","Al-Ḥayy (Le Vivant), dont l''attribut de vie n''a pas d''effet apparent dans la création","Ar-Razzāq (Celui qui pourvoit), dont l''action se manifeste dans l''univers créé"]'::jsonb,2,'L''exemple donné pour un attribut intransitif est al-Ḥayy (Le Vivant) : on affirme le Nom al-Ḥayy et l''attribut de la vie comme qualificatif d''Allah, sans qu''il y ait d''effet direct sur les créatures.',4),
   (t,c,'facile','Quelle est la définition d''un attribut transitif selon la troisième règle ?','["Un attribut qui a un lien, un impact ou un effet sur autre qu''Allah, c''est-à-dire sur la création","Un attribut propre à Allah Lui-même qui n''a aucune trace ni effet dans l''univers que nous connaissons","Un attribut dont l''affirmation nécessite d''invoquer un Nom complémentaire pour exprimer la perfection globale","Un attribut mentionné uniquement dans le Coran et absent de la Sunna du Prophète"]'::jsonb,0,'Les attributs transitifs sont ceux qui ont un lien, un impact, une influence, un effet ou une trace sur autre qu''Allah, c''est-à-dire sur la création.',5),
   (t,c,'facile','Quelle est la définition d''un attribut intransitif selon la troisième règle ?','["Un attribut qui produit un effet observable sur les créatures selon la volonté d''Allah dans la création","Un attribut propre à Allah Lui-même, sans aucune trace ni effet dans l''univers que nous connaissons","Un attribut qui ne peut être affirmé qu''en le jumelant avec son Nom complémentaire correspondant","Un attribut établi uniquement par des versets coraniques, sans preuve dans la Sunna prophétique"]'::jsonb,1,'Les attributs intransitifs sont les qualificatifs propres à Allah Lui-même, qui n''ont aucune trace ni effet dans l''univers que nous connaissons.',6),
   (t,c,'facile','La quatrième règle énonce que les Noms d''Allah désignent Son Être et Ses attributs de trois façons. Lesquelles ?','["Par affirmation globale, par négation détaillée et par implication logique nécessaire","Par le Coran exclusivement, par la Sunna exclusivement et par les deux réunis","Par correspondance (al-muṭābaqa), par inclusion (at-taḍammun) et par implication (al-iltizām)","Par les savants anciens, par les savants modernes et par le consensus de l''ensemble des juristes"]'::jsonb,2,'La quatrième règle établit que l''indication des Noms d''Allah de Son entité et de Ses attributs est soit par correspondance (al-muṭābaqa), soit par inclusion (at-taḍammun), soit par implication (al-iltizām).',7),
   (t,c,'facile','Dans la quatrième règle, qu''est-ce que la correspondance complète (al-muṭābaqa) ?','["Le mot implique une chose extérieure logiquement liée à lui, non mentionnée explicitement dans le texte","Le mot désigne uniquement une partie de ce qu''il représente, en laissant de côté les autres parties","Le mot désigne l''ensemble complet de ce qu''il représente, entité et attribut réunis","Le mot désigne uniquement l''Essence d''Allah sans l''attribut correspondant qui lui est lié"]'::jsonb,2,'La correspondance (al-muṭābaqa) est lorsque le mot désigne l''ensemble complet de ce qu''il représente. Par exemple, le mot « maison » désigne toute la structure : murs, toiture, tuyauterie, etc.',8),
   (t,c,'facile','Dans la quatrième règle, qu''est-ce que l''inclusion partielle (at-taḍammun) ?','["Le mot désigne l''ensemble complet de ce qu''il représente, entité et attribut ensemble","Le mot implique un sens extérieur logiquement lié, non mentionné explicitement","Le mot désigne uniquement une partie de ce qu''il représente","Le mot désigne l''implication jurisprudentielle d''un attribut sans en citer la source"]'::jsonb,2,'L''inclusion (at-taḍammun) : le mot est utilisé pour désigner une partie de ce qu''il représente. Par exemple, « maison » pour désigner uniquement le mur ou la toiture.',9),
   (t,c,'facile','Dans la quatrième règle, qu''est-ce que l''implication nécessaire (al-iltizām) ?','["Le mot désigne l''ensemble complet de son contenu, entité et attribut réunis dans leur totalité","On déduit un sens indirectement impliqué par le mot, extérieur mais logiquement lié à lui","Le mot désigne uniquement l''entité divine pure sans aucun attribut qui lui soit associé","Le mot désigne une seule partie de ce qu''il représente en excluant les autres parties du concept"]'::jsonb,1,'L''implication (al-iltizām) : c''est lorsqu''on déduit un sens indirectement impliqué par le mot. Par exemple, lorsque tu entends « maison », tu comprends par implication qu''il y a eu des bâtisseurs, un architecte, etc.',10),
   (t,c,'moyenne','La troisième règle stipule que ne pas reconnaître l''effet d''un attribut transitif constitue un manquement dans la croyance. Quel exemple jurisprudentiel illustre l''importance concrète de cet effet ?','["Les savants ont établi que la prière reste valide même si le croyant ignore le sens du Nom as-Samīʿ et ses implications concrètes","Les savants ont fondé la suspension de la peine des brigands repentants sur al-Ghafūr et ar-Raḥīm, qui impliquent que le pardon et la miséricorde ont eu un effet réel sur eux","Les savants ont décidé que l''invocation n''est valablement exaucée que si le suppliant connaît l''intégralité des attributs dans leur détail","Les savants ont limité les effets des Noms transitifs aux seuls actes d''adoration surérogatoires accomplis avec une intention parfaitement pure"]'::jsonb,1,'Les érudits suspendent la peine des brigands en cas de repentance et justifient cela par le verset de la sourate Al-Māʾidah (v.34) : « sachez qu''Allah est Pardonneur et Miséricordieux ». Ces deux Noms impliquent qu''Allah a pardonné leurs péchés et leur a fait miséricorde en suspendant leur peine.',11),
   (t,c,'moyenne','Selon la troisième règle, quelle distinction fondamentale existe entre l''ouïe (as-Samʿ) et la vie (al-Ḥayāt) d''Allah ?','["L''ouïe est un attribut intransitif qui n''a aucun lien avec la création et la vie est un attribut transitif ayant un effet direct sur les créatures","L''ouïe est liée à ce qui se passe chez les créatures (attribut transitif) ; la vie est un attribut essentiel propre à l''Être divin (attribut intransitif)","L''ouïe et la vie sont toutes deux des attributs intransitifs, propres à l''Être divin, sans aucun effet observable sur la création","L''ouïe et la vie sont toutes deux des attributs transitifs ayant un impact direct et observable sur les créatures d''Allah"]'::jsonb,1,'L''ouïe (as-Samʿ) est liée à ce qui se passe chez les créatures — c''est un attribut transitif. La vie (al-Ḥayāt) est un attribut essentiel propre à l''Être divin, qui n''a pas d''effet apparent ou connu dans l''univers ou la création — c''est un attribut intransitif.',12),
   (t,c,'moyenne','Dans la quatrième règle, quel verset coranique est cité pour illustrer que le Nom al-Khāliq implique, par al-iltizām, la science et la puissance d''Allah ?','["Sourate al-Ikhlāṣ : « Dis : Il est Allah, Unique, Allah l''Absolu »","Sourate Ṭalāq, v.12 : « Vous saurez ainsi que le pouvoir d''Allah est absolu et que Sa science embrasse toute chose »","Sourate al-Baqara, v.255 : « Allah ! Point de divinité à part Lui. Il est le Vivant, le Subsistant »","Sourate al-Fātiḥa : « Louange à Allah, Seigneur de la Création, le Tout Miséricordieux, le Très Miséricordieux »"]'::jsonb,1,'La quatrième règle cite la sourate Ṭalāq (v.12) : « Vous saurez ainsi que le pouvoir d''Allah est absolu et que Sa science embrasse toute chose. » Ce verset illustre que le Nom al-Khāliq implique, par al-iltizām, la science et la puissance d''Allah.',13),
   (t,c,'moyenne','Selon le statut des implications (luzūm), quel est le statut de ce qu''impliquent les paroles d''Allah et de Son Messager ?','["Leurs implications sont vraies uniquement si elles sont corroborées par le consensus unanime des savants de l''Islam","Leurs implications sont nécessairement vraies, car la parole d''Allah et du Prophète est vérité, et ce qui en découle logiquement est aussi vérité","Leurs implications restent incertaines jusqu''à leur vérification, car les humains peuvent les mal interpréter et se tromper dans leur déduction","Leurs implications sont vraies uniquement lorsqu''elles concernent la jurisprudence pratique et non les questions de croyance et de doctrine"]'::jsonb,1,'Si l''implication vient d''Allah ou de Son Messager, elle est nécessairement vraie, car la parole d''Allah et du Prophète est vérité, et ce qui en découle logiquement est aussi vérité. De plus, Allah sait parfaitement ce que Ses paroles impliquent.',14),
   (t,c,'moyenne','Selon le statut des implications, lorsqu''on rappelle à un locuteur humain l''implication de sa parole et qu''il la rejette clairement, quel est le statut de cette implication ?','["Elle lui est attribuée car il a prononcé la parole initiale qui l''engendre nécessairement","Elle lui est attribuée uniquement si son rejet intervient après un débat formellement constitué","Elle ne lui est pas attribuée, car il ne croit pas que cette conséquence fasse partie de sa parole","Elle lui est attribuée par défaut jusqu''à ce que les savants compétents statuent autrement sur la question"]'::jsonb,2,'Lorsqu''on rappelle au locuteur l''implication de sa parole et qu''il l''exclut clairement, cette implication ne lui est pas attribuée, car il ne croit pas que cette conséquence fasse partie de sa parole.',15),
   (t,c,'difficile','Dans la troisième règle, pourquoi la croyance de celui qui reconnaît le Nom as-Samīʿ et l''attribut d''ouïe mais refuse de croire à leur manifestation dans la création est-elle qualifiée de déficiente, voire déviante ?','["Parce que les attributs transitifs n''ont de valeur que s''ils sont accompagnés des attributs intransitifs correspondants et ne peuvent être affirmés séparément","Parce que les Noms d''Allah comportent des effets réels ; nier l''effet d''un attribut transitif tout en reconnaissant le Nom et l''attribut constitue une croyance incomplète et déviante","Parce que la langue arabe impose que tout Nom soit suivi de la mention explicite et formelle de son effet sur la création pour être considéré comme valide","Parce que le consensus des savants exige que les attributs transitifs soient connus dans leur intégralité pour que la foi de la personne soit correcte"]'::jsonb,1,'Affirmer qu''Allah entend les sons et les voix implique de croire à cet effet réel. Si quelqu''un reconnaît le Nom et l''attribut mais refuse de croire à leur manifestation dans la création, sa croyance dans ce Nom est déficiente, voire déviante. L''auteur insiste sur ce point pour montrer que les Noms d''Allah comportent des effets et des conséquences réels.',16),
   (t,c,'difficile','Dans la quatrième règle, comment al-Khāliq (Le Créateur) illustre-t-il les trois modes de désignation simultanément ?','["Al-muṭābaqa : il désigne uniquement l''Essence divine ; at-taḍammun : il désigne uniquement l''attribut de création ; al-iltizām : il réunit les deux ensemble dans un sens complet","Al-muṭābaqa : il désigne Allah et Son acte de création ensemble ; at-taḍammun : il désigne soit l''Essence seule soit l''attribut seul ; al-iltizām : il implique logiquement la science et la puissance","Al-muṭābaqa : il implique la science et la puissance ; at-taḍammun : il désigne Allah et la création ensemble ; al-iltizām : il désigne une partie seulement du concept","Les trois modes sont identiques pour al-Khāliq et ne permettent aucune distinction sémantique significative ni utile pour l''étudiant"]'::jsonb,1,'Al-Khāliq désigne Son entité et le qualificatif de création par correspondance (al-muṭābaqa) ; il indique uniquement Son entité ou Son qualificatif par inclusion (at-taḍammun) ; enfin, il indique les qualificatifs d''omniscience et de puissance par implication (al-iltizām), comme le confirme la sourate Ṭalāq, v.12.',17),
   (t,c,'difficile','Le négationniste des attributs d''action objecte que les confirmer implique que certaines des actions d''Allah sont survenues dans le temps. Comment celui qui affirme les attributs d''action répond-il à cette objection ?','["En admettant entièrement l''objection mais en précisant que toutes les actions d''Allah sont anciennes et n''ont donc pas réellement eu lieu dans le temps créé","En répondant que oui, certaines actions d''Allah surviennent dans le temps, mais cela ne constitue pas une imperfection, car Ses paroles et Ses actions sont inépuisables et Il agit constamment selon Sa volonté","En répondant que cette objection est valide et que les attributs d''action doivent donc être interprétés figurément pour préserver l''unicité divine contre toute limitation temporelle","En renvoyant la question aux savants car cela dépasse la portée des règles fondamentales de la doctrine islamique standard"]'::jsonb,1,'Celui qui affirme les attributs d''action répond : « Oui, et je maintiens cela, car Allah n''a cessé et ne cessera de faire ce qu''Il veut. Ses paroles et Ses actions sont inépuisables. Et la survenance de certaines de Ses actions n''implique pas Son imperfection. » Cela est confirmé par les sourates al-Kahf (v.109) et Luqmān (v.27).',18),
   (t,c,'difficile','Le négationniste des attributs objecte : « Affirmer les qualificatifs d''Allah implique que Ses attributs sont semblables à ceux des êtres. » Quelle réponse est donnée dans le cours ?','["Que cette implication est correcte et qu''il faut donc nier les attributs pour éviter toute forme d''anthropomorphisme condamnable","Que cela ne l''implique pas car les attributs du Créateur sont spécifiques à Lui ; de plus, le négationniste affirme lui-même une entité pour Allah sans assimilation — quelle différence avec les attributs ?","Que cette implication est valide pour les attributs d''essence mais fausse pour les attributs d''action d''Allah","Que la ressemblance est inévitable dans tout langage humain et que seule la négation totale de tous les attributs préserve un Tawḥīd authentiquement pur"]'::jsonb,1,'Celui qui confirme les attributs répond : non, cela ne l''implique pas, car les attributs du Créateur sont annexés à Lui et spécifiques à Lui et dignes de Lui. Il ajoute : « Tu confirmes qu''Allah a une entité tout en excluant son assimilation aux entités des êtres — quelle différence y a-t-il entre l''entité et les attributs ? »',19),
   (t,c,'difficile','Selon le statut des implications, pourquoi ne peut-on pas attribuer à un locuteur humain l''implication de sa parole lorsqu''il ne s''est pas prononcé sur elle ?','["Parce que la parole humaine est dépourvue de valeur sémantique en matière de doctrine et de croyance islamique","Parce qu''on ne peut pas lui imputer cette croyance : il peut être distrait, inattentif ou avoir parlé sans réfléchir aux implications ; lui prêter une position non formulée serait injuste","Parce que les implications non exprimées sont automatiquement réfutées par le consensus collectif des savants de l''Islam","Parce que seules les paroles d''Allah et du Prophète ont des implications juridiquement opposables et contraignantes en matière de croyance"]'::jsonb,1,'Si le locuteur ne s''est jamais prononcé sur l''implication de sa parole, on ne peut pas lui imputer cette croyance par défaut, car l''homme est un être qui passe par des états psychologiques variables ; il peut être inattentif, distrait, ou avoir prononcé une parole lors d''un débat sans réfléchir à ses implications. Il serait injuste de lui prêter une croyance ou une position qu''il n''a pas formulée elle-même.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',9,'Approfondissement de la définition du Tawhid Asma’i Wa Siffat','30/07/2025',9) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Que signifie le caractère tawqīfī des Noms d''Allah ?','["Ils peuvent être déduits librement par la raison","Ils sont d''institution divine et limités aux textes révélés","Ils sont choisis selon les usages linguistiques","Ils sont réservés aux invocations longues"]'::jsonb,1,'Les Noms d''Allah sont d''institution divine et il faut se limiter à ce qui est mentionné dans le Coran et la Sunna sans rien ajouter.',1),
   (t,c,'facile','Quel comportement contredit la règle concernant les Noms d''Allah ?','["Ajouter des noms sans preuve révélée","Invoquer Allah par Ses Noms authentiques","Apprendre les Noms rapportés","Reconnaître les Noms établis dans la révélation"]'::jsonb,0,'Il faut se contenter de ce qui est mentionné dans le Coran et la Sunna, sans ajouter ni diminuer.',2),
   (t,c,'facile','Quelle interdiction est mentionnée dans Sourate al-Isrâ’, v. 36 ?','["Délaisser les invocations","Parler sur Allah sans science","Multiplier les invocations","Apprendre les Noms d''Allah"]'::jsonb,1,'Le verset interdit de dire sur Allah ce que l''on ne sait pas, ce qui inclut l''attribution de noms non établis.',3),
   (t,c,'facile','Quel péché est mentionné parmi les plus graves dans Sourate al-Aʿrâf, v. 33 ?','["Parler sur Allah sans science","Oublier certaines invocations","Ignorer les divergences linguistiques","Multiplier les noms composés"]'::jsonb,0,'Parmi les interdictions les plus graves figure le fait de dire sur Allah ce que l''on ignore.',4),
   (t,c,'facile','Quelle parole authentique exprime l''incapacité du serviteur à louer Allah parfaitement ?','["Je connais tous Tes Noms","Je Te loue par ma raison","Je ne peux Te louer comme il se doit","Je T''invoque uniquement par les noms composés"]'::jsonb,2,'Le hadith contient la parole : « Je ne peux Te louer comme il se doit. Tu es tel que Tu T''es loué Toi-même. »',5),
   (t,c,'facile','Laquelle de ces invocations emploie un Nom authentique d''Allah ?','["Yā Cause première !","Yā Créateur des causes !","Yā Samīʿ !","Yā Père généreux !"]'::jsonb,2,'L''invocation « Yā Samīʿ ! » est citée comme exemple d''usage d''un Nom authentique.',6),
   (t,c,'facile','Que ne peut pas faire la raison seule concernant les Noms et Attributs d''Allah ?','["Connaître les Noms d''Allah sans révélation","Comprendre un nom révélé","Reconnaître un texte authentique","Apprendre les invocations rapportées"]'::jsonb,0,'La raison ne peut pas connaître par elle-même les Noms et Attributs d''Allah ; seule la Révélation nous les fait connaître.',7),
   (t,c,'facile','Pourquoi des appellations comme « le père de la générosité » sont-elles rejetées pour Allah ?','["Parce qu''elles sont réservées aux anges","Parce qu''elles limitent les Noms à 99","Parce qu''elles sont des noms composés","Parce qu''elles ne reposent sur aucune preuve révélée"]'::jsonb,3,'Ces exemples montrent qu''il est interdit d''inventer des noms pour Allah sans texte authentique.',8),
   (t,c,'facile','Que signifie aḥṣāhā dans le hadith des 99 Noms d''Allah ?','["Inventer des noms mélioratifs","Cerner, apprendre et maîtriser","Limiter les noms à une seule invocation","Abandonner les noms difficiles"]'::jsonb,1,'Le mot aḥṣāhā est expliqué comme pouvant signifier « cerner », « dénombrer » ou « maîtriser ».',9),
   (t,c,'facile','Quel est le statut de la liste des 99 noms souvent ajoutée après le hadith ?','["Elle fait partie du texte coranique","Elle est authentiquement rapportée par tous les transmetteurs","Elle provient d''une interpolation de certains rapporteurs","Elle limite définitivement tous les Noms d''Allah"]'::jsonb,2,'La liste souvent mentionnée n''est pas authentiquement attribuée au Prophète et résulte d''une interpolation de certains rapporteurs.',10),
   (t,c,'moyenne','Que désigne la profanation des Noms d''Allah mentionnée dans Sourate al-Aʿrâf, v. 180 ?','["Le fait de réserver les invocations à certaines langues","Toute déviation concernant les Noms d''Allah","L''apprentissage incomplet des Noms","Le fait de mémoriser moins de 99 noms"]'::jsonb,1,'Le verset interdit toute déviation dans les Noms d''Allah, que ce soit en les niant, en les falsifiant ou en en inventant.',11),
   (t,c,'moyenne','Que déduit-on de l''invocation : « ou que Tu as gardé auprès de Toi dans la science de l''invisible » ?','["Tous les Noms d''Allah sont connus des hommes","Les Noms d''Allah sont exactement 99","Certains Noms sont gardés dans la science de l''invisible auprès d''Allah","Les Noms d''Allah peuvent être inventés par analogie"]'::jsonb,2,'Cette formulation indique qu''Allah s''est réservé la connaissance de certains Noms dans l''invisible auprès de Lui.',12),
   (t,c,'moyenne','Pourquoi le hadith « Allah a 99 noms » ne limite-t-il pas les Noms d''Allah à ce nombre ?','["Parce qu''il nie l''existence d''autres Noms","Parce qu''il concerne uniquement les invocations nocturnes","Parce qu''il précise seulement un mérite lié à ces noms","Parce qu''il interdit les noms composés"]'::jsonb,2,'Le hadith mentionne un mérite particulier lié à ces noms sans limiter le nombre total des Noms d''Allah.',13),
   (t,c,'moyenne','Que comprend le fait de faire aḥṣā des Noms d''Allah ?','["Les remplacer par des synonymes","Les apprendre, les mémoriser et les comprendre","Limiter leur usage aux savants","Créer de nouveaux noms par raisonnement"]'::jsonb,1,'L''explication de aḥṣāhā inclut le fait de les apprendre par cœur, de les connaître et de les maîtriser.',14),
   (t,c,'moyenne','Pourquoi le Nom al-Jamīl est-il retenu parmi les Noms d''Allah ?','["Parce qu''il est établi dans un hadith authentique","Parce qu''il apparaît dans chaque sourate","Parce qu''il est unanimement déduit par analogie","Parce qu''il est le plus utilisé dans les invocations"]'::jsonb,0,'Le hadith : « Certes, Allah est Magnifique et Il aime la magnificence » établit le Nom al-Jamīl.',15),
   (t,c,'difficile','Que démontre l''expression « Il n''y a aucune divinité digne d''adoration en dehors de Toi » dans les invocations prophétiques ?','["L''exclusivité de l''adoration et de la louange pour Allah","La possibilité d''ajouter des noms par raisonnement","La limitation des Noms d''Allah à certaines invocations","L''abandon des textes au profit de l''opinion"]'::jsonb,0,'Cette formule accompagne l''adoration et la louange exclusive à Allah seul.',16),
   (t,c,'difficile','Pourquoi l''attribution à Allah d''un nom non révélé entre-t-elle dans l''interdiction de parler sans science ?','["Parce qu''aucun nom ne peut être affirmé sans preuve révélée","Parce que tous les noms mélioratifs sont équivalents","Parce que les noms d''Allah sont fondés sur la langue uniquement","Parce que les invocations remplacent les preuves"]'::jsonb,0,'Attribuer à Allah un nom qu''Il ne S''est pas donné relève de la parole sur Allah sans science.',17),
   (t,c,'difficile','Pourquoi les divergences des pieux prédécesseurs concernant les listes des 99 noms sont-elles significatives ?','["Parce qu''elles montrent l''absence d''une transmission prophétique unique et fixe","Parce qu''elles prouvent que chaque liste est obligatoire","Parce qu''elles annulent l''authenticité du hadith","Parce qu''elles limitent les Noms aux noms composés"]'::jsonb,0,'Si une liste prophétique fixe avait été rapportée, elle aurait été transmise de manière précise, continue et identique.',18),
   (t,c,'difficile','Que montre l''exemple où un Nom est remplacé par un autre dans le verset sur la coupe de la main ?','["Tous les Noms d''Allah sont interchangeables","Une erreur de récitation reste sans conséquence","Changer un Nom modifie le sens du jugement","Les Noms liés au pardon conviennent à chaque contexte"]'::jsonb,2,'Le remplacement de ʿAzīz par Ghāfūr modifie le sens du jugement et de la législation.',19),
   (t,c,'difficile','Quelle conséquence pratique découle du fait que les Noms d''Allah ne sont pas limités à un nombre défini ?','["Choisir librement des noms mélioratifs","Éviter toute recherche concernant les Noms","Se limiter à une liste fermée transmise par les narrateurs","Rechercher les Noms authentiques dans le Coran et la Sunna"]'::jsonb,3,'Les Noms d''Allah doivent être tirés du Coran et de la Sunna sans se restreindre à une liste fermée.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',10,'Approfondissement de la définition du Tawhid Asma’i Wa Siffat','03/08/2025',10) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','En combien de grandes catégories les formes d''al-ilḥād dans les Noms d''Allah sont-elles regroupées ?','["Trois","Deux","Cinq","Quatre"]'::jsonb,1,'Les formes d''al-ilḥād dans les Noms d''Allah peuvent être regroupées en deux grandes catégories.',1),
   (t,c,'facile','Que désigne at-tashbīh dans les Noms et Attributs d''Allah ?','["L''invocation d''Allah par Ses plus beaux Noms","L''affirmation des attributs sans leurs effets","L''assimilation des attributs d''Allah à ceux des créatures","Le fait de nier tous les attributs d''action"]'::jsonb,2,'At-tashbīh consiste à attribuer aux Noms et Attributs d''Allah des significations semblables à celles de la création.',2),
   (t,c,'facile','Que désigne at-taʿṭīl ?','["Le négationnisme consistant à nier un Nom ou un attribut d''Allah","Le fait de dériver les noms des idoles à partir des Noms d''Allah","L''affirmation des effets sans les attributs","L''assimilation des créatures au Créateur"]'::jsonb,0,'At-taʿṭīl consiste à nier totalement ou partiellement un Nom d''Allah ou l''attribut qu''il implique.',3),
   (t,c,'facile','Quels éléments sont affirmés dans un Nom transitif d''Allah ?','["Le Nom, sa langue d''origine et son contexte","Le Nom, l''attribut qu''il implique et son effet","Le Nom, son contraire et son équivalent humain","Le Nom, sa récitation et son écriture"]'::jsonb,1,'Un Nom transitif comprend le Nom lui-même, l''attribut qu''il implique et l''effet qui se manifeste dans la création.',4),
   (t,c,'facile','Quel effet doit être affirmé avec le Nom As-Samīʿ ?','["Allah entend toutes les voix, cachées ou manifestes","Allah entend uniquement les invocations nocturnes","Allah entend seulement les croyants","Allah entend uniquement les anges"]'::jsonb,0,'L''effet de l''ouïe est qu''Allah entend toutes les voix et tous les sons, qu''ils soient cachés ou manifestes.',5),
   (t,c,'facile','Quelle était la position des Jahmiyyah concernant les Noms d''Allah ?','["Ils niaient tous les Noms sans exception","Ils affirmaient les attributs sans les noms","Ils reconnaissaient les Noms mais niaient leurs significations réelles","Ils dérivaient les Noms d''Allah pour les donner aux prophètes"]'::jsonb,2,'Les Jahmiyyah reconnaissaient les Noms d''Allah mais prétendaient qu''ils n''avaient aucun sens réel et n''impliquaient aucun attribut.',6),
   (t,c,'facile','Quelle forme d''al-ilḥād consiste à appeler Allah par un nom non révélé ?','["La négation des effets uniquement","L''invention de noms qu''Allah ne S''est pas donnés","L''affirmation des attributs d''action","L''assimilation des croyants aux anges"]'::jsonb,1,'Une des formes d''al-ilḥād est d''appeler Allah par un nom qu''Il ne S''est pas donné Lui-même.',7),
   (t,c,'facile','Pourquoi des noms comme al-ʿUzzā et al-Lāt sont-ils mentionnés parmi les formes d''al-ilḥād ?','["Parce qu''ils désignent des anges rapprochés","Parce qu''ils sont des noms révélés puis abrogés","Parce qu''ils sont dérivés des Noms d''Allah pour nommer des idoles","Parce qu''ils représentent des attributs d''action"]'::jsonb,2,'Les polythéistes dérivaient les noms de leurs idoles à partir des Noms d''Allah, comme al-ʿUzzā dérivé de al-ʿAzīz.',8),
   (t,c,'facile','Quelle règle fondamentale concerne tous les attributs d''Allah ?','["Ils sont tous des qualificatifs de perfection exempts d''imperfection","Ils sont tous des attributs d''action uniquement","Ils ressemblent aux attributs des créatures","Ils sont limités aux invocations prophétiques"]'::jsonb,0,'Tous les attributs d''Allah sont des qualificatifs de perfection, exempts de toute imperfection.',9),
   (t,c,'facile','Lequel de ces ensembles contient uniquement des attributs de perfection ?','["Ignorance, oubli, faiblesse","Vie, science, sagesse","Fatigue, sommeil, pauvreté","Cécité, injustice, incapacité"]'::jsonb,1,'Parmi les attributs de perfection sont cités la vie, la science, l''ouïe, la vue, la miséricorde et la sagesse.',10),
   (t,c,'moyenne','Quelle déviation est réfutée par le verset : « Rien ne Lui est comparable, et Il entend tout et voit tout » ?','["L''assimilation des attributs d''Allah à ceux des créatures","L''affirmation des attributs de perfection","L''invocation par les Noms d''Allah","La reconnaissance des effets des attributs"]'::jsonb,0,'Ce verset réfute l''assimilation et affirme qu''Allah entend et voit sans qu''aucune chose ne Lui soit comparable.',11),
   (t,c,'moyenne','Pourquoi l''appellation « le père » est-elle rejetée pour Allah ?','["Parce qu''elle désigne un attribut d''action","Parce qu''elle n''est pas révélée et qu''Allah ne Se l''est pas attribuée","Parce qu''elle est réservée aux prophètes","Parce qu''elle exprime une qualité de faiblesse humaine seulement"]'::jsonb,1,'Les Noms d''Allah sont d''institution divine et il est interdit de Lui attribuer un nom qu''Il n''a pas mentionné.',12),
   (t,c,'moyenne','Que montre l''invocation : « Je T''implore par tout Nom qui est Tien, par lequel Tu T''es nommé Toi-même » ?','["Les hommes peuvent créer des noms par analogie","Les Noms d''Allah sont connus uniquement par révélation","Chaque peuple possède ses propres Noms divins","Les Noms d''Allah sont limités aux noms composés"]'::jsonb,1,'Cette invocation montre que nous ne connaissons d''Allah que les Noms qu''Il a révélés.',13),
   (t,c,'moyenne','Quelle appellation est invalidée par le verset : « Il n''a pas engendré, ni été Lui-même engendré » ?','["Le Vivant","Le Sage","Le Père","L''Audient"]'::jsonb,2,'Cette appellation est rejetée car Allah dit : « Il n''a pas engendré, ni été Lui-même engendré ».',14),
   (t,c,'moyenne','Pourquoi dériver les noms des idoles à partir des Noms d''Allah constitue-t-il une déviation ?','["Parce que cela attribue aux idoles des noms dérivés des Noms divins","Parce que cela limite les Noms d''Allah à quatre seulement","Parce que cela remplace les attributs d''action","Parce que cela annule les invocations prophétiques"]'::jsonb,0,'Les polythéistes dérivaient les noms de leurs idoles à partir des Noms d''Allah, comme al-Lāt dérivé de al-Ilāh.',15),
   (t,c,'difficile','Pourquoi nier uniquement les effets d''un attribut transitif reste-t-il une forme d''al-ilḥād ?','["Parce qu''il suffit d''affirmer le Nom seul","Parce qu''un Nom transitif implique aussi l''affirmation de son effet","Parce que les effets sont indépendants des attributs","Parce que les attributs transitifs ne concernent pas la création"]'::jsonb,1,'La croyance correcte comporte l''affirmation du Nom, de l''attribut qu''il implique et de son effet dans la création.',16),
   (t,c,'difficile','Pourquoi l''assimilation des attributs d''Allah à ceux des créatures est-elle une déviation grave ?','["Parce qu''elle facilite la compréhension des attributs","Parce qu''elle est une simple erreur linguistique","Parce qu''Allah est sans semblable dans Ses Noms et attributs","Parce qu''elle concerne uniquement les noms des idoles"]'::jsonb,2,'Les textes réfutent totalement cette assimilation et affirment qu''Allah est unique sans semblable.',17),
   (t,c,'difficile','Pourquoi l''exemption d''un défaut peut-elle constituer un éloge pour Allah ?','["Parce qu''elle affirme implicitement la perfection opposée","Parce qu''elle remplace tous les attributs affirmés","Parce qu''elle annule la nécessité des preuves textuelles","Parce qu''elle prouve une ressemblance avec les créatures"]'::jsonb,0,'Cette exemption affirme le contraire du défaut et souligne ainsi les qualités parfaites d''Allah.',18),
   (t,c,'difficile','Pourquoi des termes comme la ruse ou le stratagème ne sont-ils pas attribués à Allah de manière absolue ?','["Parce qu''ils sont toujours des qualificatifs de perfection absolue","Parce qu''ils ne sont parfaits que dans certains contextes précis","Parce qu''ils ne figurent jamais dans les textes","Parce qu''ils désignent uniquement les actes humains"]'::jsonb,1,'Ces qualificatifs sont parfaits dans un contexte de confrontation des agresseurs, mais deviennent des imperfections en dehors de ce cadre.',19),
   (t,c,'difficile','Pourquoi la formule « Allah trahit ceux qui Le trahissent » est-elle rejetée ?','["Parce que la trahison est un qualificatif purement péjoratif","Parce que la trahison est un synonyme de sagesse","Parce que la trahison est un des plus beaux Noms d''Allah","Parce que cette expression est réservée aux créatures seulement"]'::jsonb,0,'La trahison relève uniquement de l''imperfection et ne peut être attribuée à Allah.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',11,'Deuxième et Troisième règles : domaine des attributs et catégories des attributs affirmés et niés',null,11) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Quelle est la définition du Nom d''Allah (al-ism) ?','["Tout qualificatif de grandeur et de magnificence attribué à Allah","Tout mot convenable attribué à Allah lorsqu''il y a un intérêt nécessaire","Tout ce qui a été attribué à Allah avec une formulation de nom, renfermant l''extrême beauté et perfection","Tout attribut tiré exclusivement du Coran, qu''il soit positif ou négatif"]'::jsonb,2,'Le Nom d''Allah est : tout ce qui a été attribué à Allah avec une formulation de nom, renfermant l''extrême beauté et perfection.',1),
   (t,c,'facile','Quelle est la définition de l''Attribut (aṣ-ṣifah) d''Allah ?','["Les qualificatifs de grandeur et de magnificence attribués à Allah","Tout ce qui est attribué à Allah avec une formulation de nom renfermant la perfection","Tout mot non péjoratif attribué à Allah lorsqu''il y a un intérêt nécessaire","Les actes d''Allah dont les paroles sont illimitées"]'::jsonb,0,'Les Attributs sont : les qualificatifs de grandeur et de magnificence attribués à Allah.',2),
   (t,c,'facile','Qu''est-ce que le khabar (l''information) au sens technique des attributs d''Allah ?','["Un attribut d''action tiré uniquement du Coran","Tout mot convenable et non péjoratif qu''il y a un intérêt nécessaire à attribuer à Allah","Un Nom d''Allah renfermant l''extrême beauté et perfection","Un qualificatif de grandeur et de magnificence affirmé dans la Sunna"]'::jsonb,1,'Al-khabar est : tout mot convenable et non péjoratif, qu''il y a un intérêt nécessaire à attribuer à Allah.',3),
   (t,c,'facile','Parmi les trois domaines — noms, attributs, informations (khabar) — lequel est le plus restreint selon la deuxième règle ?','["Le domaine des informations (al-khabar)","Le domaine des attributs","Le domaine des noms","Les trois domaines sont d''égale étendue"]'::jsonb,2,'Le domaine des noms est le plus restreint. Le domaine des attributs est plus vaste que celui des noms. Le domaine de l''information (al-khabar) est encore plus vaste.',4),
   (t,c,'facile','Selon la deuxième règle, dans quel sens va la dérivation entre noms et attributs ?','["On tire des noms à partir des attributs","On tire des attributs à partir des noms","Noms et attributs se tirent l''un de l''autre de manière réciproque","Noms et attributs sont indépendants et ne se déduisent pas l''un de l''autre"]'::jsonb,1,'Des noms on tire des attributs, et non l''inverse. Exemple : d''al-ʿAlīm (Le Savant), on tire l''attribut de la science.',5),
   (t,c,'facile','Parmi les attributs d''action cités comme exemples dans la deuxième règle, lesquels sont mentionnés ?','["La miséricorde, la sagesse, la justice et la puissance","L''arrivée, la venue, la saisie, la prise, le maintien, la brutalité","La vie, la science, la capacité et la volonté","L''installation sur le Trône, la descente et la parole"]'::jsonb,1,'Parmi les exemples d''attributs d''action illimités sont mentionnés : l''arrivée, la venue, la saisie, la prise, le maintien, la brutalité, et d''autres attributs indénombrables.',6),
   (t,c,'facile','Quels sont les attributs affirmés cités comme exemples dans la troisième règle ?','["La mort, le sommeil, l''oubli et la fatigue","L''égal, l''associé et l''intercesseur sans autorisation","La vie, la science, la capacité, l''installation sur le Trône, la descente, le visage, les deux mains","L''arrivée, la venue, la saisie et le maintien"]'::jsonb,2,'Les attributs affirmés comprennent, parmi leurs exemples : la vie, la science, la capacité, l''installation au-dessus du Trône, la descente au ciel mondain, le visage, les deux mains et d''autres.',7),
   (t,c,'facile','Quels sont les attributs niés cités comme exemples dans la troisième règle ?','["La vie, la science, la capacité et la volonté","La mort, le sommeil, l''oubli, l''ignorance, l''incapacité, la fatigue","L''arrivée, la venue, la saisie et la brutalité","L''installation sur le Trône et la descente au ciel mondain"]'::jsonb,1,'Les attributs niés, ceux qu''Allah s''est exempté, sont tous des qualificatifs d''imperfection : la mort, le sommeil, l''oubli, l''ignorance, l''incapacité, la fatigue.',8),
   (t,c,'facile','Quels sont les deux khabar (informations) cités comme exemples légitimes dans les définitions du cours ?','["L''Audient et le Clairvoyant","Celui qui est séparé de Sa création et Celui qui se maintient par Lui-même","Le Premier et le Dernier","Le Vivant et Celui qui subsiste par Lui-même"]'::jsonb,1,'Les exemples de khabar légitimes sont : Celui qui est séparé de Sa création (al-bāʾin min khalqih) et Celui qui se maintient par Lui-même (al-qāʾim bi-nafsih).',9),
   (t,c,'facile','Quelles sont les deux catégories d''attributs niés selon leur mode d''apparition dans les textes, tels que distingués dans la troisième règle ?','["Attributs d''entité et attributs d''action","Attributs textuels et attributs rationnels","Attributs détaillés et attributs généraux","Attributs du Coran et attributs de la Sunna"]'::jsonb,2,'Les attributs niés se divisent en deux formes : les détaillés (comme l''absence de sommeil, de mort, d''ignorance, de fatigue, cités textuellement) et les généraux (comme l''absence d''égal, d''associé, d''intercesseur sans Son autorisation, regroupant plusieurs perfections sous-entendues).',10),
   (t,c,'moyenne','Le verset « Quand bien même tous les arbres de la terre se changeraient en plumes, quand bien même l''océan serait un océan d''encre où conflueraient sept autres océans, les paroles d''Allah ne s''épuiseraient pas » (Luqmān/27) est utilisé dans la deuxième règle pour prouver quoi ?','["Que les Noms d''Allah sont illimités en nombre","Que les attributs d''Allah sont plus nombreux que Ses noms car Ses actes et Ses paroles sont illimités","Que le khabar est le domaine le plus restreint parmi les trois","Que les attributs affirmés sont supérieurs aux attributs niés"]'::jsonb,1,'Ce verset est cité pour prouver que le domaine des attributs est plus vaste que celui des noms, car il y a des attributs en rapport aux actions d''Allah dont Ses paroles sont illimitées. Ses actes étant innombrables, Ses attributs d''action le sont aussi.',11),
   (t,c,'moyenne','Trois justifications obligent à affirmer les attributs d''Allah sans hésitation. La justification rationnelle repose sur trois qualités d''Allah qui rendent toute incertitude impossible. Lesquelles ?','["Allah est le plus Savant, le plus Véridique dans Ses propos, le meilleur Narrateur et le plus Éloquent","Allah est éternel, autosuffisant et sans semblable","Allah est le Créateur, le Seigneur et la seule divinité digne d''adoration","Allah est le Premier, le Dernier, l''Apparent et le Caché"]'::jsonb,0,'La preuve rationnelle repose sur le fait qu''Allah est le plus Savant de Lui-même, le plus Véridique en allocution et le meilleur Narrateur et le plus Éloquent. L''incertitude dans une information ne se produit que lorsqu''elle émane d''une personne potentiellement ignorante, menteuse ou non éloquente — trois défauts impossibles chez Allah.',12),
   (t,c,'moyenne','La troisième règle énonce que lorsqu''Allah nie un attribut de Lui-même, cela ne signifie pas seulement l''absence de cet attribut. Quelle est la règle complète ?','["La négation affirme uniquement que l''attribut nié est impropre à Allah","La négation affirme l''absence de l''attribut et l''affirmation de son contraire parfait","La négation suffit comme éloge car elle montre la pureté d''Allah","La négation doit toujours être accompagnée d''un verset explicite affirmant l''attribut contraire"]'::jsonb,1,'Il est obligatoire d''exempter Allah des qualificatifs d''imperfection tout en affirmant leurs antonymes de la manière la plus parfaite. Car ce qui est voulu lorsqu''Allah nie une chose de Lui-même, c''est de montrer son absence, mais aussi d''affirmer le parfait contraire.',13),
   (t,c,'moyenne','La troisième règle distingue deux catégories d''attributs affirmés selon leur nature. Lesquelles ?','["Attributs coraniques et attributs prophétiques","Attributs apparents et attributs cachés","Attributs d''entité (ṣifāt dhātiyya) et attributs d''action (ṣifāt fiʿliyyah)","Attributs généraux et attributs détaillés"]'::jsonb,2,'Les attributs affirmés se divisent en deux catégories : les attributs d''entité (ṣifāt dhātiyya), comme la Vie et la Science d''Allah, et les attributs d''action (ṣifāt fiʿliyyah), qui se manifestent conformément à Sa Volonté, comme Son installation au-dessus du Trône et Sa descente au dernier tiers de la nuit.',14),
   (t,c,'moyenne','Sous quelles trois formes les attributs niés apparaissent-ils dans le Coran et la Sunna selon la troisième règle ?','["Par des attributs d''entité, des attributs d''action et des informations","Par la négation globale, par des noms exprimant l''exaltation et par des formules d''exaltation comme Subḥān Allāh","Par des versets mecquois, des versets médinois et des hadiths","Par des attributs affirmés, des attributs niés et des informations complémentaires"]'::jsonb,1,'La négation des attributs d''Allah dans le Coran et la Sunna se manifeste sous trois formes : par une négation globale (comme « Rien ne Lui ressemble »), par des Noms qui expriment l''exaltation et la pureté (comme as-Salām, al-Quddūs), et par des formules d''exaltation comme Subḥān Allāh.',15),
   (t,c,'difficile','La deuxième règle précise que l''on décrit Allah par des qualificatifs d''action mais qu''on ne L''en nomme pas. Qu''est-ce que cela implique concrètement pour des qualificatifs comme « l''arrivée » ou « la descente » ?','["On peut dire qu''ils font partie de Ses Noms et les utiliser librement dans l''invocation","On ne décrit pas Allah par ces qualificatifs car ils ne figurent pas dans les textes","On L''en décrit et on L''en informe, mais on ne dit pas parmi Ses Noms : Celui qui arrive, Celui qui descend, Celui qui saisit, et ainsi de suite","On les attribue à Allah uniquement comme khabar et non comme noms ni attributs"]'::jsonb,2,'Nous décrivons Allah par ces qualificatifs comme ils apparaissent dans les textes, néanmoins nous ne Le nommons pas par ces qualificatifs. Nous ne disons pas parmi Ses Noms : Celui qui arrive, celui qui vient, celui qui saisit, celui qui descend. Toutefois, nous L''en informons et Le décrivons par Ses qualificatifs.',16),
   (t,c,'difficile','La troisième règle cite l''exemple : « Le mur n''est pas injuste. » Pourquoi cet exemple démontre-t-il qu''une négation peut ne pas être un éloge ?','["Parce que la négation chez Allah implique toujours une perfection, contrairement aux créatures","Parce que nier l''injustice au mur ne l''éloge pas : le mur ne peut simplement pas commettre d''injustice en raison de son incapacité, ce qui est une imperfection et non une perfection","Parce que le mur est une créature et que les créatures ne peuvent pas être élogées par la négation","Parce que l''injustice est un attribut exclusif aux êtres doués de raison"]'::jsonb,1,'Nier l''injustice au mur n''est pas un éloge, car le mur ne peut pas commettre d''injustice en raison de son incapacité — et il est donc imparfait. La négation peut être due à l''incapacité de l''emplacement, et donc elle n''est pas une perfection. Pour Allah en revanche, la négation implique toujours la perfection de l''attribut contraire.',17),
   (t,c,'difficile','Le verset « Rien, dans les cieux ni sur terre, ne saurait réduire l''autorité d''Allah. Car Il est certes Omniscient, Omnipotent » (Fāṭir/44) est cité pour illustrer quel principe de la troisième règle ?','["Qu''un attribut nié peut contenir plusieurs perfections implicites à la fois","Que la négation globale est supérieure à la négation détaillée","Que les attributs d''action sont plus nombreux que les attributs d''entité","Que les attributs niés ne se trouvent que dans des versets mecquois"]'::jsonb,0,'La négation de l''incapacité d''Allah comprend Sa parfaite science et Sa parfaite capacité — c''est pour cela qu''Il dit ensuite : « Car Il est certes Omniscient, Omnipotent. » Car l''incapacité est due soit à l''ignorance des causes, soit au manque de force. Avec cet exemple, on sait que le qualificatif nié peut comprendre plusieurs perfections.',18),
   (t,c,'difficile','Le verset « Et place ta confiance en Le Vivant qui ne meurt jamais » (al-Furqān/58) est cité dans la troisième règle. Que démontre la négation de la mort dans ce verset ?','["Que la mort est un attribut d''action et non un attribut d''entité","Que la négation de la mort d''Allah comprend Sa parfaite vie","Que la mort est niée uniquement pour les prophètes et non pour les croyants","Que la vie d''Allah est un attribut nié et non un attribut affirmé"]'::jsonb,1,'La négation de la mort d''Allah comprend Sa parfaite vie. Cet exemple illustre le principe que lorsqu''Allah nie un attribut de Lui-même, cela implique l''affirmation du parfait contraire.',19),
   (t,c,'difficile','Rejeter les informations d''Allah sur Ses propres attributs reviendrait logiquement à L''accuser de l''un de trois défauts selon la justification rationnelle de la troisième règle. Lesquels, et pourquoi sont-ils impossibles chez Allah ?','["L''oubli, la négligence ou la faiblesse — impossibles car Allah est le Tout-Puissant et l''Éternel","L''orgueil, la partialité ou l''injustice — impossibles car Allah est le Juste et le Sage","L''ignorance, le mensonge ou le manque d''éloquence — impossibles car Allah est le plus Savant, le plus Véridique et le meilleur Narrateur","La jalousie, la rancœur ou l''erreur — impossibles car Allah est le Parfait et l''Infaillible"]'::jsonb,2,'Rejeter les paroles d''Allah sur Ses attributs reviendrait à L''accuser d''ignorance, de mensonge ou de manque d''éloquence. Or ces trois défauts sont impossibles chez Allah : Il est le plus Savant de Lui-même, le plus Véridique en allocution et le meilleur Narrateur et le plus Éloquent. Il est donc impératif d''accepter Son information telle qu''Il l''informe.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',12,'Quatrième et Cinquième règles : attributs affirmatifs, attributs niés et leurs types',null,12) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Selon la quatrième règle, pourquoi les attributs affirmatifs d''Allah sont-ils bien plus nombreux que les attributs niés dans le Coran et la Sunna ?','["Parce que les attributs niés sont réservés aux situations de polémique uniquement","Parce que l''éloge se fait par l''affirmation des attributs de perfection et non par la simple négation","Parce que les attributs niés ne figurent que dans les sourates mecquoises","Parce que les attributs niés ont été abrogés par les versets affirmatifs"]'::jsonb,1,'Les attributs affirmés sont tous des qualificatifs d''éloge et de perfection. Plus ils sont nombreux et divers, plus la perfection d''Allah est évidente. L''éloge se fait par l''affirmation des attributs de perfection, et non par la simple négation.',1),
   (t,c,'facile','Quelle est la première des trois situations dans lesquelles les attributs niés sont mentionnés selon la quatrième règle ?','["Repousser un manque de perfection sur un point précis","Réfuter les allégations mensongères des polythéistes","Éclaircir la généralité de la perfection d''Allah","Expliquer la différence entre attributs d''entité et attributs d''action"]'::jsonb,2,'La première situation dans laquelle les attributs niés sont mentionnés est l''éclaircissement de la généralité de la perfection d''Allah, comme dans : « Rien ne Lui ressemble » (al-Shūrā/11) et « Nul n''est égal à Lui » (al-Ikhlāṣ/4).',2),
   (t,c,'facile','Quel verset illustre la deuxième situation dans laquelle les attributs niés sont mentionnés — la négation des allégations mensongères ?','["« Rien ne Lui ressemble, et c''est Lui l''Audient, le Voyant » (al-Shūrā/11)","« Ni somnolence ni sommeil ne Le saisissent » (al-Baqara/255)","« Il ne convient nullement au Tout Miséricordieux d''avoir un enfant » (Maryam/92)","« Ce n''est pas par divertissement que Nous avons créé les cieux et la terre » (al-Dukhān/38)"]'::jsonb,2,'La deuxième situation est la négation des allégations des menteurs envers Allah. Le verset illustrant cela est : « Il ne convient nullement au Tout Miséricordieux d''avoir un enfant » (Maryam/92), réfutant ceux qui Lui ont attribué un fils.',3),
   (t,c,'facile','Quel verset illustre la troisième situation dans laquelle les attributs niés sont mentionnés — repousser un manque de perfection sur un point précis ?','["« Nul n''est équivalent à Lui » (al-Ikhlāṣ/4)","« En effet, Nous avons créé les cieux et la terre en six jours, sans éprouver la moindre lassitude » (Qāf/38)","« Il n''a jamais engendré, n''a pas été engendré » (al-Ikhlāṣ/3)","« Et Il n''associe personne à Son commandement » (al-Kahf/26)"]'::jsonb,1,'La troisième situation est de repousser un manque de perfection sur un point précis. L''exemple cité est : « En effet, Nous avons créé les cieux et la terre et ce qui existe entre eux en six jours, sans éprouver la moindre lassitude » (Qāf/38), niant la fatigue et affirmant ainsi la perfection de Sa Force.',4),
   (t,c,'facile','Quelle est la voie des Pieux Prédécesseurs (Salaf aṣ-Ṣāliḥ) dans la description d''Allah, telle qu''établie dans la quatrième règle ?','["Affirmer de façon globale et nier de façon détaillée","Affirmer de façon détaillée et nier de façon globale","Nier uniquement et laisser les affirmations à la discrétion des savants","Affirmer et nier de façon également détaillée"]'::jsonb,1,'La voie de Ahl al-Sunnah wa-l-Jamāʿah est d''affirmer de façon détaillée les attributs d''Allah, et de nier de façon globale ce qu''Il a nié de Lui-même. La preuve en est le verset : « Rien ne Lui ressemble, et c''est Lui l''Audient, le Voyant » (al-Shūrā/11) — négation globale puis affirmation détaillée.',5),
   (t,c,'facile','Quelle est la définition des attributs d''entité (ṣifāt dhātiyya) selon la cinquième règle ?','["Les qualificatifs qui sont en rapport avec la Volonté d''Allah et qu''Il manifeste quand Il le veut","Les qualificatifs qui n''ont pas cessé et ne cessent pas de décrire Allah","Les qualificatifs tirés uniquement du Coran et non de la Sunna","Les qualificatifs affirmatifs opposés aux attributs niés"]'::jsonb,1,'Les attributs d''entité sont les qualificatifs qui n''ont pas cessé et ne cessent pas de décrire Allah, comme la science, la capacité, l''ouïe, la vue, la force, la sagesse, l''élévation et la grandeur.',6),
   (t,c,'facile','Quels attributs informationnels (khabariyya) sont cités parmi les attributs d''entité dans la cinquième règle ?','["L''installation sur le Trône et la descente au ciel mondain","La science, la capacité et la sagesse","Le visage, les deux mains et les deux yeux","La parole, la volonté et l''ouïe"]'::jsonb,2,'Parmi les attributs d''entité, certains sont informationnels (khabariyya) comme le visage, les deux mains et les deux yeux.',7),
   (t,c,'facile','Quelle est la définition des attributs d''action (ṣifāt fiʿliyya) selon la cinquième règle ?','["Les qualificatifs qui n''ont pas cessé et ne cessent pas de décrire Allah","Les qualificatifs niés qu''Allah s''est exempté de Lui-même","Les qualificatifs en rapport avec Sa Volonté : s''Il veut Il agit, s''Il veut Il n''agit pas","Les qualificatifs tirés uniquement de la Sunna et non du Coran"]'::jsonb,2,'Les attributs d''action sont les qualificatifs qui sont en rapport avec Sa Volonté : s''Il veut Il agit et s''Il veut Il n''agit pas, comme l''installation au-dessus du Trône et la descente au ciel de ce bas monde.',8),
   (t,c,'facile','Selon la cinquième règle, quel attribut peut être à la fois d''entité et d''action selon deux considérations différentes ?','["L''installation sur le Trône","La parole d''Allah","La science d''Allah","La descente au dernier tiers de la nuit"]'::jsonb,1,'La parole d''Allah est un qualificatif d''entité par considération de son origine, et un qualificatif d''action par considération du discours, car elle est en rapport avec Sa Volonté : Il parle quand Il le veut, comme Il l''affirme : « Quand Il veut une chose, Son commandement consiste à dire : ''Sois'', et c''est » (Yāsīn/82).',9),
   (t,c,'facile','Quel verset est cité pour montrer que les attributs d''action suivent la Sagesse d''Allah ?','["« Rien ne Lui ressemble, et c''est Lui l''Audient, le Voyant » (al-Shūrā/11)","« Ni somnolence ni sommeil ne Le saisissent » (al-Baqara/255)","« Cependant, vous ne saurez vouloir, à moins qu''Allah veuille. Et Allah est Omniscient et Sage » (al-Insān/30)","« Quand Il veut une chose, Son commandement consiste à dire : ''Sois'', et c''est » (Yāsīn/82)"]'::jsonb,2,'Tous les attributs qui sont en rapport avec Sa Volonté suivent Sa Sagesse, comme le désigne Sa parole : « Cependant, vous ne saurez vouloir, à moins qu''Allah veuille. Et Allah est Omniscient et Sage » (al-Insān/30).',10),
   (t,c,'moyenne','Le verset « Rien ne Lui ressemble, et c''est Lui l''Audient, le Voyant » (al-Shūrā/11) est la preuve centrale de la quatrième règle. Pourquoi réfute-t-il la voie des gens de l''innovation (Ahl al-Bidʿa) ?','["Parce qu''il affirme deux noms d''Allah qui ne figurent pas dans leurs écrits","Parce qu''il montre qu''après la négation globale vient l''affirmation détaillée, prouvant que décrire Allah uniquement par des négations revient à Le décrire comme le néant","Parce qu''il contient une négation détaillée qui invalide leur méthode de généralisation","Parce qu''il est d''une sourate mecquoise que les gens de l''innovation rejettent"]'::jsonb,1,'Les gens de l''innovation pensent que l''éloge d''Allah se fait surtout par la négation. Mais ce verset montre qu''Allah a nié de manière globale, puis affirmé de manière détaillée — « l''Audient, le Voyant » — prouvant que Ses attributs sont des attributs de perfection sans ressemblance avec les créatures. Décrire Allah uniquement par des négations revient à Le décrire comme le néant.',11),
   (t,c,'moyenne','Les versets « Ce n''est pas par divertissement que Nous avons créé les cieux et la terre » (al-Dukhān/38) et « sans éprouver la moindre lassitude » (Qāf/38) illustrent la troisième situation des attributs niés. Quelle double perfection affirment-ils implicitement ?','["La Vie parfaite et la Conservation absolue d''Allah","La Science totale et l''Ouïe parfaite d''Allah","La Puissance infinie et la Sagesse parfaite d''Allah","L''Unicité d''Allah et Son exemption de tout associé"]'::jsonb,2,'Ces versets nient la lassitude et le divertissement pour affirmer le contraire : la Puissance infinie et la Sagesse parfaite d''Allah. La négation de la fatigue affirme la perfection de Sa Force et de Sa Puissance ; la négation du divertissement affirme la perfection de Sa Sagesse dans la création.',12),
   (t,c,'moyenne','Selon la quatrième règle, pourquoi les négations globales dans le Coran sont-elles plus nombreuses que les négations détaillées ?','["Parce que les négations détaillées sont réservées aux hadiths et non au Coran","Parce que la négation globale — comme « nul ne Lui ressemble » — comprend en elle-même la perfection absolue d''Allah dans Son Être, Ses Attributs et Ses Actes, ce qui rend inutile de tout détailler","Parce que les négations détaillées relèvent des attributs d''action et non des attributs d''entité","Parce que les négations détaillées ont été supprimées dans les révélations tardives"]'::jsonb,1,'Les négations globales sont plus nombreuses car elles comprennent la perfection globale d''Allah. Quand Allah dit « Rien ne Lui ressemble » (al-Shūrā/11), cela affirme que toute perfection Lui appartient et qu''Il est unique dans Son Être, Ses Attributs et Ses Actes — un sens tellement global qu''il englobe toutes les négations détaillées.',13),
   (t,c,'moyenne','La cinquième règle précise que tous les attributs d''action suivent la Sagesse d''Allah. Quelle précision est apportée concernant notre connaissance de cette sagesse ?','["Cette sagesse est toujours connue des savants grâce à leur ijtihad","Cette sagesse ne peut jamais être connue des créatures","Cette sagesse peut être connue de nous ou il est plausible que nous ne la percevions pas, mais la certitude demeure qu''Allah ne veut une chose qu''en conformité avec Sa Sagesse","Cette sagesse est connue uniquement des prophètes par révélation"]'::jsonb,2,'La sagesse liée aux attributs d''action peut être connue de nous ou il est plausible que nous ne la percevions pas, mais nous avons la certitude qu''Allah ne veut une chose qu''en conformité avec Sa Sagesse, comme le désigne le verset : « Et Allah est Omniscient et Sage » (al-Insān/30).',14),
   (t,c,'moyenne','La quatrième règle oppose deux façons d''éloger : par affirmation et par négation. Quel exemple concret est cité pour illustrer que la négation seule n''est pas un éloge ?','["Dire à quelqu''un : « tu n''es pas ignorant, tu n''es pas menteur, tu n''es pas faible »","Dire à quelqu''un : « tu n''es pas un éboueur, tu n''es pas un ramasseur de mégots, tu n''es pas un balayeur »","Dire à quelqu''un : « tu n''as pas de défaut, tu n''es pas imparfait »","Dire à quelqu''un : « tu ne ressembles à personne, tu n''as pas d''égal »"]'::jsonb,1,'L''exemple cité est : dire à une personne « Tu n''es pas un éboueur, tu n''es pas un ramasseur de mégots, tu n''es pas un balayeur » ne constitue pas un éloge. Mais dire « Tu es généreux, tu es fort, tu es savant » — là, tu as réellement fait son éloge. L''éloge authentique se fait par l''affirmation et non par la négation.',15),
   (t,c,'difficile','Le verset « Rien ne Lui ressemble, et c''est Lui l''Audient, le Voyant » (al-Shūrā/11) contient à la fois une négation et une affirmation. Quelle règle méthodologique fondamentale de Ahl al-Sunnah cette structure illustre-t-elle, et en quoi s''oppose-t-elle à la voie des gens de l''innovation ?','["Ahl al-Sunnah affirment globalement et nient en détail ; les gens de l''innovation font l''inverse","Ahl al-Sunnah affirment en détail et nient globalement ; les gens de l''innovation ne retiennent que des qualificatifs négatifs, ce qui revient à décrire Allah comme le néant","Ahl al-Sunnah nient tous les attributs par précaution ; les gens de l''innovation les affirment tous","Ahl al-Sunnah et les gens de l''innovation partagent la même méthode mais diffèrent sur les preuves"]'::jsonb,1,'La voie de Ahl al-Sunnah est de détailler dans l''affirmation et de généraliser dans la négation. Ce verset en est la preuve : négation globale (« Rien ne Lui ressemble ») puis affirmation détaillée (« l''Audient, le Voyant »). Les gens de l''innovation décrivent Allah uniquement par des négations, ce qui revient en réalité à Le décrire comme le néant.',16),
   (t,c,'difficile','Selon la cinquième règle, la parole d''Allah est à la fois un attribut d''entité et un attribut d''action. Comment ces deux considérations s''articulent-elles sans contradiction ?','["Elle est d''entité car elle est créée, et d''action car elle est révélée aux prophètes","Elle est d''entité par considération de son origine — Allah a toujours été Celui qui parle — et d''action par considération du discours, car Il parle quand Il le veut, selon Sa Volonté","Elle est d''entité pour les versets mecquois et d''action pour les versets médinois","Elle est d''entité lorsqu''elle est récitée et d''action lorsqu''elle est révélée"]'::jsonb,1,'La parole est un qualificatif d''entité par considération de son origine : Allah est éternellement Celui qui parle. Elle est un qualificatif d''action par considération du discours, car elle est en rapport avec Sa Volonté — Il parle quand Il le veut, comme Il l''affirme : « Quand Il veut une chose, Son commandement consiste à dire : ''Sois'', et c''est » (Yāsīn/82).',17),
   (t,c,'difficile','La quatrième règle énonce trois situations précises dans lesquelles les attributs niés apparaissent. Laquelle parmi les propositions suivantes énumère correctement ces trois situations dans l''ordre ?','["Réfuter les polythéistes ; montrer la perfection globale ; repousser un défaut sur un point précis","Montrer la perfection globale d''Allah ; réfuter les allégations mensongères ; repousser un manque de perfection sur un point précis","Repousser un manque de perfection ; affirmer l''unicité d''Allah ; réfuter les innovations","Affirmer les attributs d''entité ; nier les attributs d''action ; corriger les fausses croyances"]'::jsonb,1,'Les trois situations dans lesquelles les attributs niés sont mentionnés sont : 1) l''éclaircissement de la généralité de la perfection d''Allah (ex. : « Rien ne Lui ressemble ») ; 2) la négation des allégations mensongères (ex. : nier qu''Il ait un enfant) ; 3) repousser un manque de perfection sur un point précis (ex. : nier la lassitude dans la création des cieux et de la terre).',18),
   (t,c,'difficile','Le verset « Ni somnolence ni sommeil ne Le saisissent » (al-Baqara/255) est cité dans la quatrième règle. Quelle double perfection ce verset affirme-t-il implicitement en niant ces deux défauts ?','["La perfection de Sa Puissance et de Sa Sagesse","La perfection de Sa Vie et de Sa Conservation","La perfection de Sa Science et de Son Ouïe","La perfection de Son Unicité et de Son exemption de tout associé"]'::jsonb,1,'Nier la somnolence et le sommeil pour Allah nie le défaut de faiblesse et affirme implicitement la perfection de Sa Vie et de Sa Conservation. Allah qui ne dort jamais est Celui dont la Vie est parfaite et dont la vigilance dans la gestion de l''univers est absolue et sans interruption.',19),
   (t,c,'difficile','La quatrième règle précise que lorsque la négation est exprimée de façon vulgaire et détaillée, elle cesse d''être un éloge. En quoi ce principe distingue-t-il la négation coranique des attributs niés d''une simple énumération de défauts absents ?','["La négation coranique est toujours globale, tandis qu''une liste de défauts absents est toujours détaillée","La négation coranique nie un défaut et affirme implicitement l''attribut de perfection opposé ; une simple liste de défauts absents n''implique aucune perfection et peut même être dévalorisante","La négation coranique s''applique uniquement aux attributs d''entité et non aux attributs d''action","La négation coranique est réservée aux versets révélés en réponse aux polythéistes"]'::jsonb,1,'Lorsque la négation est détaillée de façon vulgaire — comme dire à quelqu''un « tu n''es pas un ramasseur de mégots » — ce n''est pas un éloge. En revanche, la négation coranique nie un défaut précis et affirme implicitement l''attribut de perfection opposé : nier la somnolence affirme Sa Vie parfaite, nier la lassitude affirme Sa Puissance, nier le divertissement affirme Sa Sagesse.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',13,'Sixième règles dans les Attributs','03/08/2025',13) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','En quelles deux catégories se divisent les attributs affirmés d''Allah ?','["Attributs d''entité et attributs d''action","Attributs connus et attributs inconnus","Attributs créés et attributs inventés","Attributs visibles et attributs invisibles"]'::jsonb,0,'Les attributs affirmés d''Allah se divisent en attributs d''entité et attributs d''action.',1),
   (t,c,'facile','Que signifie le fait que les attributs d''entité soient permanents ?','["Ils sont inséparables de l''Essence d''Allah","Ils dépendent du temps et des circonstances","Ils n''existent que dans la création","Ils changent selon les nations"]'::jsonb,0,'Les attributs d''entité sont décrits comme des attributs permanents, inséparables de l''Essence d''Allah.',2),
   (t,c,'facile','À quoi sont liés les attributs d''action ?','["À la Volonté d''Allah","À l''imitation des créatures","À la limitation des textes","À la seule raison humaine"]'::jsonb,0,'Les attributs d''action sont des attributs liés à Sa Volonté.',3),
   (t,c,'facile','Quel Nom renferme à la fois l''attribut de Sagesse et l''attribut de Jugement ?','["Al-Ḥakīm","Al-Jabbār","Al-Qadīm","Al-Wāḥid"]'::jsonb,0,'Parmi Ses Noms figure al-Ḥakīm, qui renferme à la fois l''attribut de Sagesse et l''attribut de Jugement.',4),
   (t,c,'facile','Que faut-il faire avec les attributs d''entité et les attributs d''action ?','["Les accepter et les affirmer tous","N''accepter que les attributs d''entité","N''accepter que les attributs d''action","Les soumettre au raisonnement humain"]'::jsonb,0,'Ces deux catégories d''attributs affirmés doivent être acceptées et affirmées conformément au Coran et à la Sunna.',5),
   (t,c,'facile','Quels sont les deux interdits majeurs dans l''affirmation des attributs ?','["L''assimilation et l''adaptation","La mémorisation et la récitation","La négation et la falsification","La comparaison et l''explication"]'::jsonb,0,'Il est impératif d''abandonner deux interdits majeurs : l''assimilation et l''adaptation.',6),
   (t,c,'facile','Que signifie l''assimilation dans ce contexte ?','["Croire que les qualificatifs d''Allah sont similaires à ceux des êtres","Chercher à connaître la modalité des attributs","Douter des textes révélés","Inventer de nouveaux noms"]'::jsonb,0,'L''assimilation est la croyance que ce qu''on attribue à Allah parmi Ses qualificatifs est similaire aux qualificatifs des êtres.',7),
   (t,c,'facile','Que signifie l''adaptation dans ce contexte ?','["Chercher à connaître le comment des attributs d''Allah","Comparer Allah aux créatures dans tous Ses attributs","Nier les textes sur les attributs","Déduire les noms par la langue seule"]'::jsonb,0,'L''adaptation est la recherche du comment des attributs d''Allah.',8),
   (t,c,'facile','Quel verset est cité pour interdire l''assimilation ?','["Il n''y a rien qui Lui ressemble","Ne poursuis pas ce dont tu n''as aucune connaissance","Il n''a pas engendré, ni été Lui-même engendré","C''est Allah qui possède les noms les plus sublimes"]'::jsonb,0,'Parmi les preuves textuelles contre l''assimilation figure : « Il n''y a rien qui Lui ressemble. »',9),
   (t,c,'facile','Quel verset est cité pour interdire de parler sans science au sujet d''Allah ?','["Et ne poursuis pas ce dont tu n''as aucune connaissance","Rien ne Lui est comparable","Le Tout-Miséricordieux S''est installé au-dessus du Trône","Allah est Magnifique et Il aime la magnificence"]'::jsonb,0,'Parmi les preuves textuelles contre l''adaptation figure : « Et ne poursuis pas ce dont tu n''as aucune connaissance. »',10),
   (t,c,'moyenne','Quel argument montre que la différence entre le Créateur et la créature implique une différence dans les attributs ?','["Le qualificatif de tout décrit est approprié à ce dernier","Le Créateur et la créature ont exactement les mêmes attributs","La différence n''existe que dans les noms","La raison n''a aucune utilité dans ce domaine"]'::jsonb,0,'Le premier argument rationnel dit qu''il est nécessairement connu la différence d''entité et d''essence entre le Créateur et la créature, ce qui implique une différence dans les attributs.',11),
   (t,c,'moyenne','Pourquoi la ressemblance dans l''appellation n''implique-t-elle pas la ressemblance dans la réalité ?','["Parce que des choses peuvent partager un nom tout en différant dans leur réalité et leur manière d''être","Parce qu''un nom n''a jamais de sens réel","Parce que la réalité suit toujours l''appellation","Parce que les attributs sont identiques dans tous les cas"]'::jsonb,0,'Le texte donne l''exemple de mots identiques dans l''appellation mais totalement différents dans la réalité, comme la tête du chameau et la tête de la fourmi.',12),
   (t,c,'moyenne','Pourquoi l''expression « Allah est exempt d''assimilation » est-elle jugée préférable ?','["Parce qu''elle correspond aux termes du Coran","Parce qu''elle permet la comparaison","Parce qu''elle remplace la révélation","Parce qu''elle annule toute distinction"]'::jsonb,0,'Le texte dit que l''expression « Allah est exempt d''assimilation » est la plus correcte, car elle correspond aux termes du Coran.',13),
   (t,c,'moyenne','Quelles sont les trois manières de connaître la modalité d''une chose ?','["La connaissance de son essence, la vision d''un semblable, ou une information véridique","Le simple raisonnement, le hasard, ou l''habitude","La lecture, la parole et l''imagination","La comparaison, la négation et l''adaptation"]'::jsonb,0,'Le texte explique qu''on ne connaît la modalité d''une chose qu''après avoir pris connaissance de son essence, vu son semblable, ou reçu une information véridique.',14),
   (t,c,'moyenne','Que dit l''imām Mālik à propos de l''installation au-dessus du Trône ?','["L''installation est connue, le comment est inconnu, y croire est obligatoire, et poser des questions à ce sujet est une innovation","L''installation est inconnue, mais son comment est obligatoire","Le comment peut être déduit par la raison","Il faut nier l''installation et garder le silence"]'::jsonb,0,'La parole rapportée de l''imām Mālik est : « L''installation est connue, le comment en est inconnu, y croire est obligatoire, et poser des questions à ce sujet est une innovation. »',15),
   (t,c,'difficile','Pourquoi l''adaptation des attributs d''Allah est-elle impossible ?','["Parce que nous ne cernons pas Allah, qu''Il n''a ni semblable ni égal, et qu''aucun texte ne donne la modalité","Parce que les textes donnent toutes les modalités","Parce que la raison peut tout déterminer seule","Parce que l''adaptation est une forme de louange"]'::jsonb,0,'Le texte indique que l''adaptation est impossible car Allah ne peut être cerné, n''a ni égal ni semblable, et aucun texte ne donne la modalité de Ses attributs.',16),
   (t,c,'difficile','Pourquoi la question « Comment est la Main d''Allah ? » est-elle interdite ?','["Parce qu''elle revient à parler sur Allah sans science","Parce qu''elle affirme un texte révélé","Parce qu''elle porte sur un attribut d''entité","Parce qu''elle est permise seulement pour les savants"]'::jsonb,0,'Les questions de type « Comment ? » sont interdites, car elles reviennent à parler sur Allah sans science.',17),
   (t,c,'difficile','Pourquoi le verset de Sourate al-Aʿrāf, v. 33, est-il décisif pour l''interdiction du sans-science ?','["Parce qu''il interdit de dire sur Allah ce que l''on ignore","Parce qu''il ordonne d''ajouter des interprétations","Parce qu''il limite les attributs d''action","Parce qu''il remplace la Sunna"]'::jsonb,0,'Le verset dit explicitement : « … et de dire sur Allah ce que vous ne savez pas. »',18),
   (t,c,'difficile','Pourquoi la comparaison entre la main d''Allah et la main d''une créature est-elle rejetée ?','["Parce que chaque attribut est rattaché à une essence et convient à sa perfection ou à son imperfection","Parce qu''une main n''existe pas dans le langage religieux","Parce que toute main est identique à toute autre main","Parce que l''attribut ne peut jamais être décrit"]'::jsonb,0,'Le texte explique que les attributs ne sont jamais indépendants d''une entité et qu''un attribut ne peut être compris qu''en relation avec l''essence à laquelle il est rattaché.',19),
   (t,c,'difficile','Pourquoi la distinction entre tamthīl et tashābuh est-elle importante ?','["Parce que la ressemblance dans l''appellation n''implique pas une similitude totale dans la réalité","Parce que les deux notions signifient exactement la même chose","Parce qu''elles autorisent l''adaptation","Parce qu''elles annulent la nécessité des preuves"]'::jsonb,0,'Le texte distingue la ressemblance comme une imitation dans la majorité des attributs et l''assimilation comme une imitation totale dans tous les attributs.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',14,'Septième règles','14/05/2026',14) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Comment les attributs d''Allah sont-ils décrits quant à leur source d''affirmation ?','["Ils sont d''institution divine et n''ont pas de place pour la raison","Ils sont déduits uniquement par la spéculation","Ils sont établis par la coutume","Ils sont inventés par comparaison"]'::jsonb,0,'Les attributs d''Allah sont d''institution divine, et la raison n''a pas sa place dans ce domaine.',1),
   (t,c,'facile','Que doit-on faire avec les attributs d''Allah ?','["N''affirmer que ceux qui sont prouvés dans le Coran et la Sunna","N''affirmer que ceux que la raison peut imaginer","N''affirmer que les attributs d''action","N''affirmer que les attributs d''entité"]'::jsonb,0,'Nous n''affirmons à Allah parmi les attributs que ceux qui sont prouvés dans le Coran et la Sunna.',2),
   (t,c,'facile','Quel est le premier moyen d''affirmer un attribut d''Allah ?','["L''énumération explicite de l''attribut","L''invention d''un terme convenable","La comparaison avec les créatures","Le silence total sur le terme"]'::jsonb,0,'La première manière d''affirmation est l''énumération explicite de l''attribut.',3),
   (t,c,'facile','Quel attribut est cité comme exemple d''attribut d''essence ?','["La force","La vengeance","La descente","La venue"]'::jsonb,0,'Le texte cite la force, la fierté et la miséricorde comme attributs d''essence.',4),
   (t,c,'facile','Quel attribut est cité comme exemple d''attribut d''action ?','["La toute-puissance destructrice","La miséricorde","Le visage","Les deux mains"]'::jsonb,0,'Le texte cite la toute-puissance destructrice comme exemple d''attribut d''action.',5),
   (t,c,'facile','Que montre le Nom al-Ghafūr ?','["L''attribut du pardon","L''attribut de la colère","L''attribut de la fatigue","L''attribut de l''oubli"]'::jsonb,0,'Chaque Nom d''Allah implique un attribut de perfection, et al-Ghafūr implique l''attribut du pardon.',6),
   (t,c,'facile','Que montre le Nom as-Samīʿ ?','["L''attribut de l''audition","L''attribut de la faim","L''attribut du sommeil","L''attribut de la création"]'::jsonb,0,'Le texte donne as-Samīʿ comme exemple de Nom qui implique l''attribut de l''audition.',7),
   (t,c,'facile','Quelle action mentionnée établit l''attribut d''istiwaʾ ?','["Le Miséricordieux S''est établi au-dessus du Trône","Et Allah fait ce qu''Il veut","Le Coran est un exposé explicite de toute chose","Ne poursuis pas ce dont tu n''as aucune connaissance"]'::jsonb,0,'L''installation au-dessus du Trône est établie par la parole : « Le Tout Miséricordieux S''est établi au-dessus du Trône. »',8),
   (t,c,'facile','Que montre la parole : « Notre Seigneur descend au ciel de ce bas-monde » ?','["L''attribut de la descente","L''attribut du pardon","L''attribut de la parole","L''attribut de l''amour"]'::jsonb,0,'Le hadith cité établit l''attribut de la descente.',9),
   (t,c,'facile','Que montre la parole : « Ton Seigneur viendra, et les anges, en rangs alignés » ?','["L''attribut de la venue pour juger","L''attribut de la somnolence","L''attribut de l''ignorance","L''attribut du besoin"]'::jsonb,0,'Cette parole établit l''attribut de la venue d''Allah pour juger entre les créatures.',10),
   (t,c,'moyenne','Pourquoi certains savants n''ont-ils pas tranché unanimement sur al-Muntaqim comme Nom d''Allah ?','["Parce que l''attribut de la vengeance est établi, mais l''authenticité du Nom en tant que Nom divin n''est pas unanime","Parce que la vengeance est niée pour Allah","Parce que le verset ne parle que d''action humaine","Parce que le Nom n''apparaît ni dans le Coran ni dans la Sunna"]'::jsonb,0,'Le texte précise que l''attribut de la vengeance est établi pour Allah, mais que tous les savants ne sont pas unanimes sur l''authenticité d''al-Muntaqim comme Nom divin.',11),
   (t,c,'moyenne','Pourquoi la Sunna est-elle nécessaire pour la croyance ?','["Parce qu''elle détaille de nombreuses choses que le Coran mentionne sans les développer","Parce qu''elle remplace le Coran","Parce qu''elle contredit parfois le Coran","Parce qu''elle ne concerne que les actes secondaires"]'::jsonb,0,'Le texte dit que de nombreux détails juridiques et pratiques ne sont expliqués que dans la Sunna, et que leur explication fait partie de l''exposé explicite du Coran.',12),
   (t,c,'moyenne','Que faut-il faire face à un terme comme « corps » lorsqu''il n''apparaît ni dans le Coran ni dans la Sunna ?','["S''abstenir d''utiliser le terme et interroger son sens","L''affirmer automatiquement","Le nier sans examen du sens","Le remplacer par une invention plus claire"]'::jsonb,0,'Le texte dit qu''on s''abstient d''utiliser ces termes et qu''on demande ce que l''interlocuteur veut dire par là.',13),
   (t,c,'moyenne','Quel sens du mot « corps » peut être accepté sans accepter le mot lui-même ?','["Une entité réelle décrite par des Noms et Attributs conformes à Sa Majesté","Un corps humain avec organes et vaisseaux","Une ressemblance totale avec les créatures","Une réalité créée comme les autres êtres"]'::jsonb,0,'Le texte explique que si par « corps » on entend une entité réelle décrite par des Noms et Attributs conformes à Sa Majesté, le sens est correct, mais le mot n''est pas validé.',14),
   (t,c,'moyenne','Que signifie le terme « direction » lorsqu''il est nié pour Allah au sens du bas ?','["Cela contredit l''élévation d''Allah prouvée par le Coran, la Sunna, la raison, la fitra et le consensus","Cela confirme l''élévation d''Allah","Cela ne change rien à la croyance","Cela est obligatoire pour comprendre les attributs"]'::jsonb,0,'Le texte dit que la direction du bas est fausse car elle contredit l''élévation d''Allah prouvée par le Coran, la Sunna, la raison, la fitra et le consensus.',15),
   (t,c,'difficile','Pourquoi la distinction entre le mot et le sens est-elle essentielle face aux termes non mentionnés dans la Révélation ?','["Parce que le mot peut être rejeté tandis que le sens peut être accepté s''il est conforme à la Révélation","Parce que tout mot nouveau est obligatoire","Parce que le sens n''a aucune importance","Parce que le mot doit toujours être accepté"]'::jsonb,0,'Le texte distingue le mot et le sens : on s''abstient du mot, mais si le sens est conforme à la Révélation, il est accepté.',16),
   (t,c,'difficile','Pourquoi la direction du haut sans cerner Allah est-elle la seule situation correcte ?','["Parce qu''Allah est élevé au-dessus de Sa création et rien parmi les créatures ne Le cerne","Parce qu''Allah est contenu par les cieux","Parce qu''une créature peut envelopper Allah","Parce que le terme direction est affirmé textuellement"]'::jsonb,0,'Le texte dit que la direction du haut sans cerner Allah est vraie, car Allah est l''Élevé au-dessus de Sa création et rien parmi les créatures ne Le cerne.',17),
   (t,c,'difficile','Que montre le verset « Et Nous avons fait descendre sur toi le Livre, comme un exposé explicite de toute chose » ?','["Que la Sunna détaille ce que le Coran résume et fait partie de l''exposé explicite","Que la Sunna est inutile","Que seules les règles pratiques sont concernées","Que le Coran suffit sans aucun renvoi"]'::jsonb,0,'Le texte explique que de nombreux détails juridiques et pratiques ne sont expliqués que dans la Sunna, et que leur explication fait partie de l''exposé explicite du Coran.',18),
   (t,c,'difficile','Pourquoi l''exemple de l''âme est-il utilisé pour parler de la modalité des attributs d''Allah ?','["Parce qu''on croit à l''âme sans connaître son comment, tout en voyant ses effets","Parce que l''âme est identique aux attributs divins","Parce qu''elle donne une preuve complète de la modalité","Parce qu''elle permet de cerner Allah"]'::jsonb,0,'Le texte donne l''exemple de l''âme pour montrer qu''on peut croire à une réalité sans connaître son comment, tout en constatant ses effets.',19),
   (t,c,'difficile','Pourquoi faut-il revenir au Coran et à la Sunna pour connaître ce qui est obligatoire, interdit ou permis à propos d''Allah ?','["Parce que cela relève de l''invisible que la raison humaine seule ne peut pas percevoir","Parce que la raison suffit à tout déterminer","Parce que ces questions relèvent uniquement des coutumes","Parce que le sujet concerne seulement les pratiques humaines"]'::jsonb,0,'Le texte dit que les détails concernant ce qui est obligatoire, interdit ou permis relèvent de l''invisible, que la raison humaine seule ne peut pas percevoir.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',15,'Rester fidèle aux termes du Coran : les termes généraux innovés, le sens apparent des textes et la secte des délégants','21/08/2025',15) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Que désigne l''expression al-alfāẓ al-mujmala dans le domaine des Noms et Attributs d''Allah ?','["Les noms d''Allah tirés exclusivement de la Sunna et non du Coran","Les termes à portée générale qui n''apparaissent ni dans le Coran ni dans la Sunna","Les attributs niés mentionnés de manière globale dans le Coran","Les termes techniques utilisés par les pieux prédécesseurs pour décrire Allah"]'::jsonb,1,'Les al-alfāẓ al-mujmala sont les termes à portée générale qui n''apparaissent ni dans le Coran ni dans la Sunna. Ces termes ne doivent pas être utilisés pour établir la croyance concernant les Noms et Attributs d''Allah.',1),
   (t,c,'facile','Quelle est la procédure correcte lorsqu''une personne emploie un terme général innové dans une discussion sur les attributs d''Allah ?','["Rejeter le terme sans demander d''explication","Remplacer le terme par son équivalent coranique le plus proche","Demander la signification exacte voulue : si elle est conforme au Coran et à la Sunna, l''accepter tout en s''abstenant d''utiliser le terme lui-même","Accepter immédiatement le terme s''il semble convenable"]'::jsonb,2,'Lorsque ces expressions sont employées, il convient de demander la signification exacte voulue. Si elle est conforme au Coran et à la Sunna, elle est acceptée, tout en s''abstenant d''utiliser le terme lui-même. En revanche, si la signification est erronée, elle est rejetée.',2),
   (t,c,'facile','Quels sont les deux exemples de termes généraux innovés cités dans le cours ?','["Al-wujūd (l''existence) et al-dhāt (l''essence)","Al-kayf (le comment) et al-tashbīh (la ressemblance)","Al-istiʾthār (la préférence) et al-taʾwīl (l''interprétation)","Al-jism (le corps) et al-jihah (la direction)"]'::jsonb,3,'Parmi les exemples cités figurent le terme al-jism (le corps) et al-jihah (la direction), ainsi que d''autres expressions similaires.',3),
   (t,c,'facile','Parmi les raisons pour lesquelles les termes généraux innovés sont délaissés, laquelle est la première mentionnée ?','["Ils ont été une cause de divergence dans la communauté","Ils peuvent contenir une vérité comme une fausseté, entraînant un mélange entre le vrai et le faux","Ce sont des termes innovés qui n''apparaissent ni dans le Coran ni dans la Sunna","Les pieux prédécesseurs ne les ont pas utilisés"]'::jsonb,2,'La première raison pour laquelle ces termes sont délaissés est qu''ils sont des termes innovés qui n''apparaissent ni dans le Coran ni dans la Sunna.',4),
   (t,c,'facile','Que signifie comprendre les textes selon leur sens apparent (ẓāhir) ?','["Comprendre les textes selon l''interprétation des savants de chaque époque","Comprendre les textes à la lumière de la langue arabe, selon le contexte et la construction linguistique","Comprendre les textes en cherchant leur signification cachée derrière les mots","Comprendre les textes uniquement à travers les explications transmises par les compagnons"]'::jsonb,1,'Le sens apparent des textes est la signification comprise à la lumière de la langue arabe, selon le contexte et la construction linguistique. Le contraire consiste à aborder les textes par la falsification (taḥrīf) ou par des allégations de dissimulation.',5),
   (t,c,'facile','Quel exemple de falsification portant sur les mots eux-mêmes est cité dans le cours ?','["Les polythéistes ayant nié la descente du Coran en langue arabe","Les Juifs ayant transformé le mot hittah (demande de pardon) en hintah (blé) dans le commandement d''Allah","Les chrétiens ayant attribué un fils à Allah","Les Muʿtazilites ayant réinterprété le verset de l''installation sur le Trône"]'::jsonb,1,'Allah ordonna aux enfants d''Israël de dire hittah (demande de pardon). Les Juifs ont détourné le sens et compris hittah comme hintah (blé), transformant ainsi le mot et se moquant du commandement d''Allah — une falsification dans le terme lui-même.',6),
   (t,c,'facile','Selon la troisième règle, qu''est-ce qui est connu et qu''est-ce qui est inconnu dans les textes relatifs aux attributs d''Allah ?','["Le nom est connu, mais l''attribut qu''il implique est inconnu","Les attributs d''entité sont connus, mais les attributs d''action sont inconnus","Le sens apparent est connu, mais la réalité et les modalités des attributs sont inconnues","La modalité est connue, mais le sens apparent reste réservé aux savants"]'::jsonb,2,'Le sens apparent des textes des attributs est connu selon une considération (le sens) et inconnu selon une autre considération (la réalité). Le sens des textes est compris à la lumière de la langue arabe, mais la réalité des Attributs d''Allah et leur ''comment'' (al-kayfiyyah) ne sont pas connus.',7),
   (t,c,'facile','Quelle est la position de la secte des al-Mufawwiḍah sur les attributs d''Allah ?','["Ils prétendent que les attributs ont un sens que seul Allah connaît et que les créatures n''en comprennent absolument rien","Ils affirment que les attributs d''Allah ressemblent aux attributs des créatures en sens mais pas en modalité","Ils nient tous les attributs d''Allah pour éviter l''anthropomorphisme","Ils interprètent les attributs d''Allah selon la philosophie grecque"]'::jsonb,0,'Al-Mufawwiḍah (les délégants) prétendent que les attributs d''Allah ont un sens que seul Allah connaît et que les créatures n''en comprennent rien, comme si les textes étaient composés de mots dont le sens serait totalement inconnu. Cette position est en contradiction avec le Coran, la Sunna et la voie des pieux prédécesseurs.',8),
   (t,c,'facile','Quel exemple l''imam Mālik utilise-t-il pour illustrer la distinction entre sens connu et modalité inconnue dans les attributs d''Allah ?','["La descente au dernier tiers de la nuit : la descente est connue mais sa direction est inconnue","Le nom al-Ḥayy : la vie est connue dans son sens, mais sa modalité chez Allah est inconnue","L''installation (al-istiwaʾ) sur le Trône : l''installation est connue dans son sens, son ''comment'' est inconnu, la foi en cet attribut est obligatoire et chercher son ''comment'' est une innovation","Le verset ''Rien ne Lui ressemble'' : le sens de la ressemblance est connu, mais sa réalité ne l''est pas"]'::jsonb,2,'L''imam Mālik a expliqué l''exemple de l''istiwaʾ : « Le Miséricordieux s''est installé au-dessus du Trône. » L''installation est connue, mais son ''comment'' ou sa manière est inconnue. La foi en cet attribut est obligatoire, et chercher à connaître son ''comment'' est une innovation.',9),
   (t,c,'facile','En combien de grandes catégories les gens se sont-ils divisés dans leur façon d''aborder les textes relatifs aux attributs d''Allah ?','["Deux catégories","Cinq catégories","Quatre catégories","Trois catégories"]'::jsonb,3,'Les gens se sont divisés en trois grandes catégories : les assimilateurs (Ahl al-tashbīh), les négationnistes (Ahl al-taʿṭīl) ou illusionnistes, et les interprétistes ou délégants.',10),
   (t,c,'moyenne','Trois versets sont cités comme preuves textuelles de la deuxième règle sur l''obligation de comprendre le Coran selon son sens apparent. Quel verset est correctement identifié ?','["« Dis : Il est Allah, Unique » (al-Ikhlāṣ/1)","« Rien ne Lui ressemble, et c''est Lui l''Audient, le Voyant » (al-Shūrā/11)","« Nous avons révélé le Livre sous forme d''une récitation en langue arabe, afin que vous puissiez en comprendre la signification » (Yūsuf/2)","« Cependant, vous ne saurez vouloir, à moins qu''Allah veuille » (al-Insān/30)"]'::jsonb,2,'Parmi les preuves textuelles de la deuxième règle figure : « Nous avons révélé le Livre sous forme d''une récitation en langue arabe, afin que vous puissiez en comprendre la signification » (Yūsuf/2). Ce verset montre que le Coran a été révélé pour être compris, ce qui implique que son sens apparent est accessible.',11),
   (t,c,'moyenne','Quel est l''exemple tiré du Paradis utilisé pour illustrer que l''on peut comprendre le sens d''un attribut sans en connaître la réalité exacte ?','["Une grappe de raisin du Paradis qui, si elle tombait sur Terre, suffirait pour nourrir toute l''humanité : on comprend ce qu''est un raisin, mais sa réalité exacte dépasse l''entendement","Une rivière du Paradis dont l''eau est plus blanche que le lait : on comprend ce qu''est une rivière sans en percevoir la réalité","Un palais du Paradis dont les briques sont en or et en argent : on comprend ce qu''est un palais sans en saisir la grandeur réelle","Une lumière du Paradis dont l''éclat surpasse celui du soleil : on comprend ce qu''est la lumière sans en percevoir l''intensité"]'::jsonb,0,'Le Prophète a donné l''exemple d''une grappe de raisin du Paradis qui, si elle tombait sur Terre, suffirait pour nourrir toute l''humanité. La réalité exacte dépasse notre entendement, mais nous comprenons ce qu''est un raisin. De même pour les attributs d''Allah : nous comprenons leur signification, mais leur réalité reste inconnue.',12),
   (t,c,'moyenne','Deux versets sont cités pour montrer la gravité de la falsification des textes par les Juifs, prouvant l''obligation d''accepter le sens apparent. Lesquels ?','["« Il n''a jamais engendré, n''a pas été engendré » (al-Ikhlāṣ/3) et « Rien ne Lui ressemble » (al-Shūrā/11)","« Un groupe d''entre eux, après avoir entendu et compris la parole d''Allah, la falsifièrent sciemment » (al-Baqara/75) et « Il en est parmi les Juifs qui détournent les mots de leur sens » (al-Nisāʾ/46)","« Nous avons révélé le Livre en langue arabe » (Yūsuf/2) et « Le Coran arabe afin que vous raisonniez » (al-Zukhruf/3)","« Ô les croyants ! Ayez toujours foi en Allah » (al-Nisāʾ/136) et « afin qu''ils méditent sur ses versets » (Ṣād/29)"]'::jsonb,1,'Allah dit : « Un groupe d''entre eux, après avoir entendu et compris la parole d''Allah, la falsifièrent sciemment » (al-Baqara/75), et : « Il en est parmi les Juifs qui détournent les mots de leur sens » (al-Nisāʾ/46). Ces versets montrent la gravité de la falsification des textes révélés, que ce soit dans les mots ou dans les sens.',13),
   (t,c,'moyenne','Quel verset est cité comme preuve rationnelle contre la position des délégants qui prétendent que le sens des textes des attributs serait ignoré ?','["« [Voici] un Livre béni que Nous avons fait descendre vers toi, afin qu''ils méditent sur ses versets » (Ṣād/29)","« Alif, Lam, Ra. C''est un Livre dont les versets sont parfaits en style et en sens, émanant d''un Sage, Parfaitement Connaisseur » (Hūd/1)","« Rien ne Lui ressemble » (al-Shūrā/11)","« Et l''Esprit fidèle est descendu avec cela, en une langue arabe très claire » (al-Shuʿarāʾ/193-195)"]'::jsonb,1,'La preuve rationnelle s''appuie sur : « Alif, Lam, Ra. C''est un Livre dont les versets sont parfaits en style et en sens, émanant d''un Sage, Parfaitement Connaisseur » (Hūd/1). Prétendre que le sens de ce Livre serait ignoré serait de la stupidité que rejette la Sagesse d''Allah.',14),
   (t,c,'moyenne','Quel argument constitue la quatrième raison pour laquelle les termes généraux innovés (al-alfāẓ al-mujmala) sont délaissés ?','["Ils conduisent à la ressemblance des attributs d''Allah avec ceux des créatures","Ils ont été une cause de divergence dans la communauté, il est donc préférable de s''en écarter","Ils remplacent les termes coraniques par des termes philosophiques","Ils ont été rejetés par consensus explicite des savants de la première génération"]'::jsonb,1,'La quatrième raison est que ces termes ont été une cause de divergence dans la communauté, il est donc préférable de s''en écarter.',15),
   (t,c,'difficile','Selon Ibn Taymiyya cité dans le cours, qu''implique la position des délégants qui soutiennent que les Prophètes ne connaissaient pas le sens des textes relatifs aux attributs d''Allah ?','["Cela implique que les Prophètes ont transmis le Coran avec fidélité mais sans en comprendre le sens apparent","Cela implique que seuls les savants de la communauté peuvent accéder au vrai sens des attributs dans le Coran","Cela implique que les Prophètes récitaient des paroles sans les comprendre, et ouvre la porte à tout apostat ou innovateur pour imposer sa propre interprétation en prétendant que les textes sont ambigus","Cela implique que la guidée du Coran est réservée à ceux qui maîtrisent parfaitement la langue arabe classique"]'::jsonb,2,'Ibn Taymiyya dit que cela reviendrait à dire que les Prophètes prononçaient des paroles sans les comprendre. De plus, tout apostat ou innovateur pourrait alors dire que la vérité est ce qu''il sait par son opinion et sa raison, sans que les textes puissent le contredire, car ces textes seraient devenus ambigus et inutilisables dans l''argumentation.',16),
   (t,c,'difficile','La doctrine des négationnistes (Ahl al-taʿṭīl) et celle des délégants (al-Mufawwiḍah) partagent une conséquence commune dans leur rapport aux textes. Laquelle ?','["Toutes deux affirment les attributs d''Allah mais divergent uniquement sur leur modalité","Toutes deux s''appuient sur la philosophie grecque pour réinterpréter les attributs d''Allah","Toutes deux acceptent le sens apparent mais rejettent les preuves tirées de la Sunna","Toutes deux écartent le sens apparent des textes, privant ainsi les textes de leur valeur comme guide et argument"]'::jsonb,3,'Les négationnistes prétendent que le sens apparent des textes n''est pas voulu et que les textes n''ont pas de réalité. Les délégants disent que le sens apparent n''est pas voulu et qu''il y a une interprétation que seul Allah connaît. Dans les deux cas, le sens apparent est écarté, ce qui prive les textes de leur valeur comme guide.',17),
   (t,c,'difficile','Prétendre que les sens des attributs d''Allah dans le Coran sont inconnus impliquerait deux atteintes graves selon la troisième règle. Lesquelles ?','["Dénigrer Allah comme s''Il ne savait pas s''exprimer correctement, et dénigrer le Prophète en laissant entendre qu''il n''a pas correctement transmis le Coran ou n''a pas voulu la guidée des gens","Remettre en cause la langue arabe et affirmer que le Coran ne peut être compris sans traduction","Invalider les commentaires des pieux prédécesseurs et rendre le Coran inaccessible aux non-arabophones","Dénigrer les savants de la communauté et remettre en cause l''authenticité de la chaîne de transmission"]'::jsonb,0,'Prétendre que la signification des attributs reste ignorée reviendrait soit à dénigrer Allah comme s''Il ne savait pas s''exprimer correctement, soit à dénigrer le Prophète en laissant entendre qu''il n''a pas correctement transmis le Coran ou qu''il n''a pas voulu la guidée des gens — tout cela en contradiction avec le Coran.',18),
   (t,c,'difficile','La falsification peut porter sur les mots ou sur les sens. Quel exemple de falsification du sens — et non des mots — est cité dans le cours ?','["Transformer le mot hittah en hintah pour signifier blé au lieu de pardon","Réinterpréter « Ni somnolence ni sommeil ne Le saisissent » comme une métaphore de l''attention divine","Interpréter le verset « Et ton Seigneur viendra » comme signifiant « viendra l''ordre de ton Seigneur », alors qu''Allah aurait pu l''exprimer explicitement s''Il l''avait voulu","Réinterpréter « Il s''est installé au-dessus du Trône » comme signifiant « Il a dominé le Trône » par raisonnement philosophique"]'::jsonb,2,'La falsification peut concerner les mots, mais aussi les sens, comme dans l''interprétation du verset « Et ton Seigneur viendra », transformé en : « viendra l''ordre de ton Seigneur ». Or, si Allah avait voulu dire que seul Son ordre vient, Il aurait été capable de l''exprimer explicitement. Lui attribuer un autre sens sans preuve revient à détourner le texte.',19),
   (t,c,'difficile','La troisième règle distingue ce que faisaient réellement les pieux prédécesseurs de ce que prétendent faire les délégants. Quelle est cette différence précise ?','["Les pieux prédécesseurs déléguaient entièrement le sens et la modalité à Allah ; les délégants ne délèguent que la modalité","Les pieux prédécesseurs n''utilisaient que les termes coraniques ; les délégants utilisaient des termes innovés pour expliquer les attributs","Les pieux prédécesseurs affirmaient le sens des textes — tantôt de manière générale, tantôt de manière détaillée — tout en déléguant la connaissance des modalités à Allah ; les délégants prétendent déléguer le sens lui-même, ce qu''ils attribuent faussement aux prédécesseurs","Les pieux prédécesseurs interprétaient les attributs d''action mais pas les attributs d''entité ; les délégants interprétaient les deux catégories"]'::jsonb,2,'Les pieux prédécesseurs se désavouent de la doctrine des délégants. Leurs paroles affirment la sémantique des textes, tantôt de manière générale et d''autres fois de manière détaillée, tout en déléguant la connaissance des modalités à Allah. Les délégants, eux, prétendent déléguer le sens lui-même, ce qu''ils attribuent faussement à la voie des Salafs.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',16,'Le Juste Milieu : Comprendre le Sens Réel des Attributs d''Allah sans Assimilation ni Négation','30/07/2025',16) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Selon la quatrième règle, de quoi dépend le sens apparent d''un texte ?','["Du nombre de fois que le mot est répété dans le Coran","De l''opinion du savant qui interprète le texte","Du contexte et des paroles annexées au mot","De l''époque à laquelle le verset a été révélé"]'::jsonb,2,'Le sens apparent des textes est celui qui vient directement à l''esprit, et il varie en fonction du contexte et des paroles annexées. En effet, le même mot peut avoir un sens dans un contexte et un autre dans un autre contexte.',1),
   (t,c,'facile','Dans le verset de la sourate al-Isrāʾ (v. 58) : « Il n''est point de cité injuste que Nous ne fassions périr », le mot « cité » (qaryah) désigne quoi selon le contexte ?','["Les habitants de la cité","Les habitations et les bâtiments de la cité","Les dirigeants de la cité uniquement","Les ressources et richesses de la cité"]'::jsonb,1,'Dans ce verset, Allah parle de la destruction et de l''anéantissement de ces cités, donc le mot qaryah désigne ici les habitations. C''est le contexte qui nous fait distinguer entre les deux significations possibles du mot.',2),
   (t,c,'facile','Dans le verset de la sourate al-ʿAnkabūt (v. 31) — « Nous allons anéantir les habitants de cette cité » — le mot « cité » (qaryah) désigne quoi ?','["Les habitations et les bâtiments de la cité","Les richesses et ressources de la cité","Les dirigeants et chefs de la cité","Les habitants de la cité"]'::jsonb,3,'Ici, la punition ne concerne pas les habitations du village, mais bien les habitants du village. Ce qui nous fait distinguer entre les deux significations, c''est le contexte.',3),
   (t,c,'facile','Comment l''annexion (iḍāfah) du mot « main » change-t-elle son sens selon le principe exposé dans la quatrième règle ?','["Le mot « main » garde toujours le même sens, quelle que soit son annexion","Annexée à une créature, la main est appropriée à elle ; annexée au Créateur dans le verset « ce que J''ai créé de Mes mains » (Ṣād/75), elle est digne de Lui et conforme à Sa Majesté","Annexée au Créateur, la main désigne un symbole du pouvoir et non un attribut réel","Annexée à une créature, la main est toujours supérieure à celle annexée au Créateur"]'::jsonb,1,'Lorsqu''on dit « J''ai conçu ceci avec mes mains », cette main est annexée à un être créé et appropriée à lui. Mais lorsqu''Allah dit : « ce que J''ai créé de Mes mains » (Ṣād/75), la main est annexée au Créateur et donc digne de Lui, conforme à Sa Majesté. Aucune personne saine d''esprit ne peut croire que la main du Créateur est semblable à la main de la créature.',4),
   (t,c,'facile','Combien de grands groupes se sont formés parmi les gens dans leur approche du sens apparent des textes relatifs aux attributs d''Allah ?','["Deux grands groupes","Quatre grands groupes","Cinq grands groupes","Trois grands groupes"]'::jsonb,3,'Les gens se sont divisés sur le sens apparent des textes et attributs en trois groupes principaux : Ahl at-Tamthīl (les assimilateurs), Ahl as-Sunna (les gens de la Sunna), et Ahl at-Taʿṭīl (les négationnistes).',5),
   (t,c,'facile','Quelle est la position d''Ahl at-Tamthīl (les assimilateurs) face aux textes relatifs aux attributs d''Allah ?','["Ils affirment le sens apparent tout en niant toute modalité","Ils rejettent le sens apparent et le remplacent par une interprétation allégorique","Ils considèrent le sens apparent mais en l''abaissant à une ressemblance avec la création","Ils affirment les attributs sans chercher à comprendre leur sens"]'::jsonb,2,'Ahl at-Tamthīl (les assimilateurs) considèrent le sens apparent, mais en le rabaissant à une ressemblance avec la création. Ils assimilent Allah à Ses créatures, ce qui est une voie égarée contraire au verset : « Rien ne Lui ressemble, et c''est Lui l''Audient, le Clairvoyant » (al-Shūrā/11).',6),
   (t,c,'facile','Quelle est la voie d''Ahl as-Sunna dans la compréhension des attributs d''Allah, telle que résumée par Ibn ʿAbd al-Barr ?','["Affirmer tous les attributs mentionnés dans le Coran et la Sunna, y croire dans leur sens réel et non allégorique, sans définir le comment ni les assimiler à quoi que ce soit","Affirmer uniquement les attributs d''entité et déléguer la connaissance des attributs d''action à Allah","Affirmer les attributs en cherchant leur modalité exacte à travers la raison et la langue arabe","Affirmer les attributs mentionnés dans le Coran uniquement, en excluant ceux de la Sunna"]'::jsonb,0,'Ibn ʿAbd al-Barr a dit : « Les gens de la Sunna sont unanimes pour affirmer tous les attributs mentionnés dans le Coran et la Sunna, d''y croire et de les prendre dans leur sens réel et non allégorique. Toutefois, ils n''en définissent pas le comment (kayf) ni ne les assimilent à quoi que ce soit. »',7),
   (t,c,'facile','En combien de sous-catégories Ahl at-Taʿṭīl (les négationnistes) se divisent-ils ?','["Deux sous-catégories","Quatre sous-catégories","Trois sous-catégories","Cinq sous-catégories"]'::jsonb,2,'Ahl at-Taʿṭīl se divisent en trois sous-catégories : les philosophes (al-Falāsifa), les interprétistes (Ahl at-Taʾwīl), et les délégants (Ahl at-Tafwīḍ).',8),
   (t,c,'facile','Quelle est la position des philosophes (al-Falāsifa) parmi Ahl at-Taʿṭīl sur les attributs d''Allah ?','["Ils affirment le sens apparent mais le remplacent par un sens qu''ils désignent eux-mêmes","Ils disent que le sens apparent n''est pas réel, mais que le Prophète a utilisé des métaphores pour rapprocher les choses à l''esprit des gens","Ils disent que seul Allah connaît le sens véritable et que les créatures ne peuvent rien comprendre","Ils affirment tous les attributs mais nient la possibilité de les comprendre par la langue arabe"]'::jsonb,1,'Les philosophes (al-Falāsifa) disent que le sens apparent n''est pas réel, mais que le Prophète a utilisé des métaphores pour rapprocher les choses à l''esprit des gens.',9),
   (t,c,'facile','Quels sont les trois versets explicitement cités pour réfuter la doctrine des assimilateurs (Ahl at-Tamthīl) ?','["« Nous avons révélé le Livre en langue arabe » (Yūsuf/2), « afin qu''ils méditent » (Ṣād/29), et « le Prophète est plus véridique » (al-Tawba)","« Rien ne Lui ressemble » (al-Shūrā/11), « N''attribuez pas à Allah des égaux » (al-Baqara/22), « N''attribuez pas à Allah des semblables » (al-Naḥl/74)","« Il n''a jamais engendré » (al-Ikhlāṣ/3), « Ni somnolence ni sommeil » (al-Baqara/255), et « Nul n''est égal à Lui » (al-Ikhlāṣ/4)","« Ma miséricorde s''étend à toutes choses » (al-Aʿrāf/156), « La fatigue ne Nous a pas touchés » (Qāf/38), et « Rien ne Lui ressemble » (al-Shūrā/11)"]'::jsonb,1,'Trois versets sont cités pour réfuter les assimilateurs : « Rien ne Lui ressemble, et c''est Lui l''Audient, le Clairvoyant » (al-Shūrā/11), « N''attribuez donc pas à Allah des égaux, alors que vous savez » (al-Baqara/22), et « N''attribuez donc pas à Allah des semblables » (al-Naḥl/74). Ces versets rejettent explicitement qu''on attribue des semblables ou des égaux à Allah.',10),
   (t,c,'moyenne','L''exemple de la construction grammaticale est cité pour illustrer que des mots identiques peuvent changer de sens. Quel exemple précis est donné, et quelle leçon en tire-t-on pour les attributs d''Allah ?','["« Le livre est dans la bibliothèque » vs « dans la bibliothèque est le livre » : l''ordre des mots précise l''insistance, comme pour les attributs où l''ordre change l''affirmation","« Personne auprès de toi sauf Zayd » vs « Zayd n''est qu''auprès de toi » : mêmes mots, construction différente, sens totalement différent — de même, les attributs d''Allah doivent être compris selon la construction, le contexte et l''annexion","« La main de l''homme » vs « la main de l''horloge » : même mot, réalités différentes — de même les attributs d''Allah ne ressemblent pas à ceux des créatures","« La cité fut détruite » vs « les habitants de la cité furent détruits » : un même verset peut viser les bâtiments ou les personnes selon l''annexion"]'::jsonb,1,'L''exemple est : « Personne auprès de toi sauf Zayd » (Zayd est le seul présent) vs « Zayd n''est qu''auprès de toi » (Zayd n''est présent qu''ici). Bien que les mots soient les mêmes, la construction change totalement le sens. De la même manière, il faut comprendre les attributs d''Allah selon le contexte, la construction et l''annexion.',11),
   (t,c,'moyenne','Pourquoi la voie d''Ahl as-Sunna est-elle nécessairement la vérité, selon le raisonnement en deux alternatives présenté dans le cours ?','["Parce qu''elle est la plus facile à comprendre pour les non-arabophones et qu''elle correspond à l''intuition naturelle","Parce que la vérité est soit chez les prédécesseurs (Compagnons, Tābiʿīn, Salaf) soit chez ceux venus après — et prétendre qu''elle est chez les tardifs impliquerait que les Compagnons n''ont jamais exposé la croyance correcte, ce qui est impossible","Parce qu''elle a été adoptée par la majorité des savants de toutes les époques et de tous les pays","Parce qu''elle repose uniquement sur des preuves rationnelles indépendantes des textes révélés"]'::jsonb,1,'Soit la vérité est ce sur quoi étaient les prédécesseurs (Compagnons, Tābiʿīn, Salaf), soit elle est chez ceux qui sont venus après. Mais si on prétend que la vérité est chez les tardifs, cela impliquerait que les Compagnons et les Salaf n''ont jamais exposé la croyance correcte, ce qui est impossible.',12),
   (t,c,'moyenne','Trois erreurs principales sont reprochées à Ahl at-Taʿṭīl (les négationnistes). Laquelle est correctement décrite parmi les propositions suivantes ?','["Ils contredisent la raison saine en affirmant que le Créateur et la créature peuvent partager des attributs identiques","Ils détournent la parole d''Allah de son sens apparent vers un sens contradictoire, ce qui revient à une falsification (taḥrīf) ; ils contredisent la clarté de la langue arabe ; ils parlent d''Allah sans science","Ils nient uniquement les attributs d''action tout en affirmant les attributs d''entité, ce qui est une sélection arbitraire","Ils assimilent Allah au néant en niant tous Ses noms, ce qui est interdit par consensus"]'::jsonb,1,'Les trois erreurs d''Ahl at-Taʿṭīl sont : 1) ils détournent la parole d''Allah de son sens apparent vers un sens contradictoire (falsification/taḥrīf) ; 2) ils contredisent la clarté de la langue arabe en prétendant qu''il y a un sens caché derrière les mots ; 3) ils parlent d''Allah sans science, ce qu''Allah a interdit dans les versets al-Aʿrāf/33 et al-Isrāʾ/36.',13),
   (t,c,'moyenne','Quels sont les deux versets cités pour interdire de parler d''Allah sans science, dans le contexte de la réfutation d''Ahl at-Taʿṭīl ?','["« Mon Seigneur n''a interdit que les turpitudes… et de dire sur Allah ce que vous ne savez pas » (al-Aʿrāf/33) et « Ne poursuis pas ce dont tu n''as aucune connaissance » (al-Isrāʾ/36)","« Rien ne Lui ressemble » (al-Shūrā/11) et « N''attribuez pas à Allah des semblables » (al-Naḥl/74)","« Nous avons révélé le Livre en langue arabe » (Yūsuf/2) et « afin que vous raisonniez » (al-Zukhruf/3)","« Un groupe d''entre eux falsifièrent sciemment la parole d''Allah » (al-Baqara/75) et « Ils détournent les mots de leur sens » (al-Nisāʾ/46)"]'::jsonb,0,'Deux versets interdisent de parler d''Allah sans science : « Mon Seigneur n''a interdit que les turpitudes… et de dire sur Allah ce que vous ne savez pas » (al-Aʿrāf/33), et « Ne poursuis pas ce dont tu n''as aucune connaissance. L''ouïe, la vue et le cœur : sur tout cela, en vérité, on sera interrogé » (al-Isrāʾ/36).',14),
   (t,c,'moyenne','Quelle est la position des interprétistes (Ahl at-Taʾwīl) parmi les négationnistes, et en quoi diffère-t-elle de celle des délégants (Ahl at-Tafwīḍ) ?','["Les interprétistes nient le sens apparent et délèguent à Allah ; les délégants l''acceptent mais y ajoutent une interprétation","Les interprétistes disent que le sens apparent est voulu mais que son vrai sens est autre chose qu''ils désignent eux-mêmes ; les délégants disent que le sens apparent n''est pas voulu et que seul Allah connaît le sens véritable","Les interprétistes acceptent tous les attributs d''action ; les délégants n''acceptent que les attributs d''entité","Les interprétistes sont des philosophes grecs ; les délégants sont des théologiens sunnites égarés"]'::jsonb,1,'Les interprétistes (Ahl at-Taʾwīl) disent que le sens apparent est voulu, mais que son vrai sens est autre chose qu''ils désignent eux-mêmes, en contradiction avec le Coran et la Sunna. Les délégants (Ahl at-Tafwīḍ) disent que le sens apparent n''est pas voulu et que seul Allah connaît le sens véritable, ce qui revient à dire que l''homme lit des versets dont il ne comprend rien.',15),
   (t,c,'difficile','Les négationnistes (Ahl at-Taʿṭīl) partagent en réalité la même origine d''égarement que les assimilateurs (Ahl at-Tamthīl). Quelle est cette origine commune et comment chacun y a-t-il réagi ?','["Les deux groupes s''appuient sur des sources extérieures au Coran ; les assimilateurs sur la Bible, les négationnistes sur la philosophie grecque","Les deux groupes ont commencé par l''assimilation : les assimilateurs l''ont conservée, tandis que les négationnistes l''ont évacuée en niant ce qu''Allah s''est attribué — assimilant ainsi Allah au néant","Les deux groupes rejettent la Sunna : les assimilateurs la remplacent par le Coran seul, les négationnistes la remplacent par la raison pure","Les deux groupes dérivent des sectes de la période médinoise et partagent la même source historique d''égarement"]'::jsonb,1,'Leur origine est la même : tous sont tombés dans l''assimilation. Les anthropomorphistes (Ahl at-Tamthīl) l''ont conservée. Les négationnistes (Ahl at-Taʿṭīl) l''ont évacuée en niant ce qu''Allah s''est attribué. Ainsi, au lieu d''assimiler Allah aux créatures, ils L''ont assimilé au néant.',16),
   (t,c,'difficile','Trois réponses sont données aux assimilateurs qui disent : « Nous ne comprenons de la descente d''Allah et de Sa Main que ce qui ressemble à l''être créé. » Laquelle correspond à la réponse par la raison (ʿaql) ?','["Citer le verset « Rien ne Lui ressemble » (al-Shūrā/11) qui réfute directement l''assimilation","Montrer que dans la création elle-même des choses identiques en nom sont différentes en réalité : la main de l''homme, la main du chat, la main de l''horloge ont le même mot mais des réalités différentes","Demander à l''assimilateur s''il conçoit une entité qui ne ressemble pas aux autres — s''il dit oui, lui rétorquer qu''il doit aussi concevoir des attributs qui ne ressemblent pas aux autres, car la déclaration sur les attributs est comme celle sur l''essence","Rappeler que les Compagnons et les Tābiʿīn n''ont jamais interprété les attributs d''Allah comme ressemblant aux créatures"]'::jsonb,2,'La réponse par la raison est : on demande à l''assimilateur s''il ne conçoit pas une entité qui ne ressemble pas aux autres. S''il dit oui, on lui rétorque de concevoir aussi des attributs qui ne ressemblent pas aux autres. Car la déclaration sur les attributs est comme celle sur l''essence : celui qui distingue entre les deux se contredit.',17),
   (t,c,'difficile','Quelle est la réponse par l''observation (shahid) aux assimilateurs, telle qu''elle est formulée dans le cours ?','["Observer que les Compagnons affirmaient les attributs sans les assimiler, ce qui prouve que l''affirmation sans assimilation est possible","Observer que le Coran lui-même contient des négations de ressemblance, ce qui prouve que l''affirmation et la négation coexistent","Observer que dans la création des choses identiques en nom sont différentes en réalité — la main de l''homme, du chat, de l''horloge — et si on comprend la différence entre des créatures, à plus forte raison doit-on comprendre la différence entre le Créateur et la créature","Observer que les attributs d''action diffèrent des attributs d''entité même chez les créatures, prouvant que la distinction est universelle"]'::jsonb,2,'La réponse par l''observation est : dans la création elle-même, on trouve des choses identiques dans le nom mais différentes dans la réalité — la main de l''homme, la main du chat, la main de l''horloge. Si on comprend la différence entre des créatures, alors à plus forte raison doit-on comprendre la différence entre le Créateur et la créature.',18),
   (t,c,'difficile','Pourquoi la prétention d''Ahl at-Taʿṭīl — selon laquelle il y aurait un sens caché derrière les mots du Coran — constitue-t-elle une atteinte à la Sagesse et à la Parole d''Allah ?','["Parce qu''elle implique que le Coran n''est pas miraculeux, alors qu''Allah a affirmé son inimitabilité","Parce qu''elle implique qu''Allah, qui veut guider les hommes, n''aurait pas été capable d''exprimer clairement ce qu''Il voulait dire — ce qui est une atteinte à Sa Sagesse — alors qu''Il a révélé le Coran en langue arabe claire précisément pour que les gens comprennent","Parce qu''elle implique que la Sunna est supérieure au Coran pour comprendre les attributs divins","Parce qu''elle implique que seuls les savants maîtrisant la philosophie peuvent accéder au sens réel du Coran"]'::jsonb,1,'Allah a révélé le Coran en langue arabe claire (lisān ʿarabī mubīn) afin que les gens comprennent Ses propos. Si tel était le cas qu''un sens caché était voulu, pourquoi Allah — qui veut guider les hommes — n''aurait-Il pas employé directement ces mots ? Leur prétention implique qu''Allah n''aurait pas été capable d''exprimer clairement ce qu''Il voulait, ce qui est une atteinte à Sa Sagesse et à Sa Parole.',19),
   (t,c,'difficile','Al-Qāḍī Abī Yaʿlā dans Ibṭāl at-Taʾwīl formule l''obligation concernant les textes des attributs. Quelle est cette formulation et que condamne-t-elle implicitement ?','["Il oblige à déléguer le sens à Allah et condamne toute tentative d''en comprendre la signification","Il oblige à interpréter chaque attribut par son contraire pour éviter l''assimilation, et condamne l''affirmation littérale","Il n''est pas permis de rejeter ces informations ni de les interpréter ; l''obligation est de les prendre dans leur sens apparent, en affirmant qu''ils sont des attributs d''Allah ne ressemblant pas aux attributs des créatures, et avec la conviction qu''il n''y a aucune assimilation — condamnant ainsi aussi bien la négation que l''interprétation déviante","Il oblige à confirmer uniquement les attributs d''entité et à déléguer les attributs d''action à la sagesse d''Allah, condamnant toute affirmation des attributs d''action"]'::jsonb,2,'Al-Qāḍī Abī Yaʿlā dit : « Il n''est pas permis de rejeter ces informations, ni de s''occuper à les interpréter. L''obligation est de les prendre dans leur sens apparent, en affirmant qu''ils sont des attributs d''Allah, ne ressemblant pas aux attributs des créatures, et ce avec la conviction qu''il n''y a aucune assimilation en cela. » Cela condamne à la fois la négation et l''interprétation déviante.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',17,'Les ambiguïtés des sectes : réponse globale et réfutation particulière des trois hadiths','28/08/2025',17) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Quel est le double objectif des interprétistes lorsqu''ils soulèvent des ambiguïtés auprès d''Ahl as-Sunna ?','["Prouver que le Coran est difficile à comprendre et qu''il nécessite des spécialistes","Faire croire que les gens de la Sunna sont en contradiction dans leur rapport aux textes, puis imposer leur propre point de vue en concluant que les gens de la Sunna n''ont pas le droit de les critiquer","Montrer que la langue arabe ne suffit pas pour comprendre les attributs d''Allah","Pousser Ahl as-Sunna à adopter la méthode philosophique dans l''interprétation des textes"]'::jsonb,1,'Les interprétistes ont deux buts : 1) faire croire que les gens de la Sunna sont en contradiction en disant « vous aussi vous interprétez les textes » ; 2) imposer leur point de vue en concluant « puisque vous interprétez comme nous, vous devez vous taire, à vous vos interprétations et à nous les nôtres ».',1),
   (t,c,'facile','En combien de niveaux se structure la réponse d''Ahl as-Sunna face aux ambiguïtés des interprétistes ?','["Un seul niveau : une réponse globale applicable à tous les textes","Trois niveaux : textuel, rationnel et historique","Deux niveaux : une réponse globale et une réfutation détaillée texte par texte","Quatre niveaux : linguistique, contextuel, historique et rationnel"]'::jsonb,2,'La réponse d''Ahl as-Sunna face aux interprétistes se fait à deux niveaux : une réponse globale concernant tous les textes détournés, puis une réfutation détaillée, texte par texte.',2),
   (t,c,'facile','Quel est le premier point de la réponse globale d''Ahl as-Sunna aux interprétistes ?','["Les gens de la Sunna n''acceptent pas que le commentaire des textes des prédécesseurs soit une déviation du sens apparent, car le sens apparent dépend du contexte, de la construction des mots et des annexions","Les gens de la Sunna acceptent que certains textes sont ambigus et nécessitent une interprétation guidée par la raison","Les gens de la Sunna rejettent tout commentaire des textes et s''en tiennent uniquement à la lettre","Les gens de la Sunna estiment que seuls les Compagnons avaient le droit de commenter les textes"]'::jsonb,0,'Le premier point est que les gens de la Sunnah n''acceptent pas que le commentaire des textes des prédécesseurs dévie du sens apparent. Le sens apparent est celui qui vient immédiatement à l''esprit selon le contexte et la manière dont les mots et les phrases sont construits.',3),
   (t,c,'facile','Quel est le deuxième point de la réponse globale d''Ahl as-Sunna aux interprétistes ?','["Même en admettant une déviation du sens apparent chez les prédécesseurs, les interprétistes doivent fournir une preuve directe ou indirecte du Coran ou de la Sunna — leurs prétendues ambiguïtés ne constituent pas de véritables preuves","Même en admettant une déviation, les gens de la Sunna ont le droit de garder leurs interprétations sans les justifier","Même en admettant une déviation, seule la raison peut trancher entre les interprétations","Même en admettant une déviation, les interprétations des prédécesseurs ont priorité sur celles des tardifs"]'::jsonb,0,'Le deuxième point est que même en admettant une déviation du sens apparent, les interprétistes doivent fournir une preuve directe (dans le texte lui-même) ou indirecte (dans d''autres passages du Coran ou de la Sunna). Leurs prétendues ambiguïtés ne constituent pas de véritables preuves contre ce qu''Allah s''est affirmé à Lui-même.',4),
   (t,c,'facile','Pourquoi est-il indispensable de combiner la réponse globale et la réfutation spécifique selon le cours ?','["Parce que la réfutation spécifique est trop longue et nécessite le cadre de la réponse globale pour être comprise","Parce que la réponse globale pose un cadre solide, mais si l''adversaire insiste sur un texte précis, il pourrait dire que la réponse globale ne concerne pas ce texte particulier","Parce que la réponse globale s''adresse aux savants et la réfutation spécifique s''adresse au grand public","Parce que la réfutation spécifique annule la réponse globale et vice versa"]'::jsonb,1,'L''association des deux est indispensable : la réponse générale pose un cadre solide, mais si l''adversaire insiste sur un texte précis, il pourrait dire : « ta réponse globale ne concerne pas mon texte particulier ». C''est pourquoi il faut combiner les deux.',5),
   (t,c,'facile','Combien de hadiths les interprétistes attribuent-ils à l''Imam Ahmad comme preuve qu''il aurait lui-même interprété les textes ?','["Deux hadiths","Cinq hadiths","Quatre hadiths","Trois hadiths"]'::jsonb,3,'L''auteur rappelle qu''Abū Ḥāmid al-Rāzalī mentionne que certains Hanbalites ont dit qu''Ahmad n''a interprété que trois hadiths : « la pierre noire est la droite d''Allah » ; « les cœurs des serviteurs sont entre les deux doigts du Miséricordieux » ; « certes je trouve la délivrance du Miséricordieux du côté du Yémen ».',6),
   (t,c,'facile','Quelle est l''authenticité du hadith « la pierre noire est la droite d''Allah » selon les savants cités dans le cours ?','["Hadith authentique rapporté dans les deux recueils (Bukhārī et Muslim)","Hadith faible non attribué au Prophète, jugé non authentique par Ibn al-Jawzī, Ibn al-ʿArabī et Ibn Taymiyya","Hadith hasan (bon) rapporté par l''Imam Ahmad avec une chaîne complète","Hadith dont l''authenticité est contestée uniquement par les Muʿtazilites"]'::jsonb,1,'Ce hadith est erroné et non attribué au Prophète. Ibn al-Jawzī mentionne qu''il n''est pas authentique, Ibn al-ʿArabī dit qu''il est inexact, et Ibn Taymiyya précise qu''il a été rapporté avec une chaîne de transmission non prouvée.',7),
   (t,c,'facile','Le hadith « les cœurs des serviteurs sont entre les deux doigts du Miséricordieux » est-il authentique, et où a-t-il été rapporté ?','["Hadith faible rapporté uniquement par l''Imam Ahmad","Hadith authentique rapporté par l''Imam Muslim dans le livre du Destin, selon ʿAbd Allah ibn ʿAmr ibn al-ʿĀṣ","Hadith dont l''authenticité est disputée entre al-Bukhārī et Muslim","Hadith hasan rapporté par al-Tirmidhī uniquement"]'::jsonb,1,'Ce hadith est authentique, rapporté par l''Imam Muslim dans le deuxième chapitre du livre du Destin, selon ʿAbd Allah ibn ʿAmr ibn al-ʿĀṣ qui a entendu le Prophète s''exclamer : « les cœurs des hommes, tous sont entre les deux doigts du Miséricordieux semblable à un seul cœur, les orientant comme Il le veut ».',8),
   (t,c,'facile','Quelle est la signification correcte du mot « Nafas » dans le hadith « je trouve la délivrance du Miséricordieux du côté du Yémen » ?','["La respiration d''Allah","La direction géographique du Yémen","Le soulagement d''Allah pour les croyants, comme les linguistes le mentionnent : « toute chose qui soulage de la détresse »","L''armée d''Allah envoyée depuis le Yémen"]'::jsonb,2,'Le Nafas dans ce hadith est un nom d''action du verbe soulager. Les linguistes, notamment dans « Les normes linguistiques », déclarent : « al-Nafas est toute chose qui soulage de la détresse. » Le sens du hadith est donc que le soulagement d''Allah pour les croyants viendra des Yéménites.',9),
   (t,c,'facile','Combien de situations sont citées pour expliquer en quoi Allah a soulagé les croyants grâce aux Yéménites, dans la réfutation du troisième hadith ?','["Deux situations","Cinq situations","Trois situations (la foi est yéménite, les guerres d''apostasie, la sagesse vient du Yémen)","Une seule situation : la conquête de Constantinople"]'::jsonb,2,'Trois situations sont citées : 1) la foi est yéménite car les habitants de Médine (Aws et Khazraj) sont d''origine yéménite et ont accueilli le Prophète ; 2) les guerres d''apostasie et contre les hérétiques où les combattants yéménites ont joué un rôle central ; 3) la sagesse vient du Yémen car les Yéménites sont connus pour leur sagesse et prudence.',10),
   (t,c,'moyenne','Dans l''explication du verset de la sourate al-Qamar (v. 14) sur l''arche de Noé — « Qui voguait sous Nos yeux » — quelle erreur d''interprétation les interprétistes ont-ils commise, et quelle est la lecture correcte selon Ahl as-Sunna ?','["Les interprétistes ont traduit bi-aʿyuninā par « dans Nos yeux » comme lieu physique ; la lecture correcte est que la particule bi- indique l''accompagnement, donc « sous Nos yeux » — c''est-à-dire sous la protection et la surveillance d''Allah, tout en affirmant l''attribut réel des yeux","Les interprétistes ont nié que ce verset contienne un attribut d''Allah ; la lecture correcte est que le verset parle uniquement de la protection divine sans attribut","Les interprétistes ont traduit ce verset comme une métaphore de l''omniscience ; la lecture correcte est d''affirmer que les yeux d''Allah ressemblent aux yeux des créatures","Les interprétistes ont affirmé l''attribut des yeux ; la lecture correcte est de nier cet attribut pour éviter l''anthropomorphisme"]'::jsonb,0,'Le terme bi- ici indique l''accompagnement et non le lieu. Allah a affirmé pour Lui-même l''attribut des yeux. Cela ne signifie pas que le navire vogue « dans » Ses yeux, mais « sous Ses yeux », c''est-à-dire sous Sa protection et Sa surveillance. Les interprétistes, en refusant cela, ont falsifié le sens du verset et renié l''attribut d''Allah.',11),
   (t,c,'moyenne','Selon Ibn Taymiyya, pourquoi la restriction « sur terre » dans la parole d''Ibn ʿAbbās — « la pierre noire est la main droite d''Allah sur terre » — est-elle déterminante pour comprendre que la pierre noire n''est pas un attribut d''Allah ?','["Parce que la restriction géographique montre que l''attribut est limité au bas monde et n''existe pas dans l''au-delà","Parce que dire « la main droite d''Allah sur terre » avec restriction est différent de dire « la main droite d''Allah » sans restriction, et comme Allah est au-delà de Sa création, cela montre qu''il ne s''agit pas d''un attribut d''Allah","Parce que la restriction « sur terre » remplace le mot « main » par le mot « symbole »","Parce que Ibn ʿAbbās a précisé que seules les pierres terrestres peuvent représenter Allah"]'::jsonb,1,'Ibn Taymiyya précise : Ibn ʿAbbās n''a jamais dit « la main droite d''Allah » sans restriction. La restriction « sur terre » est très importante : elle montre qu''il ne s''agit pas d''un attribut d''Allah, car Allah est au-delà de Sa création. Le statut d''un mot rattaché est différent de celui qui est inconditionnel.',12),
   (t,c,'moyenne','Comment Ahl as-Sunna comprennent-ils le hadith authentique « les cœurs des serviteurs sont entre les deux doigts du Miséricordieux », et quel exemple est cité pour montrer qu''être « entre » deux choses n''implique pas le contact ?','["Ils le comprennent comme une métaphore de la puissance divine ; l''exemple cité est l''eau entre deux rives","Ils affirment qu''Allah a des doigts réels dignes de Sa magnificence, sans assimilation ; les cœurs sont entre Ses deux doigts sans que cela implique le contact — comme un nuage entre le ciel et la terre ne touche ni l''un ni l''autre, ou comme Badr est entre La Mecque et Médine sans contact","Ils interprètent « doigts » comme une métaphore du pouvoir et de la volonté divine ; l''exemple cité est la ville entre deux montagnes","Ils affirment que les doigts d''Allah touchent réellement les cœurs pour les orienter ; l''exemple est celui de la main qui tient une boussole"]'::jsonb,1,'Les gens de la Sunnah affirment qu''Allah a des doigts réels. Le fait que les cœurs soient entre Ses deux doigts n''implique pas le contact ni l''immanence. Exemples cités : un nuage entre le ciel et la terre ne touche ni l''un ni l''autre ; la ville de Badr est entre La Mecque et Médine sans y être en contact.',13),
   (t,c,'moyenne','Quelle source est citée pour vérifier l''authenticité des hadiths rapportés par l''Imam Ahmad, et qu''est-ce qu''elle détaille ?','["Le livre Ibṭāl al-Taʾwīl d''al-Qāḍī Abī Yaʿlā, qui recense les hadiths rejetés par l''Imam Ahmad","Le Majmaʿ al-Zawāʾid de l''Imam al-Haythamī, qui détaille la chaîne de transmission depuis l''élève qui rapporte de son maître jusqu''au Prophète","La Compilation de Fatwa d''Ibn Taymiyya, qui liste les hadiths authentiques sur les attributs","Le Ṣaḥīḥ d''al-Bukhārī, qui authentifie tous les hadiths d''Ahmad en les recoupant"]'::jsonb,1,'Pour vérifier l''authenticité des hadiths rapportés par l''Imam Ahmad, le Majmaʿ al-Zawāʾid de l''Imam al-Haythamī est une référence. Il détaille la chaîne de transmission depuis l''élève qui rapporte de son maître jusqu''au Prophète.',14),
   (t,c,'moyenne','Quel jugement Ibn Taymiyya porte-t-il sur l''affirmation selon laquelle l''Imam Ahmad aurait interprété trois hadiths ?','["Il confirme qu''Ahmad a bien interprété ces trois hadiths et valide cette méthode pour les cas ambigus","Il dit que cette affirmation est un mensonge à l''encontre de l''Imam Ahmad","Il dit qu''Ahmad a interprété ces hadiths uniquement par nécessité pédagogique et non par conviction","Il estime qu''Ahmad a bien interprété le premier hadith mais pas les deux autres"]'::jsonb,1,'Ibn Taymiyya déclare dans sa compilation de Fatwa (V5/p397) : « cette allégation est un mensonge à l''encontre de l''Imam Ahmad. »',15),
   (t,c,'difficile','La réponse particulière montre que les pieux prédécesseurs n''ont jamais fait d''interprétation arbitraire. Quels critères respectaient-ils toujours selon le cours, et en quoi cela les distingue-t-il fondamentalement des interprétistes ?','["Ils respectaient uniquement les preuves textuelles et excluaient tout raisonnement linguistique, contrairement aux interprétistes qui s''appuient sur la grammaire","Ils respectaient la langue arabe, le contexte et les annexions des phrases, extrayant le sens apparent sans le déformer — contrairement aux interprétistes qui dévient le sens apparent vers un sens qu''ils désignent eux-mêmes en contradiction avec le Coran et la Sunna","Ils respectaient uniquement la Sunna pour interpréter le Coran et le Coran pour interpréter la Sunna, contrairement aux interprétistes qui utilisent la philosophie","Ils respectaient les positions des Compagnons sans jamais proposer d''explication supplémentaire, contrairement aux interprétistes qui ajoutent leurs propres réflexions"]'::jsonb,1,'Les pieux prédécesseurs n''ont pas fait d''interprétation arbitraire. Ils ont toujours respecté la langue arabe, le contexte et les annexions des phrases et des propos, et ont extrait le sens apparent sans le déformer. C''est ce qui les distingue fondamentalement des interprétistes qui dévient le sens apparent vers un sens contradictoire avec le Coran et la Sunna.',16),
   (t,c,'difficile','La fin du hadith sur la pierre noire — « celui qui l''embrasse ou la serre, c''est comme s''il touche Allah » — contient le mot « comme si » (kāʾanna). Pourquoi ce détail suffit-il à prouver que la pierre noire n''est pas un attribut d''Allah ?','["Parce que « comme si » est une formule poétique qui invalide tout le hadith","Parce que « comme si » indique une assimilation de la chose à l''objet embrassé, montrant que celui qui serre la pierre ne serre pas Allah directement mais y est seulement assimilé — ce qui prouve que la pierre est distincte d''Allah","Parce que « comme si » remplace « en réalité » et confirme que la pierre est identique à la main d''Allah","Parce que « comme si » est une indication que le hadith est une métaphore ne devant pas être prise au sens littéral"]'::jsonb,1,'Ibn Taymiyya explique que le hadith ne dit pas qu''il embrassait la main d''Allah directement, mais « comme si » — montrant la différence. Ainsi, le début (« sur terre ») et la fin (« comme si ») du hadith indiquent clairement qu''il ne s''agit pas d''un attribut d''Allah comme il est connu chez toute personne sensée.',17),
   (t,c,'difficile','La parole d''Ibn ʿAbbās sur la pierre noire a une chaîne de transmission comportant un narrateur nommé Ibrāhīm al-Khūzī. Quel statut lui est accordé et quelle conséquence en découle sur la valeur de cette parole ?','["Ibrāhīm al-Khūzī est fiable et authentifié par al-Bukhārī, ce qui rend la parole d''Ibn ʿAbbās authentique","Ibrāhīm al-Khūzī est délaissé, la chaîne est donc faible ; et même si la parole était authentique, c''est une parole d''Ibn ʿAbbās et non du Prophète, et tout ijtihād d''un Compagnon n''est pas considéré comme un hadith authentique","Ibrāhīm al-Khūzī est inconnu, ce qui rend la chaîne interrompue et le hadith rejeté par consensus","Ibrāhīm al-Khūzī est fiable mais la chaîne est interrompue avant lui, ce qui affaiblit le hadith"]'::jsonb,1,'La chaîne comporte Ibrāhīm al-Khūzī qui est délaissé, donc la chaîne est faible. Et même si cette parole était authentique, ce n''est pas une parole du Prophète. Ibn ʿAbbās a parfois pris des informations auprès des gens du Livre, et tout ijtihād des compagnons n''est pas considéré comme un hadith authentique.',18),
   (t,c,'difficile','Les interprétistes ont tiré une fausse conclusion du hadith « les cœurs des serviteurs sont entre les deux doigts du Miséricordieux » en pensant qu''Allah touche les cœurs directement. Selon Ahl as-Sunna, quel raisonnement par analogie réfute cette lecture ?','["La réfutation repose sur le fait que les doigts d''Allah sont des attributs niés dans le Coran, donc le hadith est nécessairement métaphorique","La réfutation repose sur le fait que les doigts d''Allah sont identiques à ceux des créatures et ne peuvent donc pas toucher les cœurs immatériels","La réfutation repose sur le fait que même chez les créatures, être « entre » deux éléments n''implique pas le contact — comme un nuage entre le ciel et la terre ou Badr entre La Mecque et Médine — donc à plus forte raison les cœurs peuvent être entre les doigts d''Allah sans contact ni immanence","La réfutation repose sur le fait que le Jour du Jugement, les doigts d''Allah portent les cieux, donc ils ne peuvent simultanément toucher les cœurs"]'::jsonb,2,'Ce nuage assujetti entre le ciel et la terre ne touche ni l''un ni l''autre. Pareillement, on dit que la ville de Badr est entre La Mecque et Médine bien qu''il y ait une distance entre elles. En somme, les cœurs des hommes sont tous réellement entre les deux doigts du Miséricordieux sans que cela implique le contact et l''immanence.',19),
   (t,c,'difficile','Ibn Taymiyya affirme que l''allégation selon laquelle l''Imam Ahmad aurait interprété trois hadiths est un mensonge. Qu''est-ce que cela révèle sur la stratégie des interprétistes dans leur usage des exemples historiques ?','["Cela révèle que les interprétistes ignorent sincèrement les positions réelles de l''Imam Ahmad et se trompent de bonne foi","Cela révèle que les interprétistes fabriquent des précédents historiques fictifs pour contraindre Ahl as-Sunna à valider leur méthode d''interprétation arbitraire, en leur attribuant faussement des exemples de déviation du sens apparent","Cela révèle que l''Imam Ahmad avait effectivement deux positions différentes et que les interprétistes ont simplement choisi la moins connue","Cela révèle que les interprétistes citent correctement Ahmad mais l''appliquent à de mauvais textes"]'::jsonb,1,'Le Cheikh montre que les interprétistes cherchent à créer des ambiguïtés en forçant Ahl as-Sunna à choisir entre : « vous falsifiez tous les textes » ou « vous êtes en contradiction ». Attribuer faussement à l''Imam Ahmad une interprétation arbitraire est une stratégie pour légitimer leur propre méthode. Ibn Taymiyya qualifie cela de mensonge à l''encontre de l''Imam Ahmad.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',18,'Explications concernant l''attribut de l''élévation d’Allah','08/09/2025',18) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Que signifie ici istiwā’ dans le premier avis sur Sourate al-Baqarah, v. 29 ?','["L''élévation au-dessus du ciel","Le sommeil","La création du néant","La négation de l''attribut"]'::jsonb,0,'Le premier avis retient que istiwā’ signifie l’élévation au-dessus du ciel.',1),
   (t,c,'facile','Que signifie istiwā’ dans le second avis sur Sourate al-Baqarah, v. 29 ?','["La détermination complète et le dessein achevé","La descente physique","L''égalité entre Allah et la création","La négation du ciel"]'::jsonb,0,'Le second avis interprète istiwā’ comme la détermination complète et le dessein achevé.',2),
   (t,c,'facile','Quelle particule change le sens dans le verset de la création des cieux ?','["Ilā","ʿAlā","Min","Fī"]'::jsonb,0,'Le texte explique que istawā ilā n''a pas le même sens que istawā ʿalā.',3),
   (t,c,'facile','Que montre la particule ʿalā avec istawā ?','["L''élévation au-dessus et l''établissement","L''orientation vers un objectif","La descente","La disparition"]'::jsonb,0,'Le texte dit que istawā ʿalā implique l’élévation au-dessus et l’établissement.',4),
   (t,c,'facile','Que montre la particule ilā avec istawā ?','["L''orientation vers","La négation d''une direction","La création simultanée","L''égalité avec le ciel"]'::jsonb,0,'Le texte dit que istawā ilā indique une orientation vers.',5),
   (t,c,'facile','Quel exemple de verbe avec particule est donné pour illustrer le changement de sens ?','["Boire avec bi qui devient s''abreuver","Marcher avec min qui devient dormir","Parler avec ʿalā qui devient manger","Créer avec fī qui devient nier"]'::jsonb,0,'Le texte prend l''exemple du verbe boire associé à la particule bi, qui prend le sens de s’abreuver.',6),
   (t,c,'facile','Que montre le verset « Il est avec vous où que vous soyez » ?','["La compagnie d''Allah avec Sa création","L''absence de toute science","La négation de l''élévation","L''impossibilité de toute proximité spirituelle"]'::jsonb,0,'Le texte l''utilise comme preuve de la compagnie d''Allah avec Sa création.',7),
   (t,c,'facile','Que rejettent les gens de la Sunna face à ces versets ?','["L''idée de mélange ou d''immanence","L''ensemble du Coran","La Sunna authentique","L''élévation d''Allah"]'::jsonb,0,'Le texte explique qu''ils rejettent l''interprétation qui fait de la compagnie un mélange ou une immanence.',8),
   (t,c,'facile','Que signifie ici la compagnie d''Allah dans le sens correct ?','["Qu''Il les cerne par Sa science, Sa puissance, Son audition, Sa vision et Sa gérance","Qu''Il habite en eux","Qu''Il est mélangé à eux","Qu''Il cesse d''être élevé"]'::jsonb,0,'Le texte précise que la compagnie signifie Son encadrement par Sa science, Sa capacité, Son audition, Sa vision et Sa gérance.',9),
   (t,c,'facile','Quel est le premier groupe mentionné sur la compagnie d''Allah ?','["Les prédécesseurs","Les panthéistes","Les négateurs de la Sunna","Les coranistes"]'::jsonb,0,'Le premier groupe est celui des prédécesseurs, dont la doctrine est présentée comme correcte.',10),
   (t,c,'moyenne','Pourquoi le verset « Ne méditent-ils donc pas sur le Coran ? » est-il invoqué ici ?','["Pour montrer que le Coran ne se contredit pas","Pour affirmer que la compagnie est impossible","Pour nier l''explication des savants","Pour limiter le sens des attributs"]'::jsonb,0,'Le texte l''utilise pour dire que ce qu''Allah a réuni dans Son Livre ne peut pas être contradictoire.',11),
   (t,c,'moyenne','Pourquoi ne faut-il pas opposer le verset de la compagnie et celui de l''élévation ?','["Parce que les deux sont vrais et se comprennent ensemble","Parce que l''un est abrogé","Parce que l''un est faux","Parce que le Coran contient des erreurs"]'::jsonb,0,'Le texte explique que l''élévation d''Allah et Sa compagnie ne sont pas contradictoires.',12),
   (t,c,'moyenne','Que signifie le terme compagnie générale ?','["Allah est avec toutes Ses créatures par Sa science, Sa puissance, Sa vision et Sa souveraineté","Allah est physiquement partout","Allah est seulement avec les prophètes","Allah n''est pas au-dessus du Trône"]'::jsonb,0,'La compagnie générale est décrite comme l''encadrement de toutes les créatures par la science, la puissance, la vision et la souveraineté d''Allah.',13),
   (t,c,'moyenne','Que signifie la compagnie particulière ?','["Un soutien et une aide particuliers accordés à certains serviteurs","Une fusion avec les créatures","Une présence dans les lieux","Une disparition de l''élévation"]'::jsonb,0,'Le texte distingue une compagnie particulière qui implique une aide et un soutien directs.',14),
   (t,c,'moyenne','Quel est le troisième groupe cité à propos de la compagnie d''Allah ?','["Ceux qui croient à une immanence tout en affirmant l''élévation","Les prédécesseurs","Les exégètes unanimement corrects","Les compagnons du Prophète"]'::jsonb,0,'Le texte mentionne un troisième groupe qui pense qu''Allah est avec Sa création sur terre sans nier Son élévation.',15),
   (t,c,'difficile','Pourquoi la comparaison avec la lune est-elle utilisée ?','["Pour montrer qu''une compagnie peut exister sans contact physique ni mélange","Pour prouver que la lune est divine","Pour nier toute élévation","Pour dire que le ciel est sur terre"]'::jsonb,0,'Le texte explique qu''on peut dire qu''une chose est avec nous sans qu''elle descende ni se mélange, comme la lune.',16),
   (t,c,'difficile','Pourquoi la compagnie d''Allah ne contredit-elle pas Son élévation ?','["Parce qu''Allah peut être avec Sa création par Sa science tout en restant au-dessus du Trône","Parce qu''Il doit être dans la création pour la connaître","Parce que les deux notions s''annulent","Parce qu''Allah change de lieu"]'::jsonb,0,'Le texte insiste sur le fait qu''Allah est avec Sa création par Sa science, Sa vision et Sa souveraineté, tout en restant élevé au-dessus du Trône.',17),
   (t,c,'difficile','Quelle est la position correcte face à toute expression qui implique qu''Allah est sur terre ou mélangé à Sa création ?','["La rejeter","L''accepter si elle semble simple","La garder sans examen","La considérer comme neutre"]'::jsonb,0,'Le texte dit que toute expression impliquant cela est inexacte et doit être rejetée.',18),
   (t,c,'difficile','Pourquoi l''élévation d''Allah et Sa compagnie ne doivent-elles pas être réduites à une seule idée ?','["Parce que les deux sont établies par les textes et chacune a son sens propre","Parce que seule la compagnie est vraie","Parce que seule l''élévation est vraie","Parce que les textes sont ambigus"]'::jsonb,0,'Le texte affirme que l''élévation et la compagnie sont toutes deux établies et ne se contredisent pas.',19),
   (t,c,'difficile','Quelle conclusion générale le cours tire-t-il sur les attributs d''Allah et les textes révélés ?','["Il faut affirmer ce qu''Allah et Son Messager ont affirmé et rejeter ce qui ne Lui convient pas","Il faut choisir entre Coran et Sunna","Il faut interpréter librement les termes","Il faut suspendre toute croyance sur ces sujets"]'::jsonb,0,'Le texte conclut qu''il faut attester ce qu''Allah affirme dans Son Livre ou par le discours de Son Messager et rejeter ce qui ne Lui convient pas.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',19,'Explication du terme proximité concernant Allah','13/08/2025',19) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Dans le verset « Ayant créé l''homme, Nous connaissons parfaitement les secrets de son âme. Nous sommes plus proches de lui que sa veine jugulaire » (Qāf/16), quelle est la signification correcte de la proximité mentionnée ?','["La proximité physique d''Allah envers l''individu","La proximité de la veine jugulaire envers le cœur","La proximité des anges chargés de consigner les actions de l''individu","La proximité du Prophète envers ses compagnons"]'::jsonb,2,'La proximité évoquée dans ce verset est celle des anges auprès de l''individu. Allah a assigné à chaque être humain des anges chargés d''écrire et de préserver ses actions, et le contexte des versets suivants (Qāf/17-18) le confirme explicitement.',1),
   (t,c,'facile','Quel verset immédiatement suivant Qāf/16 prouve que la proximité évoquée est celle des anges ?','["« Nous l''avons fait descendre, un Coran en langue arabe, afin que vous raisonnez » (Yūsuf/2)","« Lorsque Nous te le lisons, contente-toi donc d''en suivre la récitation » (al-Qiyāma/18)","« Nous sommes alors plus proches du mourant que vous sans que vous vous en aperceviez » (al-Wāqiʿa/85)","« Au moment où les deux anges, l''un posté sur sa droite, l''autre sur sa gauche, recueillent ses moindres faits et gestes » (Qāf/17)"]'::jsonb,3,'Dans la parole d''Allah « Quand les deux recueillants » (Qāf/17), c''est une preuve que la signification est la proximité des deux anges recueillants. Le contexte des versets (Qāf/16-18) montre qu''Allah mentionne clairement la présence de deux anges à proximité de l''homme.',2),
   (t,c,'facile','Dans le verset « Nous sommes alors plus proches du mourant que vous sans que vous vous en aperceviez » (al-Wāqiʿa/85), à quelle situation la proximité est-elle limitée ?','["À la situation de l''agonie et de la sortie de l''âme","À la situation de la prière","À la situation du pèlerinage","À la situation de la naissance"]'::jsonb,0,'La proximité dans ce verset est limitée à la situation d''agonie. Ceux qui sont présents lors de la mort sont les anges, en raison de la parole d''Allah : « Et lorsque la mort atteint l''un de vous, Nos messagers (les Anges) enlèvent son âme sans aucune négligence » (al-Anʿām/61).',3),
   (t,c,'facile','Pourquoi est-il impossible qu''Allah soit Lui-même physiquement proche dans les versets de Qāf/16 et al-Wāqiʿa/85 ?','["Parce que les anges sont plus puissants qu''Allah dans ces situations","Parce qu''Allah est installé sur Son Trône, séparé de Sa création, et rien de Sa création ne réside en Lui","Parce que ces versets sont abrogés par d''autres versets","Parce que la langue arabe interdit cette signification pour les versets coraniques"]'::jsonb,1,'Cette proximité implique une présence au sein de la création. Or, Allah est installé sur Son Trône, séparé de Sa création, rien d''elle ne réside en Lui. Il est donc impossible que la proximité mentionnée soit celle d''Allah Lui-même.',4),
   (t,c,'facile','Pourquoi Allah s''attribue-t-Il la proximité des anges dans les versets concernés ?','["Parce qu''Allah veut nier Sa propre proximité envers les créatures","Parce que la langue arabe exige cette formulation dans ce contexte particulier","Parce qu''Allah et les anges sont une seule et même entité","Parce que leur proximité vient de Son commandement et ils sont Son armée et Ses émissaires"]'::jsonb,3,'Allah a annexé la proximité des anges auprès de Lui parce que leur proximité vient de Son commandement et ils sont Son armée et Ses émissaires. Tout ce qui s''accomplit sous Son ordre peut Lui être attribué.',5),
   (t,c,'facile','Le verset « Lorsque Nous te le lisons, contente-toi donc d''en suivre la récitation » (al-Qiyāma/18) illustre qu''Allah peut s''attribuer un acte accompli sous Son ordre. Qui effectuait réellement cette récitation ?','["Jibrīl, par commandement d''Allah","Le Prophète lui-même lors de la révélation","Les compagnons du Prophète lors de la transcription","Les anges recueillants chargés de consigner les révélations"]'::jsonb,0,'Ce qu''est voulu c''est la lecture de Jibrīl du Coran au Prophète, bien qu''Allah Se soit attribué cette lecture, car Jibrīl lisait par commandement d''Allah, il est donc correct de l''attribuer à Lui.',6),
   (t,c,'facile','Dans le verset « Abraham se mit à implorer Notre clémence en faveur du peuple de Loth » (Hūd/74), avec qui Ibrāhīm discutait-il en réalité ?','["Avec son peuple qui refusait la foi","Avec Allah directement, face à face","Avec les anges envoyés par Allah","Avec les prophètes de son époque"]'::jsonb,2,'Ibrāhīm débattait avec les anges qui sont les émissaires d''Allah. Allah s''attribue leurs actes parce qu''ils agissaient sur Son ordre, d''où l''usage du terme « Nous » dans le verset.',7),
   (t,c,'facile','Le hadith « Le moment où le serviteur est le plus proche de Son Seigneur est lorsqu''il se trouve en prosternation. Multipliez donc les invocations à ce moment-là ! » est rapporté par quel recueil ?','["Al-Bukhārī dans le livre de la délicatesse","Muslim, Riyāḍ al-Ṣāliḥīn n°1498","Abū Dāwūd dans le livre des prières","al-Tirmidhī dans le livre des vertus"]'::jsonb,1,'Dans un hadith, le Prophète mentionne : « Le moment où le serviteur est le plus proche de Son Seigneur est lorsqu''il se trouve en prosternation. Multipliez donc les invocations à ce moment-là ! » [Muslim, Riyāḍ al-Ṣāliḥīn n°1498].',8),
   (t,c,'facile','Quelle est la compréhension correcte du verset « Qui voguait sous Nos Yeux » (al-Qamar/14) concernant l''arche de Nūḥ ?','["L''arche se trouvait physiquement dans l''œil d''Allah","L''arche était guidée par Jibrīl sans rapport avec le regard divin","L''arche voguait sans aucune intervention divine particulière","L''arche voguait sous le regard, la surveillance et la protection d''Allah"]'::jsonb,3,'La deuxième éventualité, qui est la correcte, consiste à comprendre que l''arche de Nūḥ voguait sous le regard, la surveillance et la protection d''Allah. Cette compréhension respecte la distinction entre Allah et Sa création et exprime correctement la proximité de protection.',9),
   (t,c,'facile','Dans quel livre et chapitre al-Bukhārī rapporte-t-il le hadith sacré commençant par « Mon serviteur ne cesse de se rapprocher de Moi avec des actions surérogatoires... » ?','["Dans le livre de la délicatesse, les trente-huitièmes chapitres : la modestie","Dans le livre de la prière, chapitre de la prosternation","Dans le livre du jihad, chapitre de la récompense","Dans le livre du pèlerinage, chapitre des rites"]'::jsonb,0,'Ce hadith est authentique rapporté par l''Imam al-Bukhārī dans le livre de la délicatesse, les trente-huitièmes chapitres : la modestie.',10),
   (t,c,'moyenne','Quels sont les deux types de proximité qu''il convient de distinguer dans l''étude des attributs d''Allah ?','["La proximité physique et la proximité métaphorique seulement","La proximité des créatures envers Allah, et la proximité d''Allah envers les créatures (générale ou particulière)","La proximité des prophètes et celle des anges uniquement","La proximité dans cette vie uniquement et la proximité dans l''au-delà uniquement"]'::jsonb,1,'Il convient de distinguer deux types de proximité : la proximité des créatures envers Allah, et la proximité d''Allah envers les créatures, qui peut être générale ou particulière. Il faut affirmer cela tout en rejetant l''interprétation qui fait d''Allah un être physiquement mêlé à Sa création.',11),
   (t,c,'moyenne','Quel est le sens correct du hadith sacré « Je suis l''ouïe avec laquelle il entend, la vue avec laquelle il voit » selon les prédécesseurs (Traditionnistes) ?','["Allah oriente le pieux dans son écoute et son regard de sorte que ses perceptions seront pour Allah, par Allah et en Allah, sans mélange entre le Créateur et la créature","Allah se mélange à Sa créature et devient réellement ses membres","Le serviteur pieux acquiert les attributs divins après s''être rapproché d''Allah","Allah remplace les membres du serviteur par des membres angéliques lors de la prosternation"]'::jsonb,0,'Le sens correct est qu''Allah oriente ce pieux dans son écoute, son regard, son agissement, son cheminement, de sorte que sa perception et son œuvre seront vouées sincèrement à Allah, pour Allah la demande d''aide, et en Allah dans les préceptes et l''obéissance. C''est cela que les prédécesseurs avaient compris.',12),
   (t,c,'moyenne','Quel argument linguistique réfute l''idée que l''arche de Nūḥ se trouvait physiquement dans l''œil d''Allah dans le verset « Qui voguait sous Nos Yeux » (al-Qamar/14) ?','["Le mot arabe pour « œil » ne peut désigner qu''une métaphore dans le Coran","Le Coran ne mentionne jamais les yeux d''Allah dans d''autres versets","En langue arabe, « avancer sous mon regard » signifie être sous la surveillance, non dans l''œil du locuteur ; celui qui prétend le contraire est moqué par les gens sensés","La langue arabe interdit d''employer le pluriel pour désigner un attribut d''Allah"]'::jsonb,2,'Personne ne comprend de la déclaration « untel avance sous mon regard » que la signification est qu''il avance dans son œil. Si un individu prétend que c''est cela le sens apparent, les ignorants se moqueront de lui, outre les hommes sensés.',13),
   (t,c,'moyenne','La proximité en prosternation évoquée dans le hadith de Muslim (Riyāḍ al-Ṣāliḥīn n°1498) est-elle physique ou spirituelle, et pourquoi ?','["Elle est physique, car le serviteur descend vers le sol en direction d''Allah","Elle est physique, car Allah descend vers le serviteur lors de la prosternation","Elle est inexistante ; ce hadith est mal compris par les étudiants","Elle est spirituelle et non physique, car Allah reste élevé au-dessus de toute chose et n''est pas mêlé à Sa création"]'::jsonb,3,'En prosternation, le serviteur se trouve dans un état de proximité avec Allah ; toutefois, cette proximité est spirituelle et non physique. De même, certaines créatures peuvent être plus proches d''Allah que d''autres, comme le Prophète lors de son ascension.',14),
   (t,c,'moyenne','Quel verset est invoqué pour justifier que les expressions coraniques sur la proximité et les yeux d''Allah doivent être comprises selon l''usage de la langue arabe ?','["« Rien ne Lui ressemble, et c''est Lui l''Audient, le Voyant » (al-Shūrā/11)","« Nous l''avons fait descendre, un Coran en langue arabe, afin que vous raisonnez » (Yūsuf/2)","« Je n''ai créé les djinns et les hommes que pour qu''ils M''adorent » (al-Dhāriyāt/56)","« Allah ne vous impose rien au-delà de vos capacités » (al-Baqara/286)"]'::jsonb,1,'Allah déclare : « Nous l''avons fait descendre, un Coran en langue arabe, afin que vous raisonnez » (Yūsuf/2). Le Coran étant en langue arabe, les expressions doivent être comprises selon l''usage normal de cette langue, sans en dévier vers une interprétation forcée.',15),
   (t,c,'difficile','Certains interprétistes affirment qu''il faut falsifier le sens des versets de Qāf/16 et al-Wāqiʿa/85 pour éviter d''attribuer à Allah une proximité impossible. Quelle est la réfutation correcte de cette position ?','["Il faut effectivement falsifier ces versets car leur sens apparent est impossible","Ces versets n''ont aucun sens précis et doivent être laissés sans explication","Ces versets doivent être réservés aux savants uniquement et non enseignés au grand public","Ces versets n''ont pas besoin d''être falsifiés : leur sens apparent, compris à la lumière du contexte et des versets environnants, désigne clairement la proximité des anges et non d''Allah Lui-même"]'::jsonb,3,'L''interprétation de la proximité dans les deux versets par la proximité des anges n''est pas une déviation du sens apparent du discours pour celui qui médite dessus. Il suffit de les comprendre selon leur sens apparent en s''appuyant sur le contexte et les versets environnants, sans recourir à une falsification.',16),
   (t,c,'difficile','Certains ont interprété le hadith sacré comme signifiant qu''Allah devient réellement l''ouïe du serviteur pieux. Quel argument interne au hadith lui-même contredit cette compréhension ?','["Le hadith établit clairement deux entités distinctes : un serviteur qui se rapproche et Allah vers qui on se rapproche, un aimant et un aimé, un demandeur et un protecteur — ce qui empêche que la description de l''un soit celle de l''autre","Le hadith est trop court pour être correctement interprété sans sources extérieures","Le hadith ne mentionne pas l''ouïe ni la vue dans sa version la plus authentique","Le contexte du hadith se limite aux obligations et non aux actes surérogatoires"]'::jsonb,0,'Dans le hadith, Allah a affirmé la présence d''un serviteur et d''un adoré, d''un qui se rapproche et l''autre vers qui on se rapproche, d''un aimant et d''un aimé, d''un demandeur et d''un demandé. Le contexte du hadith indique la présence de deux entités distinctes, ce qui empêche que la description de l''un soit celle de l''autre.',17),
   (t,c,'difficile','Pourquoi est-il inconcevable de comprendre le hadith sacré comme signifiant qu''Allah serait devenu l''ouïe, la vue ou le pied d''un serviteur créé ?','["Parce que l''ouïe et la vue ne sont pas des attributs mentionnés pour Allah dans le Coran","Parce qu''Allah est le Créateur originel qui n''est précédé de rien, et il est impossible pour tout doué de raison de concevoir que ce Créateur soit l''audition ou le pied d''un être créé après Lui — une telle pensée fait frémir l''esprit","Parce que les prédécesseurs ont unanimement interdit de méditer sur ce hadith","Parce que ce hadith est considéré comme faible et ne peut pas fonder une croyance"]'::jsonb,1,'L''audition du pieux, sa vue, sa main, son pied sont des qualificatifs d''un être créé, nouveau après n''avoir rien été. Il est impossible pour tout doué de raison de comprendre que le Créateur originel, qui n''est précédé de rien, soit l''audition, la vue ou le pied d''un être créé après Lui. Cette compréhension, quand on l''imagine, fait frémir l''esprit et la langue se rétracte à la prononcer.',18),
   (t,c,'difficile','La première éventualité — l''arche dans l''œil d''Allah ou Mūsā éduqué sur l''œil d''Allah — est réfutée par deux arguments. Quel est le deuxième argument, de nature théologique ?','["La langue arabe interdit l''usage du pluriel pour désigner un attribut d''Allah","Les versets concernés sont trop anciens pour être interprétés littéralement","Allah est installé sur Son Trône, séparé de Sa création ; rien de la création ne réside en Lui, ce qui rend impossible qu''une créature se mêle à Son Essence","Les anges n''ont aucun rôle dans la protection de l''arche selon les autres versets"]'::jsonb,2,'Le second argument est théologique : ceci est complètement impossible, et il est impensable que celui qui connaît Allah et Le considère correctement comprenne cela. Car Allah est installé sur Son Trône, séparé de Sa création, rien d''elle ne réside en Lui, et Il n''est dans aucune chose de Sa création, gloire à Lui.',19),
   (t,c,'difficile','En quoi le sens correct du verset « afin que tu sois élevé sous Mes Yeux » (Ṭāhā/39) confirme-t-il nécessairement l''attribut de la vue divine, et comment ce lien est-il articulé ?','["Le verset prouve qu''Allah se déplace physiquement vers ce qu''Il protège, confirmant une proximité spatiale","Le verset signifie que la vue d''Allah est identique à celle des anges dans cette situation particulière","Si Allah protège Mūsā de Son regard, cela exige qu''Il le voie, car le sens correct doit inclure son implication par correspondance, inclusion ou implication — ce qui confirme l''attribut de la vue sans impliquer de mélange avec la création","Le sens est purement allégorique et ne confirme aucun attribut réel à Allah"]'::jsonb,2,'Si Allah protège de Son regard, cela exige qu''Il voie, car le sens correct et nécessaire doit être une partie de lui, comme il est connu dans la signification des mots, qui est par correspondance, ou inclusion, ou implication. Allah a affirmé l''existence de la vue et des yeux, et le fait qu''Il voit sous Son regard le confirme sans impliquer aucun mélange avec Sa création.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',20,'La mauvaise compréhension peut mener à la déviation','08/09/2025',20) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Dans quel livre l''Imam Muslim a-t-il rapporté le hadith qudsî « quiconque se rapproche de Moi d''un pas, Je me rapproche de lui d''une coudée » selon Abou Dhar ?','["Le livre de la prière, chapitre de la prosternation","Le livre du rappel et de l''invocation","Le livre de l''unicité, le quinzième chapitre","Le livre du jeûne, chapitre de la nuit"]'::jsonb,1,'Ce hadith est authentique, rapporté par l''Imam Muslim dans le livre du rappel et de l''invocation, selon Abou Dhar, et selon Abou Hourayra presque similaire.',1),
   (t,c,'facile','Qu''est-ce qu''un hadith qudsî ?','["Un hadith dont la chaîne de transmission remonte uniquement aux Compagnons","Un hadith dans lequel le Prophète rapporte une parole d''Allah","Un hadith faible dont l''authenticité est disputée","Un hadith rapporté exclusivement par Al-Bukhārī"]'::jsonb,1,'Il s''agit d''un hadith qudsî, car c''est le Prophète qui rapporte une parole d''Allah.',2),
   (t,c,'facile','Selon le hadith rapporté par Al-Bukhārī (n° 7405) et Muslim (n° 2675), que fait Allah lorsque Son serviteur vient à Lui en marchant ?','["Il lui accorde une récompense double","Il l''oublie s''il est lent","Il Se hâte vers lui","Il lui envoie un ange"]'::jsonb,2,'Selon le hadith : « Lorsqu''il vient vers Moi en marchant, Je Me hâte vers lui. »',3),
   (t,c,'facile','Quelle secte affirme que les actes volontaires ne proviennent pas d''Allah mais qu''ils sont anciens, et que le Coran aurait été prononcé avant la création des cieux et de la terre ?','["Les Jahmiyya","Les Muʿtazila","Les Ashāʿira","Les Mufawwiḍah"]'::jsonb,2,'Les Ashāʿira se sont égarés sur ce point, car ils disent que les actes volontaires ne proviennent pas d''Allah mais qu''ils sont anciens, et que par exemple le Coran aurait été prononcé avant la création des cieux et de la terre.',4),
   (t,c,'facile','Que prouve le fait qu''Allah ait révélé successivement la Tawrāt, puis l''Injīl, puis le Coran verset après verset ?','["Que les actes d''Allah se produisent à des moments précis selon Sa volonté","Que le Coran est moins important que la Tawrāt","Que les actes d''Allah sont tous anciens et éternels","Que la révélation s''est faite en une seule fois"]'::jsonb,0,'La révélation s''est faite progressivement, ce qui montre clairement que les actes d''Allah se produisent selon Sa volonté et à des moments précis.',5),
   (t,c,'facile','Selon le hadith cité, à quel moment le serviteur est-il le plus proche d''Allah dans la prière ?','["Lors de la récitation debout","Lors de l''inclinaison","Lors des salutations finales","Lors de la prosternation"]'::jsonb,3,'Le Prophète a dit : « le serviteur est le plus proche d''Allah lorsqu''il est prosterné ».',6),
   (t,c,'facile','Dans le treizième exemple, quel verset est examiné pour distinguer deux sens possibles de la création par les mains d''Allah ?','["« Tout malheur qui vous a touché est dû à ce que vos mains ont acquis » (Ach-Chūrā/30)","« Ne voient-ils donc pas que, parmi ce que Nos mains ont fait, Nous leur avons créé des bestiaux dont ils sont propriétaires » (Yāsīn/71)","« Ô Iblīs, qui t''a empêché de te prosterner devant ce que J''ai créé de Mes mains ? » (Ṣād/75)","« La corruption est apparue sur la terre et dans la mer à cause de ce que les gens ont accompli de leurs propres mains » (Ar-Rūm/41)"]'::jsonb,1,'Le treizième exemple porte sur le verset : « Ne voient-ils donc pas que, parmi ce que Nos mains ont fait, Nous leur avons créé des bestiaux dont ils sont propriétaires » (Yāsīn/71).',7),
   (t,c,'facile','Quelle est la particularité de la création d''Adam par rapport à toutes les autres créatures selon le cours ?','["Adam a été créé à partir de l''eau uniquement","Adam a été créé par la parole divine comme toutes les autres créatures","Adam a été créé de la main d''Allah, ce qui est une particularité propre à lui","Adam a été créé de la même manière que les bestiaux"]'::jsonb,2,'Allah a créé Adam de Ses mains, ce qui est une particularité propre à Adam. Pour les autres créations, Allah n''a pas dit « avec Mes mains ».',8),
   (t,c,'facile','Que signifie l''expression « ce que vos mains ont accompli » dans des versets comme « Tout malheur qui vous a touché est dû à ce que vos mains ont acquis » (Ach-Chūrā/30), selon la langue arabe ?','["Uniquement les actions réalisées avec les mains au sens physique","Toutes les actions de la personne, quel que soit le membre utilisé","Les actions accomplies dans un état de pureté rituelle","Exclusivement les mauvaises actions intentionnelles"]'::jsonb,1,'Ces exemples montrent que l''expression « mains » désigne ce qu''un individu accomplit par lui-même, même si ce n''est pas littéralement avec ses mains.',9),
   (t,c,'facile','Quel ouvrage de Cheikh al-Islam est cité à propos de la doctrine des pieux prédécesseurs sur les actes volontaires d''Allah ?','["Le traité de la foi islamique","La réponse aux philosophes","Le livre des réfutations des innovations","Le commentaire du hadith de Djibril, dans la compilation des Fatwas (V5/p466)"]'::jsonb,3,'Cheikh al-Islam dit dans son ouvrage Le commentaire du hadith de Djibril, dans la compilation des Fatwas (V5/p466) : « Concernant Sa proximité et Son rapprochement de certaines créatures, cela est reconnu par ceux qui attestent des actions volontaires accomplies par Allah Lui-même… »',10),
   (t,c,'moyenne','Quelle preuve coranique des actes volontaires d''Allah est tirée du verset « À ceux de Mes serviteurs qui t''interrogent sur Moi, réponds que Je suis tout proche » (Al-Baqarah/186) ?','["Allah répond aux invocations avant même la création du serviteur, prouvant Son omniscience","Allah répond au moment où le serviteur L''invoque, prouvant que Sa réponse est un acte accompli à un moment précis selon Sa volonté","Allah démontre que Sa proximité est purement métaphorique et ne concerne que Sa science","Allah indique que Ses serviteurs peuvent L''atteindre par leurs propres efforts sans aide divine"]'::jsonb,1,'Allah répond au moment où le serviteur L''invoque, et non avant sa création ni avant la création des cieux et de la terre. Cela montre que c''est un acte volontaire accompli à un moment précis.',11),
   (t,c,'moyenne','Quelle règle s''applique face aux questions du type « comment Allah peut-Il descendre au dernier tiers de la nuit alors que les fuseaux horaires sont différents ? » ?','["Il faut chercher une explication rationnelle compatible avec les données scientifiques","Il faut rejeter le hadith s''il semble impossible à comprendre","Il faut interpréter le hadith de manière allégorique pour lever la difficulté","Les questions du « comment » sont interdites concernant les noms et attributs d''Allah ; on comprend le hadith selon son sens apparent"]'::jsonb,3,'Les questions du « comment » sont interdites concernant les noms et attributs d''Allah. On ne cherche pas à savoir comment cela se passe ou comment cela est possible, car Allah fait ce qu''Il veut, rien ne Lui est impossible et Il englobe toute chose.',12),
   (t,c,'moyenne','Pourquoi la première éventualité — selon laquelle Allah aurait créé les bestiaux avec Sa main comme Il a créé Adam — est-elle réfutée par une raison linguistique tirée du verset de Ṣād/75 ?','["Parce que le mot « bestiaux » ne peut pas être associé aux mains en arabe classique","Parce que si Allah avait voulu ce sens, le verset de Yāsīn/71 aurait utilisé la particule « bi » (avec) annexée à la main, comme dans le verset de Ṣād/75 pour Adam","Parce que les bestiaux sont inférieurs à Adam et ne méritent pas cette mention","Parce que le verset de Yāsīn parle exclusivement des bienfaits matériels accordés aux hommes"]'::jsonb,1,'Si le sens voulu avait été qu''Allah a créé les bestiaux avec Sa main, le verset aurait été formulé autrement : « Nous avons créé pour eux des bestiaux avec Nos mains », comme Allah l''affirme concernant Adam dans Ṣād/75. L''absence de la particule « bi » change le sens.',13),
   (t,c,'moyenne','Comment le verset « Le Tout Miséricordieux, qui s''est élevé sur le Trône en toute majesté » (Tāhā/5) et le hadith rapporté par Al-Bukhārī selon ''Imrân ibn Husayn prouvent-ils ensemble que l''istiwāʾ est un acte volontaire d''Allah ?','["Ils prouvent que le Trône est éternel et qu''Allah l''a toujours occupé","Ils prouvent que le Trône est une métaphore de la puissance divine","Avant la création de toute chose, le Trône était au-dessus de l''eau ; puis Allah a créé les cieux et la terre, et l''istiwāʾ s''est fait après, montrant qu''il s''agit d''un acte volontaire à un moment précis","Ils prouvent que l''istiwāʾ est identique à la descente au dernier tiers de la nuit"]'::jsonb,2,'Allah était et rien d''autre que Lui n''existait, et Son Trône était sur l''eau. Cela montre que l''établissement sur le Trône s''est fait après la création, et donc que c''est un acte volontaire d''Allah qui agit selon Sa volonté.',14),
   (t,c,'moyenne','Quelle est la position de la voie des pieux prédécesseurs face aux textes affirmant les actes d''Allah comme Sa venue, Sa descente et Son établissement sur le Trône ?','["Les affirmer dans leur sens apparent, sans nier, sans chercher le « comment » et sans faire d''assimilation avec les créatures","Les interpréter de manière allégorique pour écarter tout anthropomorphisme possible","Les déléguer à Allah en suspendant tout jugement sur leur sens réel","Les accepter uniquement s''ils sont confirmés par la raison et la philosophie"]'::jsonb,0,'Les prédécesseurs, les gens de la Sunna abordent ces textes dans leur sens apparent, conformément à la réalité de leur signification convenable à Allah, sans chercher à déterminer le comment, ni à faire d''assimilation.',15),
   (t,c,'difficile','Quel raisonnement erroné a conduit certaines sectes à nier les actes volontaires d''Allah, malgré les preuves claires du Coran et de la Sunna ?','["Elles ont pensé que les actes volontaires impliquent quelque chose de nouveau, que ce qui est nouveau serait un corps, or Allah n''a ni corps ni semblable ; elles ont donc nié que les actes volontaires proviennent d''Allah","Elles ont affirmé que les actes volontaires contredisent la toute-puissance d''Allah car ils L''obligent à agir","Elles ont cru que reconnaître les actes volontaires implique de croire que Allah change et est donc imparfait","Elles ont pensé que seuls les attributs essentiels d''Allah sont authentiques, non les actes"]'::jsonb,0,'Ces sectes ont pensé que les actes volontaires impliquent quelque chose de « nouveau », et que ce qui est nouveau serait un corps, or Allah n''a ni corps ni semblable. À cause de ce raisonnement, elles ont fini par nier que les actes volontaires proviennent d''Allah, alors que le Coran et la Sunna prouvent clairement le contraire.',16),
   (t,c,'difficile','Quelle nuance grammaticale distingue le verset « Malheur à ceux qui de leurs propres mains composent un livre » (Al-Baqarah/79) des versets tels que « Tout malheur qui vous a touché est dû à ce que vos mains ont acquis » (Ach-Chūrā/30) ?','["Dans Al-Baqarah/79, la main est annexée à l''action par la particule « bi », indiquant que l''action est accomplie directement avec la main ; dans Ach-Chūrā/30, la construction désigne l''auteur sans préciser le moyen","Dans Al-Baqarah/79, la main est purement métaphorique, tandis que dans Ach-Chūrā/30 elle est littérale","Les deux versets signifient exactement la même chose et illustrent la même règle grammaticale","Dans Ach-Chūrā/30, la main désigne la puissance divine, tandis que dans Al-Baqarah/79 elle est purement symbolique"]'::jsonb,0,'Contrairement à lorsqu''Allah dit : « Malheur à ceux qui de leurs propres mains composent un livre », où la main indique l''action directement, dans d''autres versets l''annexion de l''action à la main désigne simplement l''auteur de l''action. Distinguer ces nuances dissipe beaucoup de problèmes.',17),
   (t,c,'difficile','Un savant interprète « Je Me hâte vers lui » dans le hadith qudsî comme désignant uniquement la rapidité de la récompense divine et l''assistance d''Allah. Quelle est la position correcte à adopter face à cette interprétation ?','["La rejeter entièrement car elle constitue une déviance semblable à celle des négationnistes","Ce sens lié à la récompense est acceptable s''il est appuyé par un indicateur religieux, mais le premier avis — affirmant le sens apparent de la venue et de la proximité d''Allah — est plus clair et plus conforme à la doctrine des prédécesseurs","L''accepter entièrement car elle préserve de l''anthropomorphisme","La considérer comme la seule interprétation valide selon les gens de la Sunna"]'::jsonb,1,'Ce sens reste acceptable s''il est appuyé par un indicateur religieux, et dans ce cas, ce n''est pas une déviation du sens, ni une interprétation semblable à celle des négateurs. Cependant, le premier avis est plus clair, plus sain, et plus approprié à la doctrine des prédécesseurs.',18),
   (t,c,'difficile','Pourquoi l''argument de ceux qui limitent le sens du hadith « celui qui vient à Moi en marchant » à la seule marche physique est-il réfuté ?','["Parce que la marche physique n''a aucune valeur spirituelle reconnue en Islam","Parce que seuls les hadiths mutawātir peuvent établir des règles sur la récompense divine","Parce que la dévotion pour Allah n''est pas restreinte à la marche : le hadith donne un exemple sans restriction, et le serviteur se rapproche d''Allah aussi par la prière, la prosternation et toute adoration sincère","Parce que le hadith ne concerne que le pèlerinage et la circumambulation autour de la Kaʿba"]'::jsonb,2,'On réfute ce qu''il a établi comme preuve : la dévotion pour Allah et la recherche de se rapprocher de Lui ne sont pas restreintes à la marche. Le hadith donne un exemple sans restriction. Le serviteur se rapproche aussi par la prière, l''inclinaison et la prosternation.',19),
   (t,c,'difficile','Quelle est l''implication du principe selon lequel le Coran est descendu avec clarté — « Nous avons fait descendre sur toi le Livre, comme un exposé explicite de toute chose » (An-Naḥl/89) — pour réfuter la première éventualité dans le verset de Yāsīn/71 ?','["Si Allah avait voulu dire qu''Il a créé les bestiaux avec Ses mains comme Adam, Il l''aurait formulé clairement avec la particule « bi » ; l''absence de cette formulation précise prouve que ce n''est pas le sens voulu","Ce principe montre que tous les versets ambigus doivent être interprétés de manière allégorique","Ce principe implique que la langue arabe est insuffisante pour exprimer les attributs d''Allah","Ce principe prouve que le verset de Yāsīn/71 est équivalent dans son sens au verset de Ṣād/75 sur la création d''Adam"]'::jsonb,0,'Le Coran est descendu avec clarté et non en camouflage. Si le sens voulu avait été qu''Allah a créé les bestiaux avec Sa main, le verset aurait été formulé autrement, par exemple : « Nous avons créé pour eux des bestiaux avec Nos mains », comme pour Adam dans Ṣād/75.',20);
 insert into quiz_courses(tenant_id,subject,number,title,course_date,position) values (t,'Qawaid al-Muthla',21,'Le sens du terme Annexion','14/09/2025',21) returning id into c;
 insert into quiz_questions(tenant_id,course_id,difficulte,question,options,correct_index,justification,position) values
   (t,c,'facile','Que comprend le verset : « Ceux qui te prêtent serment d''allégeance ne font que prêter serment à Allah » (La Victoire éclatante/10) ?','["Deux phrases","Une seule phrase","Trois phrases","Aucune phrase distincte"]'::jsonb,0,'Le texte dit clairement que ce verset comprend deux phrases.',1),
   (t,c,'facile','Que montre la première phrase du verset : « Ceux qui te prêtent serment d''allégeance ne font que prêter serment à Allah » (La Victoire éclatante/10) ?','["Que les Compagnons ont prêté allégeance directement à Allah","Que les Compagnons ont prêté allégeance au Prophète en personne","Que l''allégeance n''a eu lieu qu''en rêve","Que le serment n''avait aucune valeur"]'::jsonb,1,'Le texte explique que les Compagnons prêtèrent allégeance au Prophète en personne, et non directement à Allah.',2),
   (t,c,'facile','Pourquoi l''allégeance au Messager revient-elle à l''allégeance à Allah ?','["Parce qu''il est le plus âgé des Compagnons","Parce qu''il est Son Messager","Parce qu''il remplace la Révélation","Parce que le serment était seulement symbolique"]'::jsonb,1,'Le texte dit que l''allégeance au Messager revient à l''allégeance à Allah parce qu''il est Son Messager.',3),
   (t,c,'facile','Que montre la parole : « Quiconque obéit au Messager obéit certainement à Allah » (Les Femmes/80) ?','["Que l''obéissance au Messager est indépendante de celle d''Allah","Que l''obéissance au Messager revient à obéir à Allah","Que l''obéissance ne concerne que les croyants","Que le Messager reçoit une obéissance nouvelle"]'::jsonb,1,'Le texte cite ce verset pour montrer que l''obéissance au Messager est une obéissance à Celui qui l''a envoyé.',4),
   (t,c,'facile','Que signifie le verset : « La Main d''Allah est au-dessus de leurs mains » (La Victoire éclatante/10) ?','["La Main d''Allah est au-dessus des mains des allégeants","La Main du Prophète est au-dessus de leurs mains","Les Compagnons ont touché la main d''Allah","Il n''y a ici aucune affirmation réelle"]'::jsonb,0,'Le texte affirme que la Main d''Allah est au-dessus de la main des allégeants, tout en restant séparée de la création.',5),
   (t,c,'facile','Quel type d''annexion sert à montrer l''honneur, l''importance ou le rang élevé d''une créature ?','["L''annexion d''un attribut à Allah","L''annexion d''une créature à Allah","L''annexion d''un verbe au sujet","L''annexion d''un nom à une autre créature"]'::jsonb,1,'Le texte distingue l''annexion d''une créature à Allah, qui sert à montrer l''honneur, l''importance ou le rang particulier de cette créature.',6),
   (t,c,'facile','Que signifie la phrase : « J''étais malade et tu ne M''as pas visité » ?','["Que la maladie appartient réellement à Allah","Que la maladie concerne le serviteur","Que le malade n''existait pas","Que la visite n''était pas recommandée"]'::jsonb,1,'Le texte dit qu''Allah a clarifié que la maladie concernait Son serviteur et non Lui-même.',7),
   (t,c,'facile','Que signifie l''expression : « Quiconque prête à Allah un bon prêt, Il le lui multipliera plusieurs fois » (La Vache/245) ?','["Un prêt réel accordé à Allah","Une créature dans le besoin est visée, et le texte honore l''acte","Une obligation de financer les prophètes","Une interdiction de donner en aumône"]'::jsonb,1,'Le texte explique que le prêt est annexé à Allah pour en souligner le mérite, alors qu’il est en réalité accordé à une créature dans le besoin.',8),
   (t,c,'facile','Quelle est la doctrine des gens de la Sunna face aux textes des attributs ?','["Ils les interprètent tous selon la philosophie","Ils les prennent dans leur sens apparent, sans falsification, négation, recherche du comment ni assimilation","Ils en acceptent certains et en rejettent d''autres","Ils les réservent aux savants seuls"]'::jsonb,1,'Le texte conclut que la doctrine des gens de la Sunna consiste à prendre les versets et hadiths des attributs dans leur sens apparent, sans falsification, ni négation, ni recherche du comment, ni assimilation.',9),
   (t,c,'facile','Quelle est l''une des deux formes d''annexion mentionnées dans le texte ?','["L''annexion d''une créature à Allah","L''annexion d''une question au doute","L''annexion d''un doute à la croyance","L''annexion d''une créature à une autre créature"]'::jsonb,0,'Le texte énonce explicitement l''annexion d''une créature à Allah comme une des deux catégories.',10),
   (t,c,'moyenne','Pourquoi les interprétateurs ont-ils falsifié le sens de « la main d''Allah est au-dessus de leurs mains » (La Victoire éclatante/10) ?','["Parce qu''ils pensaient que le verset parlait de la pluie","Parce qu''ils croyaient que cela ne convenait pas à Allah et qu''ils voulaient éviter, selon eux, une assimilation","Parce qu''ils ne connaissaient pas le serment d''allégeance","Parce qu''ils rejetaient toute forme d''annexion"]'::jsonb,1,'Le texte dit qu''ils ont interprété ou détourné le sens afin d''éviter, selon eux, une assimilation.',11),
   (t,c,'moyenne','Pourquoi la Main d''Allah est-elle dite au-dessus des mains des allégeants sans contact ?','["Parce qu''Allah est au-dessus d''eux sur Son Trône et que l''élévation n''implique pas le contact","Parce que le Prophète avait posé sa main sur les leurs","Parce que les mains des Compagnons étaient invisibles","Parce que le verset parle seulement d''un symbole"]'::jsonb,0,'Le texte explique que la Main d''Allah est au-dessus d’eux sur Son Trône, tout en restant séparée de Sa création, comme le ciel est au-dessus de nous sans contact.',12),
   (t,c,'moyenne','Quel sens donne Allah Lui-même à la parole : « J''étais malade » dans le hadith sacré ?','["La maladie du serviteur","La maladie du Prophète","La maladie d''un ange","La maladie d''Allah"]'::jsonb,0,'Le texte précise qu’Allah a clarifié Lui-même le sens en disant : « Mon serviteur untel était malade. »',13),
   (t,c,'moyenne','Pourquoi l''annexion de la maladie, de la nourriture et de l''abreuvement à Allah n''implique-t-elle aucun besoin de Sa part ?','["Parce qu''il s''agit d''un langage coranique pour honorer l''acte et en montrer l''importance","Parce qu''Allah a besoin de la création","Parce que le hadith est faible","Parce que ces actions sont attribuées au Prophète"]'::jsonb,0,'Le texte dit qu''Allah a d''abord annexé cela à Lui-même afin d''inciter, d''honorer l''acte et d''en montrer l''importance.',14),
   (t,c,'moyenne','Quel exemple est donné pour montrer qu''une chose peut être au-dessus sans contact ?','["Le ciel est au-dessus de nous","La main est sous les mains","Le malade est dans la mosquée","Le prêt est donné à Allah"]'::jsonb,0,'Le texte dit : « le ciel est au-dessus de nous », bien qu’il soit séparé et éloigné de nous.',15),
   (t,c,'difficile','Pourquoi l''explication du hadith « J''étais malade » n''est-elle pas considérée comme une déviation du sens apparent ?','["Parce qu''Allah Lui-même a donné l''explication","Parce qu''il faut toujours détourner les textes","Parce que le sens apparent est rejeté ici","Parce que les Compagnons l''ont compris ainsi par spéculation"]'::jsonb,0,'Le texte dit que ce n’est pas une déviation, car il s’agit de l’explication donnée par l’Énonciateur Lui-même.',16),
   (t,c,'difficile','Quelle erreur est attribuée aux gens qui falsifient les textes des attributs ?','["Ils s''appuient sur des preuves du Livre et de la Sunna","Ils se contredisent et divaguent à cause de piètres ambiguïtés","Ils suivent le sens apparent du texte","Ils reviennent à l''explication prophétique"]'::jsonb,1,'Le texte reproche aux interprétistes de falsifier les textes à cause de piètres ambiguïtés sur lesquelles ils se contredisent et divaguent.',17),
   (t,c,'difficile','Pourquoi le verset de l''allégeance est-il présenté comme un honneur pour le Prophète ?','["Parce qu''il prouve qu''il est le fondateur de la foi","Parce qu''Allah a annexé l''allégeance faite au Prophète à Lui-même pour montrer la noblesse, l''importance et le rang élevé de cet acte","Parce qu''il remplace tous les autres versets","Parce que le Prophète y est nommé comme Allah"]'::jsonb,1,'Le texte dit qu’Allah annexe parfois certaines créatures ou certains actes à Lui-même afin d’en montrer la noblesse, l’importance ou le rang élevé.',18),
   (t,c,'difficile','Quelle affirmation résume la position correcte sur l''annexion d''un attribut à Allah ?','["Elle indique qu''Allah est réellement décrit par cet attribut, car un attribut ne peut exister indépendamment d''une entité","Elle veut dire qu''Allah est une créature parmi d''autres","Elle prouve seulement une métaphore sans réalité","Elle ne peut jamais concerner un attribut"]'::jsonb,0,'Le texte dit que l''annexion d''un attribut à Allah indique qu''Allah est réellement décrit par cet attribut, car un attribut ne peut exister indépendamment d’une entité.',19),
   (t,c,'difficile','Pourquoi la doctrine des gens de la Sunna face aux textes des attributs est-elle tenue pour correcte ?','["Parce qu''elle combine interprétation figurée et négation partielle","Parce qu''elle suit le sens apparent des textes sans falsification ni assimilation, et s''accorde avec l''explication donnée par Allah et Son Messager","Parce qu''elle rejette tous les textes ambigus","Parce qu''elle se fonde sur la majorité des savants"]'::jsonb,1,'Le texte conclut que la doctrine des gens de la Sunna consiste à suivre les textes tels qu’ils sont venus, sans falsification, ni négation, ni recherche du comment, ni assimilation.',20);
